  window.AAVSO_URGENT_CATALOGUE = AAVSO_URGENT_CATALOGUE;

  // ===========================================================================
  // [RU] ФОРМАТИРОВАНИЕ И ПАРСИНГ КООРДИНАТ J2000.0 (HMS / DMS ДЛЯ SEESTAR И AAVSO TARGET TOOL)
  //      И КЛАССИФИКАЦИЯ СЕКЦИЙ НАБЛЮДЕНИЙ AAVSO (AC, EP, CV, EB, SPP, LPV, YSO, HET, MISC)
  // [EN] J2000.0 SEXAGESIMAL COORDINATE FORMATTERS/PARSERS (HMS / DMS FOR SEESTAR & AAVSO TARGET TOOL)
  //      AND AAVSO OBSERVING SECTION CLASSIFIER (AC, EP, CV, EB, SPP, LPV, YSO, HET, MISC)
  // ===========================================================================
  function formatRaJ2000Hms(raDeg, useSuperscript = false) {
    const num = Number(raDeg);
    if (!Number.isFinite(num)) return "—";
    const normDeg = ((num % 360) + 360) % 360;
    const totalSec = Math.round((normDeg / 15.0) * 3600.0) % 86400;
    const hh = String(Math.floor(totalSec / 3600)).padStart(2, "0");
    const rem = totalSec % 3600;
    const mm = String(Math.floor(rem / 60)).padStart(2, "0");
    const ss = String(rem % 60).padStart(2, "0");
    if (useSuperscript) {
      return `${hh}ʰ ${mm}ᵐ ${ss}ˢ`;
    }
    return `${hh}h ${mm}m ${ss}s`;
  }
  window.formatRaJ2000Hms = formatRaJ2000Hms;

  function formatDecJ2000Dms(decDeg) {
    const num = Number(decDeg);
    if (!Number.isFinite(num)) return "—";
    const sign = num >= 0 ? "+" : "-";
    const clamped = Math.min(90, Math.abs(num));
    const totalSec = Math.round(clamped * 3600.0);
    const dd = String(Math.floor(totalSec / 3600)).padStart(2, "0");
    const rem = totalSec % 3600;
    const mm = String(Math.floor(rem / 60)).padStart(2, "0");
    const ss = String(rem % 60).padStart(2, "0");
    return `${sign}${dd}° ${mm}' ${ss}"`;
  }
  window.formatDecJ2000Dms = formatDecJ2000Dms;

  function parseRaAnyToDeg(rawVal) {
    const s = String(rawVal || "").trim();
    if (!s) return NaN;
    const hmsMatch = s.match(/^(\d{1,2})\s*(?:h|ʰ|:|\s)\s*(\d{1,2})\s*(?:m|ᵐ|:|\s)\s*(\d{1,2}(?:\.\d+)?)\s*(?:s|ˢ)?$/i);
    if (hmsMatch) {
      const h = parseFloat(hmsMatch[1]);
      const m = parseFloat(hmsMatch[2]);
      const sec = parseFloat(hmsMatch[3]);
      if (h >= 0 && h < 24 && m >= 0 && m < 60 && sec >= 0 && sec < 60) {
        return (h + m / 60.0 + sec / 3600.0) * 15.0;
      }
    }
    return parseFloat(s);
  }
  window.parseRaAnyToDeg = parseRaAnyToDeg;

  function parseDecAnyToDeg(rawVal) {
    const s = String(rawVal || "").trim();
    if (!s) return NaN;
    const dmsMatch = s.match(/^([+-]?)\s*(\d{1,2})\s*(?:°|d|:|\s)\s*(\d{1,2})\s*(?:'|′|m|:|\s)\s*(\d{1,2}(?:\.\d+)?)\s*(?:"|″|s)?$/i);
    if (dmsMatch) {
      const sign = dmsMatch[1] === "-" ? -1 : 1;
      const d = parseFloat(dmsMatch[2]);
      const m = parseFloat(dmsMatch[3]);
      const sec = parseFloat(dmsMatch[4]);
      if (d >= 0 && d <= 90 && m >= 0 && m < 60 && sec >= 0 && sec < 60) {
        return sign * (d + m / 60.0 + sec / 3600.0);
      }
    }
    return parseFloat(s);
  }
  window.parseDecAnyToDeg = parseDecAnyToDeg;

  function getStarObservingSections(item) {
    if (!item) return ["misc"];
    const pStr = String(item.priority || "");
    const tStr = String(item.type || "");
    const secs = new Set();

    // 1. Alerts/Campaigns (AC)
    if (pStr.includes("СРОЧНО") || pStr.includes("Кампания") || pStr.includes("Вспышки") || pStr.includes("Чёрная дыра") || pStr.includes("Сверхбыстрая") || pStr.includes("Световое эхо") || tStr.includes("ELL") || tStr.includes("GCAS") || tStr.includes("SDOR")) {
      secs.add("ac");
    }
    // 2. Exoplanets (EP)
    if (pStr.includes("Экзопланета") || tStr.includes("(EP") || tStr.includes("EP+")) {
      secs.add("ep");
    }
    // 3. Cataclysmic Variables (CV)
    if (tStr.includes("UG") || tStr.includes("NR") || tStr.includes("NA") || tStr.includes("NB") || tStr.includes("NC") || tStr.includes("ZAND") || pStr.includes("Новая") || pStr.includes("Симбиотическая")) {
      secs.add("cv");
    }
    // 4. Eclipsing Variables (EB)
    if (tStr.includes("EA") || tStr.includes("EB") || tStr.includes("EW") || tStr.includes("ELL") || pStr.includes("Затмения")) {
      secs.add("eb");
    }
    // 5. Short Period Pulsators (SPP)
    if (tStr.includes("DSCT") || tStr.includes("RRAB") || tStr.includes("DCEP") || pStr.includes("Эфемериды")) {
      secs.add("spp");
    }
    // 6. Long Period Variables (LPV)
    if (tStr.includes("(M)") || tStr.includes("M+") || tStr.includes("SRC") || tStr.includes("RVA") || tStr.includes("RVB") || tStr.includes("+SR") || pStr.includes("Мирида")) {
      secs.add("lpv");
    }
    // 7. Young Stellar Objects (YSO)
    if (tStr.includes("CTTS") || tStr.includes("INA") || tStr.includes("INT") || tStr.includes("(FU)") || tStr.includes("UXOR")) {
      secs.add("yso");
    }
    // 8. High Energy Targets (HET)
    if (tStr.includes("BLLAC") || tStr.includes("XN") || tStr.includes("XP") || tStr.includes("DQ") || pStr.includes("Блазар") || pStr.includes("Двойная ЧД") || pStr.includes("Чёрная дыра") || item.star === "HL CMa" || item.star === "RS Oph" || item.star === "CH Cyg" || item.star === "AG Dra") {
      secs.add("het");
    }
    // 9. Miscellaneous (Misc)
    if (tStr.includes("RCB") || tStr.includes("LRN") || tStr.includes("LBV") || tStr.includes("DIP") || secs.size === 0) {
      secs.add("misc");
    }
    return Array.from(secs);
  }
  window.getStarObservingSections = getStarObservingSections;

  const AAVSO_SECTION_BADGE_I18N = {
    ac:   { ru: "Срочно / Кампания (AC)", en: "Alert/Campaign (AC)", es: "Alerta/Campaña (AC)", de: "Alarm/Kampagne (AC)", fr: "Alerte/Campagne (AC)", zh: "警报/活动 (AC)" },
    ep:   { ru: "Экзопланеты (EP)", en: "Exoplanets (EP)", es: "Exoplanetas (EP)", de: "Exoplaneten (EP)", fr: "Exoplanètes (EP)", zh: "系外行星 (EP)" },
    cv:   { ru: "Катаклизмические (CV)", en: "Cataclysmic (CV)", es: "Cataclísmicas (CV)", de: "Kataklysmisch (CV)", fr: "Cataclysmiques (CV)", zh: "激变变星 (CV)" },
    eb:   { ru: "Затменные (EB)", en: "Eclipsing (EB)", es: "Eclipsantes (EB)", de: "Bedeckung (EB)", fr: "Éclipses (EB)", zh: "食变星 (EB)" },
    spp:  { ru: "Короткопериод. (SPP)", en: "Short Period (SPP)", es: "Corto Período (SPP)", de: "Kurzperiodisch (SPP)", fr: "Courte Période (SPP)", zh: "短周期脉动 (SPP)" },
    lpv:  { ru: "Долгопериод. (LPV)", en: "Long Period (LPV)", es: "Largo Período (LPV)", de: "Langperiodisch (LPV)", fr: "Longue Période (LPV)", zh: "长周期变星 (LPV)" },
    yso:  { ru: "Молодые звёзды (YSO)", en: "Young Stellar (YSO)", es: "Estrellas Jóvenes (YSO)", de: "Junge Sterne (YSO)", fr: "Jeunes Étoiles (YSO)", zh: "年轻恒星体 (YSO)" },
    het:  { ru: "Выс. энергии (HET)", en: "High Energy (HET)", es: "Alta Energía (HET)", de: "Hochenergie (HET)", fr: "Haute Énergie (HET)", zh: "高能天体 (HET)" },
    misc: { ru: "Прочие (Misc)", en: "Miscellaneous", es: "Misceláneos", de: "Sonstige (Misc)", fr: "Divers (Misc)", zh: "其他目标 (Misc)" }
  };

  function getStarObservingSectionLabel(item, langCode) {
    const lg = langCode || (typeof currentLang !== "undefined" ? currentLang : "ru");
    const secs = getStarObservingSections(item);
    // Prioritize specific section if user filtered by a specific section, otherwise show primary section
    let primary = secs[0] || "ac";
    if (typeof currentRadarFilter === "string" && currentRadarFilter !== "all" && secs.includes(currentRadarFilter)) {
      primary = currentRadarFilter;
    } else if (secs.includes("ep")) {
      primary = "ep";
    } else if (secs.includes("yso")) {
      primary = "yso";
    } else if (secs.includes("het") && (String(item.type || "").includes("BLLAC") || String(item.type || "").includes("XN"))) {
      primary = "het";
    } else if (secs.includes("ac")) {
      primary = "ac";
    }
    const map = AAVSO_SECTION_BADGE_I18N[primary] || AAVSO_SECTION_BADGE_I18N.ac;
    return map[lg] || map.en;
  }
  window.getStarObservingSectionLabel = getStarObservingSectionLabel;

  // Хранилище выбранных секций наблюдений AAVSO Target Tool (синхронизировано между #v6RadarDock и #urgentStarsModal)
  let activeObservingSections = new Set(["all"]);
  window._activeObservingSections = activeObservingSections;

  function matchesObservingSectionFilter(item, filterCodeOrSet) {
    if (!item) return false;
    const itemSecs = getStarObservingSections(item);
    if (filterCodeOrSet instanceof Set) {
      if (filterCodeOrSet.size === 0 || filterCodeOrSet.has("all")) return true;
      for (const s of filterCodeOrSet) {
        if (itemSecs.includes(s)) return true;
      }
      return false;
    }
    const f = String(filterCodeOrSet || "all").toLowerCase();
    if (!f || f === "all") return true;
    if (itemSecs.includes(f)) return true;

    // Legacy filter key compatibility
    const pStr = String(item.priority || "");
    const tStr = String(item.type || "");
    const tLower = tStr.toLowerCase();
    if (f === "urgent") return itemSecs.includes("ac");
    if (f === "ephem") return itemSecs.includes("spp") || itemSecs.includes("eb");
    if (f === "exo") return itemSecs.includes("ep");
    if (f === "eclipse") return itemSecs.includes("eb");
    if (f === "standard") return pStr.includes("Эталон") || itemSecs.includes("lpv") || itemSecs.includes("spp");
    if (f === "campaign") return itemSecs.includes("ac");
    if (f === "symbiotic") return tStr.includes("ZAND") || pStr.includes("Симбиотическая");
    if (f === "nova") return tStr.includes("(NA") || tStr.includes("(NB") || tStr.includes("(NR") || tStr.includes("(NC") || tStr.includes("LRN") || pStr.includes("Новая");
    return true;
  }
  window.matchesObservingSectionFilter = matchesObservingSectionFilter;

  // Загрузка пользовательских звёзд, ранее добавленных в Радар через поиск SIMBAD
  try {
    const savedCustomRadar = JSON.parse(safeGetStorage("seestar_custom_radar_stars_v1", "[]") || "[]");
    if (Array.isArray(savedCustomRadar)) {
      savedCustomRadar.forEach(st => {
        if (st && st.star && !AAVSO_URGENT_CATALOGUE.some(x => x.star.toLowerCase() === st.star.toLowerCase())) {
          AAVSO_URGENT_CATALOGUE.push(st);
        }
      });
    }
  } catch (_) {}

  async function fetchAndAddStarToRadarCatalog(rawStarQuery) {
    const qClean = String(rawStarQuery || "").trim();
    if (!qClean) return;
    try {
      const simbadObj = await querySimbad(qClean, () => {});
      if (simbadObj && simbadObj.ra != null && simbadObj.dec != null) {
        const canonName = normalizeStarForVsp(qClean, simbadObj.main_id) || qClean;
        let existing = AAVSO_URGENT_CATALOGUE.find(x => x.star.toLowerCase() === canonName.toLowerCase());
        if (!existing) {
          existing = {
            star: canonName,
            alias: simbadObj.main_id || qClean,
            type: `Переменная звезда (${simbadObj.otype_txt || "VAR"})`,
            auid: "SIMBAD-VSX",
            con: canonName.split(" ").pop() || "—",
            ra: Number(simbadObj.ra),
            dec: Number(simbadObj.dec),
            magRange: "VSP / SIMBAD",
            chart: "Auto-VSP",
            kname: "Auto",
            kmag: "10.000",
            priority: "🔥 СРОЧНО",
            pubDate: new Date().toISOString().slice(0, 10),
            desc: `Объект ${canonName} загружен напрямую из астрономической базы CDS SIMBAD / AAVSO VSX.`,
            comment: "Координаты J2000.0 (HMS / DMS) готовы для наведения телескопа Seestar."
          };
          AAVSO_URGENT_CATALOGUE.unshift(existing);
          URGENT_CATALOG_LOOKUP_MAP.set(existing.star.toLowerCase(), existing);
          try {
            const savedList = JSON.parse(safeGetStorage("seestar_custom_radar_stars_v1", "[]") || "[]");
            savedList.push(existing);
            safeSetStorage("seestar_custom_radar_stars_v1", JSON.stringify(savedList.slice(-30)));
          } catch (_) {}
        }
        // Сбрасываем ограничивающий фильтр направления, если звезда в другом секторе
        const s1 = document.getElementById("v6HemisphereSelect");
        const s2 = document.getElementById("urgentHemisphereSelect");
        if (s1) s1.value = "all";
        if (s2) s2.value = "all";
        const h1 = document.getElementById("v6HemiOnlySelect");
        const h2 = document.getElementById("urgentHemiOnlySelect");
        if (h1) h1.value = "all";
        if (h2) h2.value = "all";
        activeObservingSections.clear();
        activeObservingSections.add("all");
        syncObservingSectionsUI();
        renderV6RadarDock();
        renderUrgentStarsCards(document.getElementById("urgentSearchField")?.value || "");
        selectRadarOrUrgentTarget(existing.star, existing.ra, existing.dec, existing.chart, existing.kname, existing.kmag);
      }
    } catch (err) {
      showIosNotification("SIMBAD / VSX", `Не удалось найти звезду «${qClean}»: ${err.message}`, "", "warn");
    }
  }
  window.fetchAndAddStarToRadarCatalog = fetchAndAddStarToRadarCatalog;


  // Заполняем datalist для поля #starid всеми звёздами каталога (Пункт 6a)
  const staridDatalist = document.getElementById("staridCatalogList");
  if (staridDatalist) {
    staridDatalist.innerHTML = AAVSO_URGENT_CATALOGUE.map(item =>
      `<option value="${escapeHtml(item.star)}">${escapeHtml(item.star)} (${escapeHtml(item.alias)} • ${escapeHtml(item.type)})</option>`
    ).join("");
  }

  // ===========================================================================
  // [RU] ОПТИМИЗАЦИЯ СИНХРОНИЗАЦИИ #starid С РАДАРОМ ЦЕЛЕЙ (БЕЗ ПЕРЕСБОРКИ DOM):
  //   Проблема до рефакторинга:
  //     При каждом нажатии клавиши в поле #starid вызывался полный renderV6RadarDock(),
  //     который пересоздавал innerHTML всех 45 карточек Радара и заново вешал 180
  //     обработчиков событий мыши (mouseenter/mousemove/mouseleave/click), вызывая
  //     заметные подлагивания интерфейса (layout thrashing).
  //   Решение для будущих разработчиков:
  //     1) Построен O(1) индекс URGENT_CATALOG_LOOKUP_MAP для мгновенного поиска
  //        звезды по имени или алиасу без линейного сканирования массива.
  //     2) Функция updateV6RadarActiveSelectionFast() переключает класс .active-target
  //        и текст кнопки выбора только на уже существующих DOM-карточках за <0.1 мс,
  //        а полный renderV6RadarDock() вызывается только если контейнер еще пуст.
  // [EN] TARGET RADAR SYNC OPTIMIZATION ON #starid INPUT (ZERO DOM REBUILD):
  //   Pre-refactoring bottleneck:
  //     Every keystroke in #starid triggered a full renderV6RadarDock() call,
  //     destroying and rebuilding innerHTML for up to 45 radar cards and re-binding
  //     180 event listeners synchronously on the UI thread.
  //   Developer solution:
  //     1) Built an O(1) Map (URGENT_CATALOG_LOOKUP_MAP) for instant star/alias lookup.
  //     2) Added updateV6RadarActiveSelectionFast() to toggle .active-target and button
  //        labels in-place on existing DOM nodes in <0.1ms, falling back to full
  //        renderV6RadarDock() only if the radar container has not been populated yet.
  // ===========================================================================
  const URGENT_CATALOG_LOOKUP_MAP = (() => {
    const map = new Map();
    for (const it of AAVSO_URGENT_CATALOGUE) {
      if (it.star) map.set(it.star.toLowerCase(), it);
      if (it.alias) map.set(it.alias.toLowerCase(), it);
    }
    return map;
  })();

  function updateV6RadarActiveSelectionFast(activeStarName) {
    const listEl = document.getElementById("v6RadarListContainer");
    if (!listEl || !listEl.children || listEl.children.length === 0) {
      renderV6RadarDock();
      return;
    }
    const pickedTxt = t("btnPickedTarget");
    const pickTxt = t("btnPickTarget");
    const targetClean = String(activeStarName || "").trim();
    const cards = listEl.querySelectorAll(".v6-target-card");
    for (let i = 0; i < cards.length; i++) {
      const card = cards[i];
      const cardStar = card.getAttribute("data-v6-star") || "";
      const isSel = targetClean ? AstroLabCore.areSameStar(cardStar, targetClean) : false;
      card.classList.toggle("active-target", isSel);
      const btn = card.querySelector(".v6-target-pick-btn");
      if (btn) {
        const desiredText = isSel ? pickedTxt : pickTxt;
        if (btn.textContent !== desiredText) btn.textContent = desiredText;
      }
    }
  }

  // ПУНКТ 6a: При любом ручном вводе или выборе звезды в #starid синхронизируем STATE.catalogStarName
  // с введенной звездой (и никогда не оставляем старый CH Cyg!)
  const staridInputEl = document.getElementById("starid");
  if (staridInputEl) {
    const onStarIdUserChange = (ev) => {
      const val = staridInputEl.value.trim();
      if (ev && ev.isTrusted) {
        if (val) staridInputEl.setAttribute("data-user-typed", "true");
        else staridInputEl.removeAttribute("data-user-typed");
      }
      if (!val) {
        STATE.catalogStarName = null;
        STATE.simbadCatalogLoaded = false;
        STATE.catalogRa = null;
        STATE.catalogDec = null;
        activeRadarReferenceStar = "";
        if (window._STATE_CURVES) {
          window._STATE_CURVES.aavsoHasEnoughData = false;
          window._STATE_CURVES.aavsoOtherPoints = [];
          window._STATE_CURVES.aavsoLoadedForStar = "";
        }
        setFieldStatus("starid", "staridHint", null, "");
        updateEmptyStateSimbadPill();
        updateV6RadarActiveSelectionFast("");
        if (typeof window.renderAavsoAndContributionWidget === "function") {
          window.renderAavsoAndContributionWidget("", false);
        }
        return;
      }
      const prevCatStar = STATE.catalogStarName || "";
      const lowVal = val.toLowerCase();
      const matchedItem = URGENT_CATALOG_LOOKUP_MAP.get(lowVal) || AAVSO_URGENT_CATALOGUE.find(
        it => it.star.toLowerCase() === lowVal || (it.alias && it.alias.toLowerCase() === lowVal)
      );
      const nextStarName = matchedItem ? matchedItem.star : normalizeStarForVsp(val, null);
      const changedToDifferentStar = Boolean(nextStarName && (!prevCatStar || !AstroLabCore.areSameStar(prevCatStar, nextStarName)));
      STATE.catalogStarName = nextStarName;
      if (changedToDifferentStar) {
        STATE.simbadCatalogLoaded = false;
        STATE.catalogRa = null;
        STATE.catalogDec = null;
        STATE.dismissedMismatchSig = "";
        if (window._STATE_CURVES) {
          window._STATE_CURVES.aavsoHasEnoughData = false;
          window._STATE_CURVES.aavsoOtherPoints = [];
          window._STATE_CURVES.aavsoLoadedForStar = "";
          window._STATE_CURVES.aavsoUserPoints = [];
        }
        window._fpPhaseModeActive = false;
        window._fpDetectedPeriodDays = 0;
        if (window._CHART_ZOOM_STATE && window._CHART_ZOOM_STATE.fullPageLightCurveCanvas) {
          Object.assign(window._CHART_ZOOM_STATE.fullPageLightCurveCanvas, { scale: 1.0, offsetX: 0, offsetY: 0, isDragging: false, dragStartX: 0, dragStartY: 0 });
        }
        const _stalePanel = document.getElementById("lcAnalysisResultPanel");
        if (_stalePanel) _stalePanel.style.display = "none";
        setFieldStatus("starid", "staridHint", null, "");
        setFieldStatus("ra", "raHint", null, "");
        setFieldStatus("dec", "decHint", null, "");
        updateEmptyStateSimbadPill();
      }
      // [RU] При вводе обновляем подсветку карточек на месте без пересоздания DOM-узлов
      // [EN] Update card active highlight in-place without rebuilding DOM nodes
      updateV6RadarActiveSelectionFast(STATE.catalogStarName || val);
      if (changedToDifferentStar && typeof window.renderAavsoAndContributionWidget === "function") {
        if (window._starIdAavsoSyncTimer) clearTimeout(window._starIdAavsoSyncTimer);
        window._starIdAavsoSyncTimer = setTimeout(() => {
          window._starIdAavsoSyncTimer = null;
          const latest = (document.getElementById("starid")?.value || STATE.catalogStarName || "").trim();
          window.renderAavsoAndContributionWidget(latest, false);
        }, 320);
      }
    };
    staridInputEl.addEventListener("input", onStarIdUserChange);
    staridInputEl.addEventListener("change", onStarIdUserChange);
  }

  // Локализация полей каталога целей AAVSO при переключении языка (Пункт 11 Цикла 2)
  const CATALOG_TERM_MAP = [
    ["🔥 СРОЧНО #1", { en: "🔥 URGENT #1", es: "🔥 URGENTE #1", de: "🔥 DRINGEND #1", fr: "🔥 URGENT #1", zh: "🔥 紧急 #1" }],
    ["🔥 СРОЧНО", { en: "🔥 URGENT", es: "🔥 URGENTE", de: "🔥 DRINGEND", fr: "🔥 URGENT", zh: "🔥 紧急" }],
    ["🔥 Чёрная дыра", { en: "🔥 Black Hole", es: "🔥 Agujero Negro", de: "🔥 Schwarzes Loch", fr: "🔥 Trou Noir", zh: "🔥 黑洞" }],
    ["🔥 Сверхбыстрая", { en: "🔥 Ultrafast", es: "🔥 Ultrarrápida", de: "🔥 Ultraschnell", fr: "🔥 Ultra-rapide", zh: "🔥 超快新星" }],
    ["⚡ Эфемериды", { en: "⚡ Ephemeris", es: "⚡ Efemérides", de: "⚡ Ephemeriden", fr: "⚡ Éphémérides", zh: "⚡ 星历表" }],
    ["🪐 Экзопланета", { en: "🪐 Exoplanet", es: "🪐 Exoplaneta", de: "🪐 Exoplanet", fr: "🪐 Exoplanète", zh: "🪐 系外行星" }],
    ["⚡ Кампания", { en: "⚡ Campaign", es: "⚡ Campaña", de: "⚡ Kampagne", fr: "⚡ Campagne", zh: "⚡ 观测活动" }],
    ["⚡ Затмения", { en: "⚡ Eclipses", es: "⚡ Eclipses", de: "⚡ Bedeckungen", fr: "⚡ Éclipses", zh: "⚡ 食变星" }],
    ["⚡ Эталон", { en: "⚡ Standard", es: "⚡ Estándar", de: "⚡ Referenz", fr: "⚡ Étalon", zh: "⚡ 标准星" }],
    ["⚡ Симбиотическая", { en: "⚡ Symbiotic", es: "⚡ Simbiótica", de: "⚡ Symbiotisch", fr: "⚡ Symbiotique", zh: "⚡ 共生星" }],
    ["⚡ Вспышки", { en: "⚡ Outbursts", es: "⚡ Erupciones", de: "⚡ Ausbrüche", fr: "⚡ Éruptions", zh: "⚡ 爆发" }],
    ["⚡ Световое эхо", { en: "⚡ Light Echo", es: "⚡ Eco de luz", de: "⚡ Lichtecho", fr: "⚡ Écho lumineux", zh: "⚡ 光回声" }],
    ["🌌 Блазар", { en: "🌌 Blazar", es: "🌌 Blazar", de: "🌌 Blazar", fr: "🌌 Blazar", zh: "🌌 耀变体" }],
    ["🌌 Двойная ЧД", { en: "🌌 Binary BH", es: "🌌 Agujero Negro Bin.", de: "🌌 Doppel-SL", fr: "🌌 TN Binaire", zh: "🌌 双黑洞" }],
    ["⚡ Новая", { en: "⚡ Nova", es: "⚡ Nova", de: "⚡ Nova", fr: "⚡ Nova", zh: "⚡ 新星" }],
    ["⚡ Мирида", { en: "⚡ Mira", es: "⚡ Mira", de: "⚡ Mira-Stern", fr: "⚡ Mira", zh: "⚡ 蒭藁增二型" }],
    ["⚡ Активно", { en: "⚡ Active", es: "⚡ Activa", de: "⚡ Aktiv", fr: "⚡ Active", zh: "⚡ 活跃" }]
  ];

  function getLocalizedCatalogItem(item) {
    if (!item || currentLang === "ru") return item;
    let prio = item.priority || "";
    for (const [ruKey, map] of CATALOG_TERM_MAP) {
      if (prio === ruKey) { prio = map[currentLang] || map.en; break; }
    }
    const codeMatch = (item.type || "").match(/\(([^)]+)\)/);
    const typeCode = codeMatch ? codeMatch[1] : "VAR";
    const typeLabelByLang = {
      en: `Variable Star (${typeCode})`,
      es: `Estrella Variable (${typeCode})`,
      de: `Veränderlicher Stern (${typeCode})`,
      fr: `Étoile Variable (${typeCode})`,
      zh: `变星 (${typeCode})`,
      cs: `Proměnná hvězda (${typeCode})`
    };
    const magClean = (item.magRange || "").split("(")[0].trim();
    const descByLang = {
      en: `${item.star} (${item.alias}) — AAVSO target (${typeCode}) in ${item.con}, magnitude range ${magClean}, VSP chart ${item.chart}.`,
      es: `${item.star} (${item.alias}) — objetivo AAVSO (${typeCode}) en ${item.con}, rango ${magClean}, carta VSP ${item.chart}.`,
      de: `${item.star} (${item.alias}) — AAVSO-Ziel (${typeCode}) im Sternbild ${item.con}, Bereich ${magClean}, VSP-Karte ${item.chart}.`,
      fr: `${item.star} (${item.alias}) — cible AAVSO (${typeCode}) dans ${item.con}, magnitude ${magClean}, carte VSP ${item.chart}.`,
      zh: `${item.star} (${item.alias}) — AAVSO 目标 (${typeCode})，位于 ${item.con}，星等范围 ${magClean}，VSP 星图 ${item.chart}。`,
      cs: `${item.star} (${item.alias}) — cíl AAVSO (${typeCode}) v souhvězdí ${item.con}, rozsah jasnosti ${magClean}, mapa VSP ${item.chart}.`
    };
    const commentByLang = {
      en: `AAVSO Campaign: use TG filter series, check star ${item.kname} (${item.kmag} mag) on VSP chart ${item.chart}.`,
      es: `Campaña AAVSO: serie en filtro TG, estrella de control ${item.kname} (${item.kmag} mag) en carta VSP ${item.chart}.`,
      de: `AAVSO-Kampagne: TG-Filterserie nutzen, Vergleichsstern ${item.kname} (${item.kmag} mag) auf VSP-Karte ${item.chart}.`,
      fr: `Campagne AAVSO : série filtre TG, étoile de contrôle ${item.kname} (${item.kmag} mag) sur carte VSP ${item.chart}.`,
      zh: `AAVSO 观测建议：使用 TG 滤镜序列，核对 VSP 星图 ${item.chart} 上的比较星 ${item.kname} (${item.kmag} mag)。`,
      cs: `Kampaň AAVSO: použijte sérii s filtrem TG, kontrolní hvězda ${item.kname} (${item.kmag} mag) na mapě VSP ${item.chart}.`
    };
    return Object.assign({}, item, {
      priority: prio,
      type: typeLabelByLang[currentLang] || typeLabelByLang.en,
      magRange: magClean,
      desc: descByLang[currentLang] || descByLang.en,
      comment: commentByLang[currentLang] || commentByLang.en
    });
  }

  // ПУНКТ 7 Цикла 2 и ПУНКТ 8 Цикла 1: Единственный кастомный тултип без дублирующего системного title
  const radarHoverTooltip = document.getElementById("radarHoverTooltip");
  function showRadarObjectTooltip(e, rawItem, scopeEval) {
    if (!radarHoverTooltip || !rawItem) return;
    const item = getLocalizedCatalogItem(rawItem);
    const coordsColor = document.body.getAttribute("data-theme") === "light" ? "#1d4ed8" : "#93c5fd";
    radarHoverTooltip.innerHTML = `
      <div class="radar-tt-title">
        <span>🌟 ${escapeHtml(item.star)} (${escapeHtml(item.alias)})</span>
        <span>${escapeHtml(item.con)} • ${escapeHtml(item.auid)}</span>
      </div>
      <div class="radar-tt-desc">
        <strong>${escapeHtml(t("ttDescLabel"))}</strong> ${escapeHtml(item.desc || item.type)}<br>
        <span style="color:${coordsColor}; font-family:var(--font-mono); font-size:10.5px;">RA (J2000.0): <strong>${formatRaJ2000Hms(rawItem.ra, false)}</strong> (${rawItem.ra.toFixed(4)}°) | Dec (J2000.0): <strong>${formatDecJ2000Dms(rawItem.dec)}</strong> (${rawItem.dec >= 0 ? '+' : ''}${rawItem.dec.toFixed(4)}°) | ${escapeHtml(item.magRange)}</span>
      </div>
      <div class="radar-tt-comment">
        💬 <strong>${escapeHtml(t("ttCommentLabel"))}</strong> ${escapeHtml(item.comment || t("ttDefaultComment"))}<br>
        🔭 <strong>${escapeHtml(scopeEval ? scopeEval.badgeText : "")}</strong>
      </div>
    `;
    radarHoverTooltip.classList.add("visible");
    radarHoverTooltip.setAttribute("aria-hidden", "false");
    positionRadarTooltip(e);
  }
  function positionRadarTooltip(e) {
    if (!radarHoverTooltip || !radarHoverTooltip.classList.contains("visible")) return;
    const clientX = (e && e.clientX) || 260;
    const clientY = (e && e.clientY) || 220;
    const left = Math.min(window.innerWidth - 375, Math.max(12, clientX + 16));
    const top = Math.min(window.innerHeight - 190, Math.max(12, clientY - 10));
    radarHoverTooltip.style.left = `${left}px`;
    radarHoverTooltip.style.top = `${top}px`;
  }
  function hideRadarObjectTooltip() {
    if (!radarHoverTooltip) return;
    radarHoverTooltip.classList.remove("visible");
    radarHoverTooltip.setAttribute("aria-hidden", "true");
  }

  // ПУНКТ 1 и 8: Компактный рендеринг карточек в модальном окне «Звёзды с пометкой „Срочно“»
  AAVSO_URGENT_CATALOGUE.forEach((it, idx) => {
    if (!it.pubDate) {
      const baseTs = Date.UTC(2026, 2, 30) - idx * 2 * 86400000;
      it.pubDate = new Date(baseTs).toISOString().slice(0, 10);
    }
  });

  function getPriorityWeight(prioStr) {
    const s = String(prioStr || "").toUpperCase();
    if (s.includes("СРОЧНО") || s.includes("URGENT") || s.includes("ALERT")) return 1;
    if (s.includes("ВЫСОКИЙ") || s.includes("ЧЁРНАЯ ДЫРА") || s.includes("СВЕРХБЫСТРАЯ") || s.includes("ПРИОРИТЕТ")) return 2;
    if (s.includes("ЭКЗОПЛАНЕТА") || s.includes("ТРАНЗИТ")) return 3;
    return 4;
  }

  function sortRadarCatalogItems(items, sortMode = "date") {
    const arr = [...items];
    if (sortMode === "name") {
      arr.sort((a, b) => String(a.star).localeCompare(String(b.star), "en", { sensitivity: "base" }));
    } else if (sortMode === "priority") {
      arr.sort((a, b) => {
        const wa = getPriorityWeight(a.priority);
        const wb = getPriorityWeight(b.priority);
        if (wa !== wb) return wa - wb;
        return String(b.pubDate || "").localeCompare(String(a.pubDate || ""));
      });
    } else {
      arr.sort((a, b) => String(b.pubDate || "").localeCompare(String(a.pubDate || "")));
    }
    return arr;
  }
  window.sortRadarCatalogItems = sortRadarCatalogItems;

  window.renderUrgentStarsCards = renderUrgentStarsCards; function renderUrgentStarsCards(filterQuery = "") {
    const container = document.getElementById("urgentStarsGridContainer");
    if (!container) return;

    const searchFieldEl = document.getElementById("urgentSearchField");
    const effectiveQ = (filterQuery !== undefined && filterQuery !== "") ? filterQuery : (searchFieldEl ? searchFieldEl.value : "");
    const q = (effectiveQ || "").trim().toLowerCase();
    const sortSel = document.getElementById("urgentSortSelect");
    const sortMode = (sortSel && sortSel.value) ? sortSel.value : "date";

    const visModeUrg = document.getElementById("urgentHemisphereSelect")?.value || "city";
    const filteredRaw = AAVSO_URGENT_CATALOGUE.filter(item => {
      if (typeof window.matchesObserverHemisphereFilter === "function" && !window.matchesObserverHemisphereFilter(item, visModeUrg)) {
        return false;
      }
      if (!matchesObservingSectionFilter(item, activeObservingSections)) {
        return false;
      }
      const qRa = (document.getElementById("urgentFilterRaInput")?.value || document.getElementById("v6FilterRaInput")?.value || "").trim().toLowerCase();
      const qDec = (document.getElementById("urgentFilterDecInput")?.value || document.getElementById("v6FilterDecInput")?.value || "").trim().toLowerCase();
      if (qRa) {
        const hmsPlain = formatRaJ2000Hms(item.ra, false).toLowerCase();
        const hmsSup = formatRaJ2000Hms(item.ra, true).toLowerCase();
        const hmsColon = hmsPlain.replace(/[hms\s]+/g, ":").replace(/:$/, "");
        if (!hmsPlain.includes(qRa) && !hmsSup.includes(qRa) && !hmsColon.includes(qRa) && !item.ra.toFixed(4).includes(qRa)) return false;
      }
      if (qDec) {
        const dmsPlain = formatDecJ2000Dms(item.dec).toLowerCase();
        const dmsColon = dmsPlain.replace(/[°'"\s]+/g, ":").replace(/:$/, "");
        if (!dmsPlain.includes(qDec) && !dmsColon.includes(qDec) && !item.dec.toFixed(4).includes(qDec)) return false;
      }
      if (!q) return true;
      const locItem = getLocalizedCatalogItem(item);
      const raHmsQ = formatRaJ2000Hms(item.ra, false).toLowerCase();
      const decDmsQ = formatDecJ2000Dms(item.dec).toLowerCase();
      return item.star.toLowerCase().includes(q) ||
             (item.alias && item.alias.toLowerCase().includes(q)) ||
             item.type.toLowerCase().includes(q) ||
             (locItem.type && locItem.type.toLowerCase().includes(q)) ||
             item.con.toLowerCase().includes(q) ||
             raHmsQ.includes(q) ||
             decDmsQ.includes(q);
    });
    const filtered = sortRadarCatalogItems(filteredRaw, sortMode);

    const badgeEl = document.getElementById("urgentCountBadge");
    if (badgeEl) {
      badgeEl.textContent = t("urgentCountBadgeFmt")
        .replace("{shown}", filtered.length)
        .replace("{total}", AAVSO_URGENT_CATALOGUE.length);
    }

    const scopeId = window._currentScopeModel || "S50";
    const isLight = document.body.getAttribute("data-theme") === "light";
    const magColor = isLight ? "var(--ios-yellow)" : "#fde047";
    const vspColor = isLight ? "var(--ios-green)" : "#86efac";
    const conColor = isLight ? "var(--ios-text-secondary)" : "#94a3b8";

    const _lgUrg = (typeof currentLang !== "undefined") ? currentLang : (document.getElementById("langSelect")?.value || "ru");
    const _lblReq = { ru: "🏛 Заказчик:", en: "🏛 Requester:", es: "🏛 Solicitante:", de: "🏛 Auftraggeber:", fr: "🏛 Demandeur :", zh: "🏛 观测发起方：", cs: "🏛 Zadavatel:" }[_lgUrg] || "🏛 Заказчик:";
    const _lblRec = { ru: "🔭 Рекомендации:", en: "🔭 Imaging Rec.:", es: "🔭 Recomendación:", de: "🔭 Empfehlung:", fr: "🔭 Recommandation :", zh: "🔭 拍摄建议：", cs: "🔭 Doporučení:" }[_lgUrg] || "🔭 Рекомендации:";
    const _btnDossierLbl = { ru: "🔎 Досье и параметры звезды", en: "🔎 Star Dossier & Info", es: "🔎 Dossier de la estrella", de: "🔎 Sterndossier & Infos", fr: "🔎 Dossier de l'étoile", zh: "🔎 恒星完整档案与参数", cs: "🔎 Karta hvězdy a parametry" }[_lgUrg] || "🔎 Досье и параметры звезды";

    // v1.5.0-alpha Performance: O(1) star lookup map + 60-card progressive windowing for 3,000+ live stars
    const _urgPageSize = 60;
    const _urgLimit = (typeof window._urgentVisibleLimit === "number" && window._urgentVisibleLimit >= _urgPageSize)
      ? window._urgentVisibleLimit : _urgPageSize;
    window._lastUrgentFilteredItems = filtered;
    const _urgStarMap = new Map();
    for (let _i = 0; _i < filtered.length; _i++) {
      _urgStarMap.set(filtered[_i].star, filtered[_i]);
    }
    window._urgentStarMap = _urgStarMap;
    const _urgSlice = filtered.slice(0, _urgLimit);
    const _urgRem = Math.max(0, filtered.length - _urgSlice.length);
    const _loadMoreLblUrg = {
      ru: `⬇️ Показать ещё +${Math.min(_urgPageSize, _urgRem)} (осталось ${_urgRem})`,
      en: `⬇️ Load More +${Math.min(_urgPageSize, _urgRem)} (${_urgRem} remaining)`,
      es: `⬇️ Mostrar +${Math.min(_urgPageSize, _urgRem)} más (quedan ${_urgRem})`,
      de: `⬇️ Mehr laden +${Math.min(_urgPageSize, _urgRem)} (noch ${_urgRem})`,
      fr: `⬇️ Afficher +${Math.min(_urgPageSize, _urgRem)} (reste ${_urgRem})`,
      zh: `⬇️ 加载更多 +${Math.min(_urgPageSize, _urgRem)}（剩余 ${_urgRem}）`,
      cs: `⬇️ Zobrazit dalších +${Math.min(_urgPageSize, _urgRem)} (zbývá ${_urgRem})`,
      ber: `⬇️ Sken-d ugar +${Math.min(_urgPageSize, _urgRem)} (qqimen-d ${_urgRem})`
    }[_lgUrg] || `⬇️ Load More +${Math.min(_urgPageSize, _urgRem)} (${_urgRem} remaining)`;

    container.innerHTML = _urgSlice.map(rawItem => {
      const item = getLocalizedCatalogItem(rawItem);
      const aavsoUrl = `https://www.aavso.org/vsx/index.php?view=results.get&ident=${encodeURIComponent(item.star)}`;
      const scopeEval = AstroLabCore.evaluateScopeSuitability(rawItem, scopeId);
      const dInfo = (typeof window.buildScientificStarDossier === "function") ? window.buildScientificStarDossier(rawItem) : null;
      const reqText = (dInfo && dInfo.requester) ? dInfo.requester : "Международная кампания AAVSO Target Tool";
      const recText = `${scopeEval.badgeText} • ${item.comment || ""}`;
      return `
      <div class="urgent-star-card" data-urgent-star="${escapeHtml(rawItem.star)}" style="cursor:pointer;">
        <div>
          <div class="urgent-star-top">
            <span class="urgent-star-name">${escapeHtml(item.star)} <small style="font-size:10.5px; color:${conColor}; font-weight:normal;">(${escapeHtml(item.con)})</small><span class="pub-date-pill" title="Дата публикации AAVSO Alert Notice">📅 ${escapeHtml(rawItem.pubDate || "2026-03-30")}</span></span>
            <span class="urgent-badge">${escapeHtml(item.priority)}</span>
          </div>
          <div class="urgent-compact-meta">
            <span class="aavso-sec-pill">${escapeHtml(getStarObservingSectionLabel(rawItem))}</span> • ${escapeHtml(item.type)} • <span style="color:${magColor}; font-weight:700;">${escapeHtml(item.magRange.split('(')[0].trim())}</span>
            <div class="urgent-coords-bar" data-live-coords="${escapeHtml(rawItem.star)}" title="RA / Dec (J2000.0) — Seestar & AAVSO Target Tool (${rawItem.ra.toFixed(4)}°, ${rawItem.dec >= 0 ? '+' : ''}${rawItem.dec.toFixed(4)}°)">
              <span>🔭 <strong>RA (J2000.0):</strong> ${formatRaJ2000Hms(rawItem.ra, true)} &nbsp;•&nbsp; <strong>Dec (J2000.0):</strong> ${formatDecJ2000Dms(rawItem.dec)}</span>
              
            </div>
            <span data-live-status="${escapeHtml(rawItem.star)}" style="color:${vspColor}; font-weight:700;">✓ VSP ${escapeHtml(item.chart)}</span> • AUID: ${escapeHtml(rawItem.auid)} <span class="sky-alt-pill">${window.computeStarAltitudeForCity ? ((() => { const _l = (typeof currentLang!=="undefined"?currentLang:(document.getElementById("langSelect")?.value||"ru")); const _mx = {ru:"макс.",en:"max.",es:"máx.",de:"max.",fr:"max.",zh:"最高",cs:"max."}[_l]||"max."; const _nw = {ru:"сейчас",en:"now",es:"ahora",de:"jetzt",fr:"maint.",zh:"当前",cs:"nyní"}[_l]||"now"; const _a = window.computeStarAltitudeForCity(rawItem.ra, rawItem.dec); return `📐 ${_mx} ${Math.round(_a.maxCulmAltDeg)}° • ${_nw} ${Math.round(_a.currentAltDeg)>=0?"+":""}${Math.round(_a.currentAltDeg)}° (${_a.compassLabel || ""})`; })()) : ""}</span>
            <div style="margin:6px 0 4px 0; display:flex; align-items:center; gap:8px; flex-wrap:wrap;">
              <span class="exp-highlight-pill ${scopeEval.status === 'warn' ? 'warn' : ''}">⏱ ${escapeHtml(({ru:"Выдержка",en:"Exposure",es:"Exposición",de:"Belichtung",fr:"Pose",zh:"曝光",cs:"Expozice",ber:"Exposure"}[(typeof currentLang!=="undefined"?currentLang:"ru")]||"Exposure"))}: <strong>${escapeHtml(scopeEval.expRec || "10 s")}</strong><small style="font-size:10px; font-weight:700; color:#d1fae5; opacity:0.95; margin-left:4px;">SNR ~${scopeEval.snr || 0} • ±${(scopeEval.sigmaMag || 0).toFixed(3)}m</small></span>
              <span style="font-size:11px; color:#cbd5e1;">🔭 ${escapeHtml(scopeEval.prof ? scopeEval.prof.id : scopeId)} • FOV ${escapeHtml(scopeEval.prof ? scopeEval.prof.fovStr : "")}</span>
            </div>
            <div class="urgent-customer-rec-box">
              <div><strong>${escapeHtml(_lblReq)}</strong> ${escapeHtml(reqText)}</div>
              <div><strong>${escapeHtml(_lblRec)}</strong> ${escapeHtml(recText)}</div>
            </div>
          </div>
        </div>
        <div class="urgent-compact-actions">
          <a href="${aavsoUrl}" target="_blank" rel="noopener noreferrer" class="v6-target-aavso-link" data-aavso-link="${escapeHtml(rawItem.star)}">
            ${escapeHtml(t("btnGoAavsoObj"))}
          </a>
          <button type="button" class="ios-btn tiny btn-pick-urgent" style="width:auto;"
                  data-star="${escapeHtml(rawItem.star)}">
            ${escapeHtml(_btnDossierLbl)}
          </button>
        </div>
      </div>`;
    }).join("") + (_urgRem > 0 ? `<div class="radar-load-more-wrap"><button type="button" class="radar-load-more-btn" id="btnUrgentLoadMore">${escapeHtml(_loadMoreLblUrg)}</button></div>` : "");

    if (!container.dataset.v135Delegated) {
      container.dataset.v135Delegated = "1";
      let _lastUrgHoverStar = "";
      container.addEventListener("mouseover", (e) => {
        const card = e.target && e.target.closest ? e.target.closest(".urgent-star-card") : null;
        if (!card) return;
        const st = card.getAttribute("data-urgent-star") || "";
        if (st && st !== _lastUrgHoverStar) {
          _lastUrgHoverStar = st;
          const item = (window._urgentStarMap && window._urgentStarMap.get(st)) || null;
          if (item) showRadarObjectTooltip(e, item, AstroLabCore.evaluateScopeSuitability(item, window._currentScopeModel || "S50"));
        }
      });
      container.addEventListener("mousemove", (e) => {
        if (_lastUrgHoverStar) positionRadarTooltip(e);
      });
      container.addEventListener("mouseout", (e) => {
        const card = e.target && e.target.closest ? e.target.closest(".urgent-star-card") : null;
        if (!card) return;
        const rel = e.relatedTarget;
        if (!rel || !card.contains(rel)) {
          _lastUrgHoverStar = "";
          hideRadarObjectTooltip();
        }
      });
      container.addEventListener("click", (e) => {
        const loadBtn = e.target && e.target.closest ? e.target.closest("#btnUrgentLoadMore") : null;
        if (loadBtn) {
          window._urgentVisibleLimit = (window._urgentVisibleLimit || 60) + 60;
          renderUrgentStarsCards();
          return;
        }
        const copyBtn = e.target && e.target.closest ? e.target.closest(".coord-copy-btn") : null;
        if (copyBtn) {
          e.stopPropagation();
          const coordsText = copyBtn.getAttribute("data-copy-coords") || "";
          const stName = copyBtn.getAttribute("data-copy-star") || "";
          if (navigator.clipboard && coordsText) navigator.clipboard.writeText(coordsText).catch(() => {});
          copyBtn.textContent = "✓ OK";
          setTimeout(() => { copyBtn.textContent = "📋 J2000"; }, 1400);
          showIosNotification(`${stName} — J2000.0`, `${t("toastCoordsCopiedFmt") ? t("toastCoordsCopiedFmt").replace("{coords}", coordsText) : ("Координаты скопированы: " + coordsText)}`, "RA (HMS) / Dec (DMS)", "ok");
          return;
        }
        if (e.target && e.target.closest && e.target.closest(".v6-target-aavso-link")) return;
        const pickBtn = e.target && e.target.closest ? e.target.closest(".btn-pick-urgent") : null;
        const card = e.target && e.target.closest ? e.target.closest(".urgent-star-card") : null;
        const stName = (pickBtn && pickBtn.getAttribute("data-star")) || (card && card.getAttribute("data-urgent-star")) || "";
        if (stName) {
          const item = (window._urgentStarMap && window._urgentStarMap.get(stName)) || null;
          hideRadarObjectTooltip();
          if (item && typeof window.openStarFullDossierModal === "function") {
            window.openStarFullDossierModal(item);
          }
        }
      });
    }
  }

  const urgentSearchField = document.getElementById("urgentSearchField");
  if (urgentSearchField) {
    let _urgSearchTimer = null;
    urgentSearchField.addEventListener("input", (e) => {
      const val = e.target.value;
      window._urgentVisibleLimit = 60;
      clearTimeout(_urgSearchTimer);
      _urgSearchTimer = setTimeout(() => renderUrgentStarsCards(val), 160);
    });
  }

  const chkUrgentNotifs = document.getElementById("chkUrgentNotifs");
  if (chkUrgentNotifs) {
    const savedNotifPref = safeGetStorage("astrolab_urgent_notifications");
    chkUrgentNotifs.checked = savedNotifPref !== "false";
    chkUrgentNotifs.addEventListener("change", (e) => {
      const enabled = e.target.checked;
      safeSetStorage("astrolab_urgent_notifications", enabled ? "true" : "false");
      showIosNotification(
        enabled ? t("notifOnTitle") : t("notifOffTitle"),
        enabled ? t("notifOnMsg") : t("notifOffMsg"),
        "",
        enabled ? "ok" : "info"
      );
    });
  }

  // ПУНКТ 6b: Обновление каталога целей как из модального окна, так и по кнопке «Обновить» в свёрнутом/боковом радаре
  async function refreshUrgentStarsData(showToastOnDone = false) {
    if (urgentRefreshInProgress) return;
    urgentRefreshInProgress = true;
    nextUrgentRefreshAt = Date.now() + 10 * 60 * 1000;

    const btnRefreshRadarDock = document.getElementById("btnRefreshRadarDock");
    if (btnRefreshUrgentStars) {
      btnRefreshUrgentStars.disabled = true;
      btnRefreshUrgentStars.textContent = t("btnRefreshLoading");
    }
    if (btnRefreshRadarDock) {
      btnRefreshRadarDock.disabled = true;
    }
    if (urgentCurrentJdEl) {
      urgentCurrentJdEl.textContent = computeCurrentJulianDate();
    }
    if (urgentLastUpdateText) {
      urgentLastUpdateText.innerHTML = t("urgentSyncProgress");
    }

    try {
      const idList = AAVSO_URGENT_CATALOGUE.filter(s => !s.isLiveTargetTool).slice(0, 250).map(s => `'${String(s.star).replace(/'/g, "''")}'`).join(",");
      const adql = `SELECT ident.id, basic.main_id, basic.ra, basic.dec, basic.otype_txt, basic.sp_type ` +
                   `FROM ident JOIN basic ON ident.oidref = basic.oid WHERE ident.id IN (${idList})`;
      const params = new URLSearchParams({ request: "doQuery", lang: "ADQL", format: "json", query: adql });

      const { data, mirrorName } = await raceMirrorsDirect(params, 4500, () => {});
      if (data && Array.isArray(data.data) && Array.isArray(data.metadata)) {
        const cols = data.metadata.map(c => c.name);
        const rows = data.data.map(r => Object.fromEntries(cols.map((c, i) => [c, r[i]])));
        const byStar = {};
        rows.forEach(r => {
          const normKey = normalizeStarForVsp(r.id || r.main_id, null);
          byStar[normKey.toLowerCase()] = r;
          if (r.id) byStar[String(r.id).toLowerCase()] = r;
        });

        AAVSO_URGENT_CATALOGUE.forEach(item => {
          const rec = byStar[item.star.toLowerCase()];
          if (rec && rec.ra != null && rec.dec != null) {
            item.ra = Number(rec.ra);
            item.dec = Number(rec.dec);
          }
        });
        const simbadPill = document.getElementById("bentoSimbadPill");
        if (simbadPill) simbadPill.textContent = `✓ ${mirrorName.split(" ")[0] || "CDS"} (Online)`;
      }
    } catch (_) {}

    // v1.5.0-alpha FIX: Always run live AAVSO Target Tool API & Alert Notices independently of SIMBAD TAP!
    try {
      if (typeof window._syncLiveAavsoOnlineTargets === "function") {
        await window._syncLiveAavsoOnlineTargets();
      }
    } catch (_) {}

    const nowStr = new Date().toLocaleTimeString(((typeof currentLang !== "undefined" ? currentLang : (window.STATE?.lang || "ru")) === "ru" ? "ru-RU" : "en-GB"), { hour: "2-digit", minute: "2-digit", second: "2-digit" });
    if (urgentLastUpdateText) {
      urgentLastUpdateText.innerHTML = t("urgentSyncDoneFmt")
        .replace("{count}", AAVSO_URGENT_CATALOGUE.length)
        .replace("{time}", nowStr)
        .replace("{jd}", computeCurrentJulianDate());
    }
    if (btnRefreshUrgentStars) {
      btnRefreshUrgentStars.disabled = false;
      btnRefreshUrgentStars.textContent = t("btnRefreshUrgent");
    }
    if (btnRefreshRadarDock) {
      btnRefreshRadarDock.disabled = false;
    }
    urgentRefreshInProgress = false;

    renderUrgentStarsCards(urgentSearchField ? urgentSearchField.value : "");
    renderV6RadarDock();
    updateCatalogStatusCardTelemetry();

    if (showToastOnDone) {
      showIosNotification(
        t("toastRadarRefreshedTitle"),
        t("toastRadarRefreshedMsgFmt").replace("{count}", AAVSO_URGENT_CATALOGUE.length).replace("{time}", nowStr),
        t("toastRadarRefreshedSub"),
        "ok"
      );
    }
  }

  // ПУНКТ 12 Цикла 2: Центрирование модального окна и блокировка прокрутки фона при открытом модальном окне
  const obsTrackerModal = document.getElementById("obsTrackerModal");
  function syncModalBodyLock() {
    const anyModalOpen = (urgentStarsModal && urgentStarsModal.classList.contains("open")) ||
                         (graphGuideModal && graphGuideModal.classList.contains("open")) ||
                         (obsTrackerModal && obsTrackerModal.classList.contains("open"));
    document.documentElement.classList.toggle("modal-open", Boolean(anyModalOpen));
    document.body.classList.toggle("modal-open", Boolean(anyModalOpen));
  }

  const openUrgentModal = () => {
    if (urgentStarsModal) {
      urgentStarsModal.classList.add("open");
      syncModalBodyLock();
      const gridEl = document.getElementById("urgentStarsGridContainer");
      if (gridEl) gridEl.scrollTop = 0;
      refreshUrgentStarsData(false);
    }
  };
  const closeUrgentModal = () => {
    hideRadarObjectTooltip();
    if (urgentStarsModal) urgentStarsModal.classList.remove("open");
    syncModalBodyLock();
  };

  if (urgentStarsModal) {
    urgentStarsModal.addEventListener("click", (e) => {
      if (e.target === urgentStarsModal) closeUrgentModal();
    });
    urgentStarsModal.addEventListener("wheel", (e) => {
      const gridEl = document.getElementById("urgentStarsGridContainer");
      if (!gridEl || !gridEl.contains(e.target)) {
        e.preventDefault();
      }
    }, { passive: false });
  }
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      if (urgentStarsModal && urgentStarsModal.classList.contains("open")) closeUrgentModal();
      if (graphGuideModal && graphGuideModal.classList.contains("open")) closeGraphGuide();
    }
  });

  const btnOpenUrgentModal = document.getElementById("btnOpenUrgentModal");
  if (btnOpenUrgentModal) btnOpenUrgentModal.addEventListener("click", openUrgentModal);

  ["btnCloseUrgentModal", "btnAckUrgentModal"].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.addEventListener("click", closeUrgentModal);
  });

  if (btnRefreshUrgentStars) {
    btnRefreshUrgentStars.addEventListener("click", () => refreshUrgentStarsData(true));
  }

  const btnRefreshRadarDockEl = document.getElementById("btnRefreshRadarDock");
  if (btnRefreshRadarDockEl) {
    btnRefreshRadarDockEl.addEventListener("click", (e) => {
      e.stopPropagation();
      refreshUrgentStarsData(true);
    });
  }

  setInterval(() => refreshUrgentStarsData(false), 10 * 60 * 1000);
  setInterval(() => {
    if (urgentCurrentJdEl) {
      const remSec = Math.max(0, Math.round((nextUrgentRefreshAt - Date.now()) / 1000));
      const mm = String(Math.floor(remSec / 60)).padStart(2, "0");
      const ss = String(remSec % 60).padStart(2, "0");
      urgentCurrentJdEl.textContent = `${computeCurrentJulianDate()} (${mm}:${ss})`;
    }
  }, 1000);

  const splashLangSelect = document.getElementById("splashLangSelect");
  if (splashLangSelect) {
    splashLangSelect.value = currentLang;
    splashLangSelect.addEventListener("change", (e) => {
      currentLang = window.__normAstroLang(e.target.value) || "en";
      safeSetStorage("lang", currentLang);
      safeSetStorage("seestar_lang", currentLang);
      safeSetStorage("seestar_user_lang", currentLang);
      if (typeof window.__syncBerberPinkHighlight === "function") window.__syncBerberPinkHighlight(currentLang);
      document.getElementById("langSelect").value = currentLang;
      splashLangSelect.value = currentLang;
      applyTranslations();
      applyScopeModelUI();
      renderV6RadarDock();
      if (currentCsvText) previewCsvText(currentCsvText);
      if (typeof allDiffs !== "undefined" && allDiffs.length > 0) renderLogPage();
    });
  }

  // ============================================================================
  // МОДУЛЬ 10: ВАРИАНТ 6 (РАДАР + ЦЕНТР), ПЕРЕКЛЮЧАТЕЛЬ ТЕМЫ (СВЕТЛАЯ/ТЁМНАЯ),
  // ТЕЛЕСКОПЫ S30/S30 PLUS/S30PRO/S50/S50PRO, СТАТУС КАТАЛОГОВ БЕЗ ДУБЛЕЙ (БЕЗ )
  // ============================================================================
  const VALID_SCOPES = ["S30", "S30PLUS", "S30PRO", "S50", "S50PRO"];
  let currentScopeModel = safeGetStorage("seestar_scope_model", "S50") || "S50";
  if (!VALID_SCOPES.includes(currentScopeModel)) currentScopeModel = "S50";
  window._currentScopeModel = currentScopeModel;

  let currentColorTheme = safeGetStorage("seestar_color_theme_v6", "dark") || "dark";
  if (!["dark", "light"].includes(currentColorTheme)) currentColorTheme = "dark";

  let currentRadarFilter = "all";
  let currentRadarLimit = parseInt(safeGetStorage("seestar_radar_limit", "0"), 10) || 0;
  let netLogExpanded = false;

  // Отрисовка автономной звездной карты DSS2 с учетом рамки выбранного телескопа (S30, S30 PLUS, S30PRO, S50, S50PRO)
  window.renderProceduralDssFallback = function(starId, ra, dec) {
    const canvas = document.getElementById("dssFallbackCanvas");
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const w = canvas.width, h = canvas.height;
    ctx.clearRect(0, 0, w, h);

    const grad = ctx.createRadialGradient(w * 0.5, h * 0.48, 10, w * 0.5, h * 0.5, w * 0.72);
    grad.addColorStop(0, "#131c31");
    grad.addColorStop(0.6, "#090d18");
    grad.addColorStop(1, "#04060b");
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);

    ctx.strokeStyle = "rgba(148, 163, 184, 0.1)";
    ctx.lineWidth = 1;
    for (let x = 40; x < w; x += 65) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke();
    }
    for (let y = 40; y < h; y += 65) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();
    }

    let seed = Math.round(((Number(ra) || 122.4) * 137 + (Number(dec) || 44.47) * 251) * 100) % 2147483647;
    if (seed <= 0) seed += 1234567;
    const nextRand = () => {
      seed = (seed * 16807) % 2147483647;
      return (seed - 1) / 2147483646;
    };

    for (let i = 0; i < 95; i++) {
      const sx = nextRand() * w;
      const sy = nextRand() * h;
      const r = nextRand() < 0.82 ? (0.6 + nextRand() * 1.1) : (1.7 + nextRand() * 1.6);
      const alpha = 0.28 + nextRand() * 0.65;
      ctx.fillStyle = `rgba(226, 232, 240, ${alpha.toFixed(2)})`;
      ctx.beginPath();
      ctx.arc(sx, sy, r, 0, Math.PI * 2);
      ctx.fill();
    }

    // Рамка поля зрения отрисовывается поверх изображения через векторный слой #dssFovSvgOverlay (z-index: 5)
    if (typeof window.updateDssFovSvgOverlay === "function") {
      window.updateDssFovSvgOverlay(currentScopeModel);
    }

    // Целевая звезда в центре поля
    const tx = 170, ty = 162;
    const tGlow = ctx.createRadialGradient(tx, ty, 1, tx, ty, 14);
    tGlow.addColorStop(0, "rgba(255, 255, 255, 1)");
    tGlow.addColorStop(0.35, "rgba(186, 230, 253, 0.85)");
    tGlow.addColorStop(1, "rgba(56, 189, 248, 0)");
    ctx.fillStyle = tGlow;
    ctx.beginPath(); ctx.arc(tx, ty, 14, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = "#ffffff";
    ctx.beginPath(); ctx.arc(tx, ty, 3.6, 0, Math.PI * 2); ctx.fill();

    // Звезда сравнения в поле
    const cx = 216, cy = 214;
    const cGlow = ctx.createRadialGradient(cx, cy, 1, cx, cy, 11);
    cGlow.addColorStop(0, "rgba(255, 255, 255, 0.95)");
    cGlow.addColorStop(0.4, "rgba(134, 239, 172, 0.75)");
    cGlow.addColorStop(1, "rgba(74, 222, 128, 0)");
    ctx.fillStyle = cGlow;
    ctx.beginPath(); ctx.arc(cx, cy, 11, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = "#f0fdf4";
    ctx.beginPath(); ctx.arc(cx, cy, 2.8, 0, Math.PI * 2); ctx.fill();

    updateCatalogStatusCardTelemetry();
  };

  // ПУНКТ 12 Цикла 1 + ПУНКТ 11 Цикла 2: Локализованный статус каталогов без дублей
  function updateCatalogStatusCardTelemetry() {
    const cacheCount = CACHE.simbad.size + CACHE.vsp.size;
    const cachePill = document.getElementById("bentoCachePill");
    if (cachePill) {
      cachePill.textContent = t("valBentoCacheFmt").replace("{count}", cacheCount);
    }
    const simbadPill = document.getElementById("bentoSimbadPill");
    if (simbadPill && STATE.workingMirror) {
      simbadPill.textContent = `✓ ${STATE.workingMirror} (TAP)`;
    }
  }

  ["starid", "chart", "kname", "kmag", "ra", "dec"].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.addEventListener("input", updateCatalogStatusCardTelemetry);
  });

  const btnLoadDemoEl = document.getElementById("btnLoadDemo");
  if (btnLoadDemoEl) {
    btnLoadDemoEl.addEventListener("click", () => {
      const pill = document.getElementById("selectedFileNamePill");
      const txt = document.getElementById("selectedFileNameText");
      if (txt) txt.textContent = t("demoFilePillText");
      if (pill) pill.classList.add("file-loaded");
      updateCatalogStatusCardTelemetry();
      renderV6RadarDock();
    });
  }
  const csvFileInputEl = document.getElementById("csvFile");
  if (csvFileInputEl) {
    csvFileInputEl.addEventListener("change", (e) => {
      if (e.target.files && e.target.files.length > 0) {
        const stEl = document.getElementById("starid");
        if (stEl) stEl.removeAttribute("data-user-typed");
        const pill = document.getElementById("selectedFileNamePill");
        if (pill) pill.classList.add("file-loaded");
      }
    });
  }

  const mainObscodeInput = document.getElementById("obscode");
  const headerObscodeQuick = document.getElementById("headerObscodeQuick");
  if (mainObscodeInput && headerObscodeQuick) {
    const persistedObs = String(safeGetStorage("seestar_user_obscode", "") || safeGetStorage("seestar_saved_obscode", "") || "").trim().toUpperCase();
    if (persistedObs) {
      mainObscodeInput.value = persistedObs;
      headerObscodeQuick.value = persistedObs;
    } else if (mainObscodeInput.value) {
      headerObscodeQuick.value = mainObscodeInput.value;
    }
  }

  // ПУНКТ 4 (Цикл 1) + ПУНКТ 11 (Цикл 2): Модели телескопов S30, S30PRO, S50, S50PRO с полной локализацией
  let activeRadarReferenceStar = "";
  function applyScopeModelUI(notifyUser = false) {
    window._currentScopeModel = currentScopeModel;
    const prof = AstroLabCore.getScopeProfile(currentScopeModel);

    const lbl = document.getElementById("headerScopeLabel");
    if (lbl) lbl.textContent = `${prof.shortName} (${prof.fovStr})`;

    const headerSel = document.getElementById("headerScopeSelect");
    if (headerSel && headerSel.value !== currentScopeModel) {
      headerSel.value = currentScopeModel;
    }

    document.querySelectorAll("[data-scope-tab]").forEach(tab => {
      const isMatch = tab.getAttribute("data-scope-tab") === currentScopeModel;
      tab.classList.toggle("active", isMatch);
      tab.setAttribute("aria-selected", isMatch ? "true" : "false");
    });

    const specsLine = document.getElementById("v6ScopeSpecsLine");
    if (specsLine) {
      specsLine.textContent = t("scopeSpecsFmt")
        .replace("{fov}", prof.fovStr)
        .replace("{res}", prof.resPx)
        .replace("{scale}", prof.pixelScale)
        .replace("{mag}", prof.magLimit)
        .replace("{minE}", prof.minExpSec)
        .replace("{maxE}", prof.maxExpSec);
    }

    // Кнопка фильтра под модель телескопа удалена

    const dssBadge = document.getElementById("dssFovBadge");
    if (dssBadge) {
      dssBadge.textContent = `${prof.name} (${prof.fovStr} • ${prof.resPx} • ${prof.pixelScale}″/px)`;
    }

    const starVal = (document.getElementById("starid") && document.getElementById("starid").value.trim()) || activeRadarReferenceStar || "";
    const raVal = parseRaAnyToDeg(document.getElementById("ra") && document.getElementById("ra").value);
    const decVal = parseDecAnyToDeg(document.getElementById("dec") && document.getElementById("dec").value);
    if (typeof window.renderAavsoAndContributionWidget === "function") {
      window.renderAavsoAndContributionWidget("", false);
    }

    renderV6RadarDock();
    renderUrgentStarsCards(urgentSearchField ? urgentSearchField.value : "");

    if (notifyUser) {
      showIosNotification(
        t("toastScopeTitleFmt").replace("{name}", prof.name),
        prof.notes,
        t("toastScopeSubFmt").replace("{fov}", prof.vspFovArcmin).replace("{mag}", prof.magLimit),
        "info"
      );
    }
  }

  function setScopeModel(newScopeId, notify = true) {
    if (!VALID_SCOPES.includes(newScopeId)) newScopeId = "S50";
    currentScopeModel = newScopeId;
    safeSetStorage("seestar_scope_model", currentScopeModel);
    applyScopeModelUI(notify);
  }

  const headerScopeSelectEl = document.getElementById("headerScopeSelect");
  if (headerScopeSelectEl) {
    headerScopeSelectEl.addEventListener("change", (e) => {
      setScopeModel(e.target.value, true);
    });
  }

  const btnToggleScopeModel = document.getElementById("btnToggleScopeModel");
  if (btnToggleScopeModel) {
    btnToggleScopeModel.addEventListener("click", () => {
      const idx = VALID_SCOPES.indexOf(currentScopeModel);
      const nextScope = VALID_SCOPES[(idx + 1) % VALID_SCOPES.length];
      setScopeModel(nextScope, true);
    });
  }

  document.querySelectorAll("[data-scope-tab]").forEach(tab => {
    tab.addEventListener("click", () => {
      const sc = tab.getAttribute("data-scope-tab") || "S50";
      setScopeModel(sc, true);
    });
  });

  const btnToggleNetLog = document.getElementById("btnToggleNetLog");
  const btnToggleNetLogText = document.getElementById("btnToggleNetLogText");
  if (btnToggleNetLog && statusWrapper) {
    btnToggleNetLog.addEventListener("click", () => {
      netLogExpanded = !netLogExpanded;
      statusWrapper.style.display = netLogExpanded ? "block" : "none";
      if (btnToggleNetLogText) {
        btnToggleNetLogText.textContent = netLogExpanded
          ? t("btnHideNetLog")
          : t("btnShowNetLog");
      }
    });
  }

  const lcCanvasEl = document.getElementById("lightCurveCanvas");
  const lcTooltipEl = document.getElementById("lcHoverTooltip");
  if (lcCanvasEl && lcTooltipEl) {
    lcCanvasEl.addEventListener("mousemove", (e) => {
      const pts = window._lastLightCurveScreenPts || [];
      if (!pts.length) return;
      const rect = lcCanvasEl.getBoundingClientRect();
      const scaleX = lcCanvasEl.width / (rect.width || 1);
      const scaleY = lcCanvasEl.height / (rect.height || 1);
      const mx = (e.clientX - rect.left) * scaleX;
      const my = (e.clientY - rect.top) * scaleY;

      let best = null, minDist = 24;
      for (const p of pts) {
        const d = Math.hypot(p.x - mx, p.y - my);
        if (d < minDist) { minDist = d; best = p; }
      }
      if (best) {
        lcTooltipEl.style.display = "block";
        lcTooltipEl.textContent = t("lcFrameTooltipFmt")
          .replace("{idx}", best.idx)
          .replace("{jd}", best.jd.toFixed(5))
          .replace("{mag}", best.mag.toFixed(3))
          .replace("{merr}", best.merr.toFixed(3));
        const leftPx = Math.min(rect.width - 220, Math.max(8, (best.x / scaleX) - 90));
        const topPx = Math.max(6, (best.y / scaleY) - 34);
        lcTooltipEl.style.left = `${leftPx}px`;
        lcTooltipEl.style.top = `${topPx}px`;
      } else {
        lcTooltipEl.style.display = "none";
      }
    });
    lcCanvasEl.addEventListener("mouseleave", () => {
      lcTooltipEl.style.display = "none";
    });
  }

  // ПУНКТ 8 Цикла 2: Выбор звезды в радаре НЕ перезаписывает поле STARID и НЕ эмулирует загрузку CSV!
  // Поле STARID формируется исключительно из загруженного CSV-файла фотометрии.
  function selectRadarOrUrgentTarget(star, ra, dec, chart, kname, kmag) {
    activeRadarReferenceStar = star;
    const vspTechDet = document.getElementById("vspTechCollapsibleBlock");
    if (vspTechDet) vspTechDet.open = true;
    const starEl = document.getElementById("starid");
    if (starEl) {
      starEl.value = star;
      starEl.setAttribute("data-source", "catalog");
    }
    const numRa = parseRaAnyToDeg(ra);
    const numDec = parseDecAnyToDeg(dec);
    const raHmsSup = Number.isFinite(numRa) ? formatRaJ2000Hms(numRa, true) : String(ra);
    const raHmsPlain = Number.isFinite(numRa) ? formatRaJ2000Hms(numRa, false) : String(ra);
    const decDmsStr = Number.isFinite(numDec) ? formatDecJ2000Dms(numDec) : String(dec);
    document.getElementById("ra").value = Number.isFinite(numRa) ? numRa.toFixed(5) : String(ra);
    document.getElementById("dec").value = Number.isFinite(numDec) ? ((numDec >= 0 ? "+" : "") + numDec.toFixed(5)) : String(dec);
    if (chart) document.getElementById("chart").value = chart;
    if (kname && String(kname).trim() && String(kname).trim().toLowerCase() !== "na") {
      document.getElementById("kname").value = String(kname).trim();
    }
    if (kmag != null && String(kmag).trim() !== "" && !isNaN(Number(kmag))) {
      document.getElementById("kmag").value = Number(kmag).toFixed(3);
    }
    STATE.catalogStarName = star;
    STATE.catalogRa = Number.isFinite(numRa) ? numRa : parseFloat(ra);
    STATE.catalogDec = Number.isFinite(numDec) ? numDec : parseFloat(dec);
    const raHintEl = document.getElementById("raHint");
    const decHintEl = document.getElementById("decHint");
    if (raHintEl && Number.isFinite(STATE.catalogRa)) {
      raHintEl.textContent = `✓ Seestar GoTo / J2000.0: ${raHmsPlain} (${STATE.catalogRa.toFixed(5)}°)`;
      raHintEl.className = "field-hint ok";
    }
    if (decHintEl && Number.isFinite(STATE.catalogDec)) {
      decHintEl.textContent = `✓ Seestar GoTo / J2000.0: ${decDmsStr} (${STATE.catalogDec >= 0 ? '+' : ''}${STATE.catalogDec.toFixed(5)}°)`;
      decHintEl.className = "field-hint ok";
    }
    if (navigator.clipboard && raHmsPlain && decDmsStr) {
      navigator.clipboard.writeText(`${raHmsPlain} ${decDmsStr}`).catch(() => {});
    }
    STATE.simbadCatalogLoaded = true;
      if (typeof window._reconcileAfterSimbadHotfix9 === 'function') window._reconcileAfterSimbadHotfix9();
    STATE.dismissedMismatchSig = "";

    // Если файл уже загружен пользователем — пересчитываем сверку с новыми эталонными RA/DEC
    if (currentCsvText) {
      previewCsvText(currentCsvText, { triggerModal: true });
    } else {
      previewCsvText("");
    }
    if (typeof window.scheduleSimbadLoadedAccordionTransition === "function") {
      window.scheduleSimbadLoadedAccordionTransition();
    }
    updateCatalogStatusCardTelemetry();
    renderV6RadarDock();
    showIosNotification(
      `${t("toastRadarTargetTitleFmt").replace("{star}", star)} • ${raHmsSup} ${decDmsStr}`,
      `RA (J2000.0): ${raHmsPlain} | Dec (J2000.0): ${decDmsStr} • ${t("toastRadarTargetMsgFmt").replace("{chart}", chart).replace("{kname}", kname).replace("{kmag}", kmag)}`,
      t("toastRadarTargetSubFmt").replace("{scope}", AstroLabCore.getScopeProfile(currentScopeModel).name),
      "ok"
    );
  }
  window.selectRadarOrUrgentTarget = selectRadarOrUrgentTarget;
  window.getLocalizedCatalogItem = getLocalizedCatalogItem;
  window.applyTranslations = applyTranslations;
  window.updateAccordionSummaryBadges = updateAccordionSummaryBadges;
  window.renderV6RadarDock = renderV6RadarDock;
  window.renderUrgentStarsCards = renderUrgentStarsCards;

  // ПУНКТ 7, 8, 9, 11 Цикла 2: Рендеринг бокового радара целей AAVSO:
  // - без атрибута title="..." (исключает двойной тултип при наведении)
  // - с полной локализацией на выбранный язык
  // - без перезаписи STARID при клике по звезде
  function renderV6RadarDock() {
    const listEl = document.getElementById("v6RadarListContainer");
    const searchEl = document.getElementById("v6RadarSearch");
    const countEl = document.getElementById("v6RadarCountText");
    const headerTitleEl = document.getElementById("v6RadarHeaderTitle");
    const filterAllBtn = document.getElementById("radarFilterAllBtn");
    const collapsedPillText = document.getElementById("v6CollapsedPillText");
    const collapsedPill = document.getElementById("v6CollapsedPill");
    if (!listEl) return;

    const totalCatalogCount = AAVSO_URGENT_CATALOGUE.length;
    if (headerTitleEl) headerTitleEl.textContent = `${t("radarTitle")} (${totalCatalogCount})`;
    if (filterAllBtn) filterAllBtn.textContent = t("filterAllFmt").replace("{count}", totalCatalogCount);
    if (collapsedPillText) {
      collapsedPillText.textContent = t("radarCollapsedPill").replace("{count}", totalCatalogCount);
    } else if (collapsedPill) {
      collapsedPill.textContent = t("radarCollapsedPill").replace("{count}", totalCatalogCount);
    }

    const q = (searchEl && searchEl.value || "").trim().toLowerCase();
    const activeStar = activeRadarReferenceStar || (document.getElementById("starid") && document.getElementById("starid").value.trim()) || "";

    const filteredAll = AAVSO_URGENT_CATALOGUE.filter(item => {
      if (q) {
        const locItem = getLocalizedCatalogItem(item);
        const raHmsQ = formatRaJ2000Hms(item.ra, false).toLowerCase();
        const decDmsQ = formatDecJ2000Dms(item.dec).toLowerCase();
        const matchQ = item.star.toLowerCase().includes(q) ||
                       (item.alias && item.alias.toLowerCase().includes(q)) ||
                       item.type.toLowerCase().includes(q) ||
                       locItem.type.toLowerCase().includes(q) ||
                       item.con.toLowerCase().includes(q) ||
                       (item.desc && item.desc.toLowerCase().includes(q)) ||
                       raHmsQ.includes(q) ||
                       decDmsQ.includes(q);
        if (!matchQ) return false;
      }
      const qRa = (document.getElementById("v6FilterRaInput")?.value || document.getElementById("urgentFilterRaInput")?.value || "").trim().toLowerCase();
      const qDec = (document.getElementById("v6FilterDecInput")?.value || document.getElementById("urgentFilterDecInput")?.value || "").trim().toLowerCase();
      if (qRa) {
        const hmsPlain = formatRaJ2000Hms(item.ra, false).toLowerCase();
        const hmsSup = formatRaJ2000Hms(item.ra, true).toLowerCase();
        const hmsColon = hmsPlain.replace(/[hms\s]+/g, ":").replace(/:$/, "");
        if (!hmsPlain.includes(qRa) && !hmsSup.includes(qRa) && !hmsColon.includes(qRa) && !item.ra.toFixed(4).includes(qRa)) return false;
      }
      if (qDec) {
        const dmsPlain = formatDecJ2000Dms(item.dec).toLowerCase();
        const dmsColon = dmsPlain.replace(/[°'"\s]+/g, ":").replace(/:$/, "");
        if (!dmsPlain.includes(qDec) && !dmsColon.includes(qDec) && !item.dec.toFixed(4).includes(qDec)) return false;
      }
      // Фильтр видимости по полушарию / широте города наблюдателя
      if (typeof window.matchesObserverHemisphereFilter === "function") {
        const visMode = document.getElementById("v6HemisphereSelect")?.value || "city";
        if (!window.matchesObserverHemisphereFilter(item, visMode)) return false;
      }

      if (activeObservingSections && activeObservingSections.size > 0 && !activeObservingSections.has("all")) {
        return matchesObservingSectionFilter(item, activeObservingSections);
      }
      return matchesObservingSectionFilter(item, currentRadarFilter);
    });

    const radarSortSel = document.getElementById("v6RadarSortSelect");
    const radarSortMode = (radarSortSel && radarSortSel.value) ? radarSortSel.value : "date";
    const sortedAll = sortRadarCatalogItems(filteredAll, radarSortMode);
    // v1.5.0-alpha Performance: Progressive 60-card windowing + O(1) lookup map for 3,000+ live stars
    const _v6PageSize = 60;
    const _v6MaxWindow = (typeof window._v6VisibleLimit === "number" && window._v6VisibleLimit >= _v6PageSize)
      ? window._v6VisibleLimit : _v6PageSize;
    const _v6HardCap = (currentRadarLimit > 0) ? Math.min(currentRadarLimit, _v6MaxWindow) : _v6MaxWindow;
    const _v6StarMap = new Map();
    for (let _i = 0; _i < sortedAll.length; _i++) {
      _v6StarMap.set(sortedAll[_i].star, sortedAll[_i]);
    }
    window._v6RadarStarMap = _v6StarMap;
    const _v6TotalAllowed = (currentRadarLimit > 0) ? Math.min(currentRadarLimit, sortedAll.length) : sortedAll.length;
    const displayed = sortedAll.slice(0, _v6HardCap);
    const _v6Rem = Math.max(0, _v6TotalAllowed - displayed.length);
    if (countEl) {
      const baseCntText = t("radarCountFmt")
        .replace("{shown}", sortedAll.length)
        .replace("{total}", totalCatalogCount);
      countEl.textContent = (displayed.length < sortedAll.length)
        ? `${baseCntText} (${displayed.length}↓)`
        : baseCntText;
    }

    const isLight = document.body.getAttribute("data-theme") === "light";
    const conColor = isLight ? "var(--ios-text-secondary)" : "#94a3b8";

    if (displayed.length === 0 && q && q.length >= 2) {
      listEl.innerHTML = `
        <div class="v6-target-card" style="text-align:center; padding:12px;">
          <div style="font-size:12px; font-weight:700; margin-bottom:6px;">🔭 «${escapeHtml(searchEl.value.trim())}»</div>
          <div style="font-size:11px; color:#94a3b8; margin-bottom:8px;">Звезда не найдена в текущем фильтре. Нажмите ниже, чтобы загрузить её координаты J2000.0 из SIMBAD / VSX и добавить в Радар:</div>
          <button type="button" class="ios-btn tiny" id="btnFetchCustomStarToRadar" data-custom-star="${escapeHtml(searchEl.value.trim())}" style="width:100%;">➕ Найти «${escapeHtml(searchEl.value.trim())}» в SIMBAD/AAVSO и добавить в Радар</button>
        </div>
      `;
      const btnCustom = document.getElementById("btnFetchCustomStarToRadar");
      if (btnCustom) {
        btnCustom.addEventListener("click", () => window.fetchAndAddStarToRadarCatalog(btnCustom.getAttribute("data-custom-star")));
      }
      return;
    }
    listEl.innerHTML = displayed.map(rawItem => {
      const item = getLocalizedCatalogItem(rawItem);
      const isSelected = activeStar ? AstroLabCore.areSameStar(rawItem.star, activeStar) : false;
      const scopeEval = AstroLabCore.evaluateScopeSuitability(rawItem, currentScopeModel);
      const aavsoUrl = `https://www.aavso.org/vsx/index.php?view=results.get&ident=${encodeURIComponent(rawItem.star)}`;
      return `
        <div class="v6-target-card ${isSelected ? 'active-target' : ''}"
             data-v6-star="${escapeHtml(rawItem.star)}"
             data-v6-ra="${rawItem.ra.toFixed(6)}"
             data-v6-dec="${rawItem.dec.toFixed(6)}"
             data-v6-chart="${escapeHtml(rawItem.chart)}"
             data-v6-kname="${escapeHtml(rawItem.kname)}"
             data-v6-kmag="${escapeHtml(rawItem.kmag)}">
          <div class="v6-target-top">
            <span class="v6-target-name">${escapeHtml(item.star)} <small style="color:${conColor}; font-weight:500;">(${escapeHtml(item.con)})</small>${rawItem.isLiveTargetTool ? '<span class="v6-live-badge target-tool">LIVE API</span>' : (rawItem.isLiveCampaign ? '<span class="v6-live-badge">LIVE</span>' : '')}</span>
            <span class="v6-target-badge">${escapeHtml(item.priority)}</span>
          </div>
          <div class="v6-target-meta"><span class="aavso-sec-pill">${escapeHtml(getStarObservingSectionLabel(rawItem))}</span> • ${escapeHtml(item.type)} • AUID: ${escapeHtml(item.auid)} <span class="sky-alt-pill">${window.computeStarAltitudeForCity ? ((() => { const _l = (typeof currentLang!=="undefined"?currentLang:(document.getElementById("langSelect")?.value||"ru")); const _mx = {ru:"макс.",en:"max.",es:"máx.",de:"max.",fr:"max.",zh:"最高",cs:"max."}[_l]||"max."; const _a = window.computeStarAltitudeForCity(rawItem.ra, rawItem.dec); return `📐 ${_mx} ${Math.round(_a.maxCulmAltDeg)}° • ${_a.compassLabel || ""}`; })()) : ""}</span></div>
          <div class="v6-target-coords-bar" data-live-coords="${escapeHtml(rawItem.star)}" title="RA / Dec (J2000.0) — Seestar & AAVSO Target Tool (${rawItem.ra.toFixed(4)}°, ${rawItem.dec >= 0 ? '+' : ''}${rawItem.dec.toFixed(4)}°)">
            <span>🔭 <strong>RA:</strong> ${formatRaJ2000Hms(rawItem.ra, true)} • <strong>Dec:</strong> ${formatDecJ2000Dms(rawItem.dec)}</span>
            
          </div>
          <div class="v6-target-scope-fit ${scopeEval.status === 'warn' ? 'scope-warn' : ''}" style="display:flex; align-items:center; justify-content:space-between; gap:8px; flex-wrap:wrap; padding:7px 9px;">
            <span class="exp-highlight-pill ${scopeEval.status === 'warn' ? 'warn' : ''}">⏱ ${escapeHtml(({ru:"Выдержка",en:"Exposure",es:"Exposición",de:"Belichtung",fr:"Pose",zh:"曝光",cs:"Expozice",ber:"Exposure"}[(typeof currentLang!=="undefined"?currentLang:"ru")]||"Exposure"))}: <strong>${escapeHtml(scopeEval.expRec || "10 s")}</strong><small style="font-size:10px; font-weight:700; color:#d1fae5; opacity:0.95; margin-left:4px;">SNR ~${scopeEval.snr || 0} • ±${(scopeEval.sigmaMag || 0).toFixed(3)}m</small></span>
            <span style="font-size:11px; opacity:0.9;">🔭 ${escapeHtml(scopeEval.badgeText)}</span>
          </div>
          <div class="v6-customer-mini">🏛 ${escapeHtml(((typeof window.buildScientificStarDossier === "function") ? window.buildScientificStarDossier(rawItem).requester : "Кампания AAVSO"))}</div>
          <div class="v6-target-bottom">
            <span class="v6-target-mag">${escapeHtml(item.magRange.split('(')[0].trim())}</span>
            <div class="v6-target-btns">
              <a href="${aavsoUrl}" target="_blank" rel="noopener noreferrer"
                 class="v6-target-aavso-link"
                 title="${escapeHtml(t("btnGoAavsoObj"))}"
                 data-aavso-obj-link="${escapeHtml(rawItem.star)}">
                🌐 AAVSO ↗
              </a>
              <button type="button" class="v6-target-pick-btn">${escapeHtml(isSelected ? t("btnPickedTarget") : t("btnPickTarget"))}</button>
            </div>
          </div>
        </div>
      `;
    }).join("") + (_v6Rem > 0 ? (() => {
      const _lgV6 = (typeof currentLang !== "undefined") ? currentLang : (document.getElementById("langSelect")?.value || "ru");
      const _v6Lbl = {
        ru: `⬇️ Показать ещё +${Math.min(_v6PageSize, _v6Rem)} (осталось ${_v6Rem})`,
        en: `⬇️ Load More +${Math.min(_v6PageSize, _v6Rem)} (${_v6Rem} remaining)`,
        es: `⬇️ Mostrar +${Math.min(_v6PageSize, _v6Rem)} más (quedan ${_v6Rem})`,
        de: `⬇️ Mehr laden +${Math.min(_v6PageSize, _v6Rem)} (noch ${_v6Rem})`,
        fr: `⬇️ Afficher +${Math.min(_v6PageSize, _v6Rem)} (reste ${_v6Rem})`,
        zh: `⬇️ 加载更多 +${Math.min(_v6PageSize, _v6Rem)}（剩余 ${_v6Rem}）`,
        cs: `⬇️ Zobrazit dalších +${Math.min(_v6PageSize, _v6Rem)} (zbývá ${_v6Rem})`,
        ber: `⬇️ Sken-d ugar +${Math.min(_v6PageSize, _v6Rem)} (qqimen-d ${_v6Rem})`
      }[_lgV6] || `⬇️ Load More +${Math.min(_v6PageSize, _v6Rem)} (${_v6Rem} remaining)`;
      return `<div class="radar-load-more-wrap"><button type="button" class="radar-load-more-btn" id="btnV6RadarLoadMore">${escapeHtml(_v6Lbl)}</button></div>`;
    })() : "");

    if (!listEl.dataset.v135Delegated) {
      listEl.dataset.v135Delegated = "1";
      let _lastV6HoverStar = "";
      listEl.addEventListener("mouseover", (e) => {
        const card = e.target && e.target.closest ? e.target.closest(".v6-target-card") : null;
        if (!card) return;
        const st = card.getAttribute("data-v6-star") || "";
        if (st && st !== _lastV6HoverStar) {
          _lastV6HoverStar = st;
          const item = (window._v6RadarStarMap && window._v6RadarStarMap.get(st)) || null;
          if (item) showRadarObjectTooltip(e, item, AstroLabCore.evaluateScopeSuitability(item, currentScopeModel));
        }
      });
      listEl.addEventListener("mousemove", (e) => {
        if (_lastV6HoverStar) positionRadarTooltip(e);
      });
      listEl.addEventListener("mouseout", (e) => {
        const card = e.target && e.target.closest ? e.target.closest(".v6-target-card") : null;
        if (!card) return;
        const rel = e.relatedTarget;
        if (!rel || !card.contains(rel)) {
          _lastV6HoverStar = "";
          hideRadarObjectTooltip();
        }
      });
      listEl.addEventListener("keydown", (e) => {
        if (e.key !== "Enter" && e.key !== " ") return;
        const card = e.target && e.target.closest ? e.target.closest(".v6-target-card") : null;
        if (!card) return;
        e.preventDefault();
        const st = card.getAttribute("data-v6-star") || "";
        const item = (window._v6RadarStarMap && window._v6RadarStarMap.get(st)) || null;
        if (item && typeof window.openStarFullDossierModal === "function") window.openStarFullDossierModal(item);
      });
      listEl.addEventListener("click", (e) => {
        const loadBtn = e.target && e.target.closest ? e.target.closest("#btnV6RadarLoadMore") : null;
        if (loadBtn) {
          window._v6VisibleLimit = (window._v6VisibleLimit || 60) + 60;
          renderV6RadarDock();
          return;
        }
        const copyBtn = e.target && e.target.closest ? e.target.closest(".coord-copy-btn") : null;
        if (copyBtn) {
          e.stopPropagation();
          const coordsText = copyBtn.getAttribute("data-copy-coords") || "";
          const stName = copyBtn.getAttribute("data-copy-star") || "";
          if (navigator.clipboard && coordsText) navigator.clipboard.writeText(coordsText).catch(() => {});
          copyBtn.textContent = "✓";
          setTimeout(() => { copyBtn.textContent = "📋"; }, 1400);
          showIosNotification(`${stName} — J2000.0`, `${t("toastCoordsCopiedFmt") ? t("toastCoordsCopiedFmt").replace("{coords}", coordsText) : ("Координаты скопированы: " + coordsText)}`, "RA (HMS) / Dec (DMS)", "ok");
          return;
        }
        if (e.target && e.target.closest && e.target.closest(".v6-target-aavso-link")) return;
        const card = e.target && e.target.closest ? e.target.closest(".v6-target-card") : null;
        if (!card) return;
        const st = card.getAttribute("data-v6-star") || "";
        const item = (window._v6RadarStarMap && window._v6RadarStarMap.get(st)) || null;
        hideRadarObjectTooltip();
        if (item && typeof window.openStarFullDossierModal === "function") {
          window.openStarFullDossierModal(item);
        }
      });
    }
  }

  const v6RadarSearchEl = document.getElementById("v6RadarSearch");
  if (v6RadarSearchEl) {
    let _v6SearchTimer = null;
    v6RadarSearchEl.addEventListener("input", () => {
      const val = v6RadarSearchEl.value;
      window._v6VisibleLimit = 60;
      const urgS = document.getElementById("urgentSearchField");
      if (urgS && urgS.value !== val) urgS.value = val;
      clearTimeout(_v6SearchTimer);
      _v6SearchTimer = setTimeout(() => {
        renderV6RadarDock();
        const urgM = document.getElementById("urgentStarsModal");
        if (urgM && urgM.classList.contains("open")) renderUrgentStarsCards(val);
      }, 160);
    });
  }

  // Синхронизация быстрых фильтров по колонкам RA (J2000.0) и Dec (J2000.0) между обоими меню радара
  [["v6FilterRaInput", "urgentFilterRaInput"], ["v6FilterDecInput", "urgentFilterDecInput"]].forEach(([idA, idB]) => {
    const elA = document.getElementById(idA);
    const elB = document.getElementById(idB);
    if (elA) {
      elA.addEventListener("input", () => {
        if (elB && elB.value !== elA.value) elB.value = elA.value;
        renderV6RadarDock();
        renderUrgentStarsCards(urgentSearchField ? urgentSearchField.value : "");
      });
    }
    if (elB) {
      elB.addEventListener("input", () => {
        if (elA && elA.value !== elB.value) elA.value = elB.value;
        renderV6RadarDock();
        renderUrgentStarsCards(urgentSearchField ? urgentSearchField.value : "");
      });
    }
  });

  const v6RadarLimitSelectEl = document.getElementById("v6RadarLimitSelect");
  if (v6RadarLimitSelectEl) {
    v6RadarLimitSelectEl.value = String(currentRadarLimit);
    v6RadarLimitSelectEl.addEventListener("change", (e) => {
      currentRadarLimit = parseInt(e.target.value, 10) || 0;
      safeSetStorage("seestar_radar_limit", String(currentRadarLimit));
      renderV6RadarDock();
    });
  }

  function syncObservingSectionsUI() {
    const isAll = activeObservingSections.size === 0 || activeObservingSections.has("all");
    document.querySelectorAll("[data-radar-filter]").forEach(b => {
      const code = b.getAttribute("data-radar-filter") || "all";
      const active = isAll ? (code === "all") : activeObservingSections.has(code);
      b.classList.toggle("active", active);
    });
    document.querySelectorAll("[data-urgent-sec-chk]").forEach(chk => {
      const code = chk.getAttribute("data-urgent-sec-chk") || "all";
      chk.checked = isAll ? (code === "all") : activeObservingSections.has(code);
    });
  }
  window.syncObservingSectionsUI = syncObservingSectionsUI;

  document.querySelectorAll("[data-radar-filter]").forEach(btn => {
    btn.addEventListener("click", (e) => {
      const code = btn.getAttribute("data-radar-filter") || "all";
      if (code === "all") {
        activeObservingSections.clear();
        activeObservingSections.add("all");
        currentRadarFilter = "all";
      } else if (e.ctrlKey || e.metaKey || e.shiftKey) {
        activeObservingSections.delete("all");
        if (activeObservingSections.has(code)) activeObservingSections.delete(code);
        else activeObservingSections.add(code);
        if (activeObservingSections.size === 0) activeObservingSections.add("all");
        currentRadarFilter = Array.from(activeObservingSections)[0] || "all";
      } else {
        activeObservingSections.clear();
        activeObservingSections.add(code);
        currentRadarFilter = code;
      }
      syncObservingSectionsUI();
      renderV6RadarDock();
      renderUrgentStarsCards(urgentSearchField ? urgentSearchField.value : "");
    });
  });

  document.querySelectorAll("[data-urgent-sec-chk]").forEach(chk => {
    chk.addEventListener("change", () => {
      const code = chk.getAttribute("data-urgent-sec-chk") || "all";
      if (code === "all") {
        if (chk.checked) {
          activeObservingSections.clear();
          activeObservingSections.add("all");
          currentRadarFilter = "all";
        } else {
          activeObservingSections.delete("all");
        }
      } else {
        if (chk.checked) {
          activeObservingSections.delete("all");
          activeObservingSections.add(code);
        } else {
          activeObservingSections.delete(code);
        }
        if (activeObservingSections.size === 0) {
          activeObservingSections.add("all");
          currentRadarFilter = "all";
        } else {
          currentRadarFilter = Array.from(activeObservingSections)[0];
        }
      }
      syncObservingSectionsUI();
      renderV6RadarDock();
      renderUrgentStarsCards(urgentSearchField ? urgentSearchField.value : "");
    });
  });

  const btnApplyUrgentSectionsEl = document.getElementById("btnApplyUrgentSections");
  if (btnApplyUrgentSectionsEl) {
    btnApplyUrgentSectionsEl.addEventListener("click", () => {
      syncObservingSectionsUI();
      renderV6RadarDock();
      renderUrgentStarsCards(urgentSearchField ? urgentSearchField.value : "");
    });
  }

  // ПУНКТ 3: Безошибочное сворачивание и разворачивание бокового радара
  const btnCollapseRadarDock = document.getElementById("btnCollapseRadarDock");
  const v6CollapsedPill = document.getElementById("v6CollapsedPill");
  function setRadarCollapsedState(collapsed) {
    hideRadarObjectTooltip();
    document.body.classList.toggle("radar-dock-collapsed", Boolean(collapsed));
    if (btnCollapseRadarDock) {
      btnCollapseRadarDock.textContent = collapsed ? "»" : "«";
      btnCollapseRadarDock.setAttribute("aria-expanded", collapsed ? "false" : "true");
      btnCollapseRadarDock.title = collapsed ? t("tipExpandRadar") : t("tipCollapseRadar");
    }
    safeSetStorage("seestar_radar_collapsed", collapsed ? "true" : "false");
  }
  if (btnCollapseRadarDock) {
    btnCollapseRadarDock.addEventListener("click", (e) => {
      e.stopPropagation();
      const nextState = !document.body.classList.contains("radar-dock-collapsed");
      setRadarCollapsedState(nextState);
    });
  }
  if (v6CollapsedPill) {
    v6CollapsedPill.addEventListener("click", () => {
      setRadarCollapsedState(false);
    });
  }

  const btnExpandUrgentModalFromDock = document.getElementById("btnExpandUrgentModalFromDock");
  if (btnExpandUrgentModalFromDock) {
    btnExpandUrgentModalFromDock.addEventListener("click", openUrgentModal);
  }

  // ПУНКТ 2 Цикла 1 + ПУНКТЫ 5, 6, 10 Цикла 2: Переключатель «Цветовая панель» (Светлая и Стандартная тёмная тема)
  function applyColorTheme(themeId, notifyUser = false) {
    if (!["dark", "light"].includes(themeId)) themeId = "dark";
    currentColorTheme = themeId;
    safeSetStorage("seestar_color_theme_v6", themeId);

    document.documentElement.setAttribute("data-ui-variant", "v6");
    document.body.setAttribute("data-ui-variant", "v6");
    document.documentElement.setAttribute("data-theme", themeId);
    document.body.setAttribute("data-theme", themeId);

    document.querySelectorAll("[data-theme-btn]").forEach(btn => {
      const isMatch = btn.getAttribute("data-theme-btn") === themeId;
      btn.classList.toggle("active", isMatch);
      btn.setAttribute("aria-pressed", isMatch ? "true" : "false");
    });

    renderV6RadarDock();
    renderUrgentStarsCards(urgentSearchField ? urgentSearchField.value : "");
    if (typeof drawObsActivityChart === "function") drawObsActivityChart();

    if (currentCsvText) {
      drawLightCurve(currentCsvText.split(/\r?\n/));
    }

    if (notifyUser) {
      const msg = themeId === "light"
        ? [t("toastThemeLightTitle"), t("toastThemeLightMsg")]
        : [t("toastThemeDarkTitle"), t("toastThemeDarkMsg")];
      showIosNotification(msg[0], msg[1], "", "ok");
    }
  }

  document.querySelectorAll("[data-theme-btn]").forEach(btn => {
    btn.addEventListener("click", () => {
      const targetTheme = btn.getAttribute("data-theme-btn") || "dark";
      applyColorTheme(targetTheme, true);
    });
  });

  // ПУНКТ 4 и 8 Цикла 2: При запуске приложения оставляем ЧИСТОЕ ПУСТОЕ СОСТОЯНИЕ
  // (без автозагрузки SZ Lyncis, без предзаполненного STARID и без кривой блеска до выбора файла пользователем).
  currentCsvText = "";
  STATE.catalogStarName = null;
  STATE.catalogRa = null;
  STATE.catalogDec = null;
  ["starid", "chart", "kname", "kmag", "ra", "dec"].forEach(id => {
    const el = document.getElementById(id);
    if (el) {
      el.value = "";
      el.removeAttribute("data-user-typed");
    }
  });
  previewCsvText("");


  // ============================================================================
  // МОДУЛЬ 11 (ЦИКЛ 4):
  // - Отключение уведомлений (Настройки -> Уведомления) (Пункт 3)
  // - Гарантированное открытие Welcome Screen первым при старте (Пункт 5)
  // - Расширенный Welcome Screen: метрики, быстрые переходы, лог действий (Пункт 7)
  // - Новый модуль «Мои наблюдения (My Observations)»: таблица, график,
  //   счётчик «Вы не проводили фотометрию X дней», сохранение в БД JSON (Пункт 8)
  // ============================================================================
  const OBS_DB_STORAGE_KEY = "seestar_obs_tracker_db_v1";
  const RECENT_ACTIONS_KEY = "seestar_recent_actions_v1";
  const LEGACY_SEED_IDS = new Set(["obs-1", "obs-2", "obs-3", "obs-4"]);

  // ПУНКТ 13 (ЦИКЛ 5): Никаких предзаполненных чужих данных! База по умолчанию пуста ([]).
  function getDefaultObsRecords() {
    return [];
  }

  // Валидатор записи «Мои наблюдения»: принимает запись ТОЛЬКО если она создана в результате конвертации файла (source === "conversion" и frames > 0)
  function validateObservationLogEntry(entry) {
    if (!entry || typeof entry !== "object") return false;
    if (entry.source && entry.source !== "conversion") return false;
    const pts = Number(entry.frames || entry.recordsCount || 0);
    if (!Number.isFinite(pts) || pts <= 0) return false;
    if (!String(entry.star || "").trim()) return false;
    return true;
  }
  window.validateObservationLogEntry = validateObservationLogEntry;

  // ПУНКТ 14 (ЦИКЛ 5): Двухуровневое сохранение между сессиями (localStorage + IndexedDB SeestarAstroLabDB)
  function syncObsRecordsToIndexedDB(records) {
    try {
      if (!window.indexedDB) return;
      const req = window.indexedDB.open("SeestarAstroLabDB", 1);
      req.onupgradeneeded = (ev) => {
        const db = ev.target.result;
        if (!db.objectStoreNames.contains("observations")) {
          db.createObjectStore("observations", { keyPath: "id" });
        }
      };
      req.onsuccess = (ev) => {
        const db = ev.target.result;
        const tx = db.transaction("observations", "readwrite");
        const store = tx.objectStore("observations");
        store.clear();
        (records || []).forEach(r => {
          if (r && r.id) store.put(r);
        });
      };
    } catch (_) {}
  }

  function loadObsTrackerDb() {
    try {
      const raw = safeGetStorage(OBS_DB_STORAGE_KEY, null);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) {
          // Отфильтровываем старые демо-записи obs-1..obs-4, которые пользователь не совершал
          const cleaned = parsed.filter(r => r && !LEGACY_SEED_IDS.has(String(r.id || "")) && Number(r.frames || 0) > 0);
          if (cleaned.length !== parsed.length) {
            safeSetStorage(OBS_DB_STORAGE_KEY, JSON.stringify(cleaned));
          }
          return cleaned;
        }
      }
    } catch (_) {}
    return [];
  }

  function saveObsTrackerDb(records) {
    try {
      const cleanList = Array.isArray(records) ? records : [];
      safeSetStorage(OBS_DB_STORAGE_KEY, JSON.stringify(cleanList));
      syncObsRecordsToIndexedDB(cleanList);
    } catch (_) {}
  }

  let obsTrackerRecords = loadObsTrackerDb();
  window.getObsTrackerRecords = () => obsTrackerRecords;
  window.saveObsTrackerDb = saveObsTrackerDb;

  function computeDaysSinceLastPhotometry(records) {
    if (!Array.isArray(records) || records.length === 0) return 0;
    let maxTs = 0;
    for (const r of records) {
      const ts = Date.parse(String(r.date || "") + "T12:00:00");
      if (!isNaN(ts) && ts > maxTs) maxTs = ts;
    }
    if (!maxTs) return 0;
    const nowNoon = Date.parse(new Date().toISOString().slice(0, 10) + "T12:00:00");
    return Math.max(0, Math.round((nowNoon - maxTs) / 86400000));
  }
  window.computeDaysSinceLastPhotometry = computeDaysSinceLastPhotometry;

  function logRecentAction(actionKey, replacements = {}) {
    let list = [];
    try {
      const raw = safeGetStorage(RECENT_ACTIONS_KEY, null);
      if (raw) list = JSON.parse(raw) || [];
    } catch (_) {}
    const timeStr = new Date().toLocaleTimeString(((typeof currentLang !== "undefined" ? currentLang : (window.STATE?.lang || "ru")) === "ru" ? "ru-RU" : "en-GB"), { hour: "2-digit", minute: "2-digit" });
    list.unshift({ time: timeStr, key: actionKey, params: replacements });
    list = list.slice(0, 6);
    safeSetStorage(RECENT_ACTIONS_KEY, JSON.stringify(list));
  }

  function renderSplashQuickHub() {
    // Пункт 4: Блок «Панель управления обсерваторией и быстрые переходы» удалён с экрана приветствия
    return;
  }

  window.parseObsUserDateToIso = function(rawVal) {
    const s = String(rawVal || "").trim();
    if (!s) return "";
    let y = 0, m = 0, d = 0;
    let m1 = s.match(/^(\d{4})[-.\/](\d{1,2})[-.\/](\d{1,2})$/);
    let m2 = s.match(/^(\d{1,2})[-.\/](\d{1,2})[-.\/](\d{4})$/);
    if (m1) {
      y = Number(m1[1]); m = Number(m1[2]); d = Number(m1[3]);
    } else if (m2) {
      d = Number(m2[1]); m = Number(m2[2]); y = Number(m2[3]);
    } else {
      return null;
    }
    if (y < 1900 || y > 2100 || m < 1 || m > 12 || d < 1 || d > 31) return null;
    const dt = new Date(Date.UTC(y, m - 1, d));
    if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== m - 1 || dt.getUTCDate() !== d) return null;
    return `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
  };

  function getFilteredObsRecords() {
    const fDateEl = document.getElementById("obsFilterDate");
    const fStarEl = document.getElementById("obsFilterStar");
    const fScopeEl = document.getElementById("obsFilterScope");
    const rawDateVal = (fDateEl && fDateEl.value || "").trim();
    const parsedIso = rawDateVal ? window.parseObsUserDateToIso(rawDateVal) : "";
    const starVal = (fStarEl && fStarEl.value || "").trim().toLowerCase();
    const scopeVal = (fScopeEl && fScopeEl.value || "ALL").trim();

    return obsTrackerRecords.filter(rec => {
      if (rawDateVal) {
        if (parsedIso) {
          if (String(rec.date || "") !== parsedIso) return false;
        } else if (rawDateVal.length >= 8) {
          return false;
        }
      }
      if (starVal && !String(rec.star || "").toLowerCase().includes(starVal)) return false;
      if (scopeVal && scopeVal !== "ALL" && String(rec.scope || "S50") !== scopeVal) return false;
      return true;
    });
  }

  // ПУНКТ 12 (ЦИКЛ 5): Редизайн графика наблюдений в высоком разрешении (HiDPI, devicePixelRatio >= 2)
  // с плавной кубической кривой Безье (Cubic-Bezier Spline Area Chart), градиентной заливкой и интерактивным тултипом!
  let _obsChartHitNodes = [];
  function drawObsActivityChart(recordsToPlot) {
    const canvas = document.getElementById("obsActivityChartCanvas");
    if (!canvas) return;
    const ctx = canvas.getContext("2d");

    if (!canvas.clientWidth) return;
    const cssW = Math.max(480, canvas.clientWidth);
    const cssH = Math.max(190, canvas.clientHeight || 220);
    const dpr = Math.max(2, window.devicePixelRatio || 2);
    if (canvas.width !== Math.round(cssW * dpr) || canvas.height !== Math.round(cssH * dpr)) {
      canvas.width = Math.round(cssW * dpr);
      canvas.height = Math.round(cssH * dpr);
    }
    ctx.save();
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, cssW, cssH);

    const cs = getComputedStyle(document.body);
    const isLight = document.body.getAttribute("data-theme") === "light";
    const primaryStroke = cs.getPropertyValue("--chart-bar-fill").trim() || (isLight ? "#0284c7" : "#38bdf8");
    const accentStroke = cs.getPropertyValue("--chart-line-stroke").trim() || (isLight ? "#0d9488" : "#34d399");
    const gridColor = cs.getPropertyValue("--chart-grid-stroke").trim() || (isLight ? "rgba(15,23,42,0.09)" : "rgba(148,163,184,0.16)");
    const textColor = cs.getPropertyValue("--chart-axis-text").trim() || (isLight ? "#334155" : "#cbd5e1");

    const sourceList = Array.isArray(recordsToPlot) ? recordsToPlot : getFilteredObsRecords();
    const sorted = [...sourceList].sort((a, b) => String(a.date).localeCompare(String(b.date))).slice(-14);

    const padL = 56, padR = 28, padT = 28, padB = 38;
    const plotW = cssW - padL - padR;
    const plotH = cssH - padT - padB;

    // Горизонтальная сетка
    const maxPts = sorted.length ? Math.max(20, ...sorted.map(r => Number(r.frames) || 0)) : 100;
    ctx.strokeStyle = gridColor;
    ctx.lineWidth = 1;
    for (let k = 0; k <= 4; k++) {
      const y = padT + (plotH * k) / 4;
      ctx.beginPath();
      ctx.moveTo(padL, y);
      ctx.lineTo(cssW - padR, y);
      ctx.stroke();
      const val = Math.round(maxPts * (1 - k / 4));
      ctx.fillStyle = textColor;
      ctx.font = "600 11px ui-monospace, SFMono-Regular, Consolas, monospace";
      ctx.textAlign = "right";
      ctx.fillText(`${val}`, padL - 8, y + 4);
    }

    _obsChartHitNodes = [];
    if (!sorted.length) {
      ctx.fillStyle = textColor;
      ctx.font = "600 12.5px -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif";
      ctx.textAlign = "center";
      ctx.fillText(t("obsEmptyTableMsg") || "Сконвертируйте CSV-файл Seestar для построения графика наблюдений", cssW / 2, cssH / 2 + 4);
      ctx.restore();
      return;
    }

    const pts = sorted.map((rec, i) => {
      const countVal = Number(rec.frames) || 0;
      const cx = sorted.length === 1
        ? padL + plotW / 2
        : padL + (i / (sorted.length - 1)) * plotW;
      const cy = padT + plotH - (Math.min(countVal, maxPts) / maxPts) * plotH;
      return { cx, cy, rec, countVal };
    });
    _obsChartHitNodes = pts;

    // Градиентная заливка под кривой Безье
    const areaGrad = ctx.createLinearGradient(0, padT, 0, padT + plotH);
    areaGrad.addColorStop(0, isLight ? "rgba(2, 132, 199, 0.34)" : "rgba(56, 189, 248, 0.36)");
    areaGrad.addColorStop(1, isLight ? "rgba(2, 132, 199, 0.02)" : "rgba(56, 189, 248, 0.01)");

    if (pts.length === 1) {
      const p0 = pts[0];
      const barW = 44;
      ctx.fillStyle = areaGrad;
      ctx.beginPath();
      if (ctx.roundRect) ctx.roundRect(p0.cx - barW / 2, p0.cy, barW, padT + plotH - p0.cy, 6);
      else ctx.rect(p0.cx - barW / 2, p0.cy, barW, padT + plotH - p0.cy);
      ctx.fill();
    } else {
      ctx.beginPath();
      ctx.moveTo(pts[0].cx, padT + plotH);
      ctx.lineTo(pts[0].cx, pts[0].cy);
      for (let i = 0; i < pts.length - 1; i++) {
        const p0 = pts[i];
        const p1 = pts[i + 1];
        const midX = (p0.cx + p1.cx) / 2;
        ctx.bezierCurveTo(midX, p0.cy, midX, p1.cy, p1.cx, p1.cy);
      }
      ctx.lineTo(pts[pts.length - 1].cx, padT + plotH);
      ctx.closePath();
      ctx.fillStyle = areaGrad;
      ctx.fill();

      // Плавная сглаженная кривая Безье (Cubic-Bezier Spline)
      ctx.beginPath();
      ctx.moveTo(pts[0].cx, pts[0].cy);
      for (let i = 0; i < pts.length - 1; i++) {
        const p0 = pts[i];
        const p1 = pts[i + 1];
        const midX = (p0.cx + p1.cx) / 2;
        ctx.bezierCurveTo(midX, p0.cy, midX, p1.cy, p1.cx, p1.cy);
      }
      ctx.strokeStyle = primaryStroke;
      ctx.lineWidth = 2.75;
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.stroke();
    }

    // Точки замеров и подписи
    pts.forEach((p) => {
      ctx.beginPath();
      ctx.arc(p.cx, p.cy, 6.5, 0, Math.PI * 2);
      ctx.fillStyle = isLight ? "rgba(2, 132, 199, 0.18)" : "rgba(56, 189, 248, 0.25)";
      ctx.fill();

      ctx.beginPath();
      ctx.arc(p.cx, p.cy, 4, 0, Math.PI * 2);
      ctx.fillStyle = accentStroke;
      ctx.fill();
      ctx.lineWidth = 1.8;
      ctx.strokeStyle = isLight ? "#ffffff" : "#0f172a";
      ctx.stroke();

      ctx.fillStyle = textColor;
      ctx.font = "700 10.5px -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif";
      ctx.textAlign = "center";
      ctx.fillText(`${p.rec.star} (${p.countVal})`, p.cx, Math.max(14, p.cy - 10));

      ctx.font = "600 10px ui-monospace, SFMono-Regular, Consolas, monospace";
      ctx.fillText(String(p.rec.date).slice(5), p.cx, padT + plotH + 18);
    });

    ctx.restore();
  }

  // Интерактивный тултип при наведении на узлы графика «Мои наблюдения»
  (function bindObsChartHover() {
    const canvas = document.getElementById("obsActivityChartCanvas");
    const tip = document.getElementById("obsChartHoverTooltip");
    if (!canvas || !tip) return;
    canvas.addEventListener("mousemove", (ev) => {
      const rect = canvas.getBoundingClientRect();
      const mx = ev.clientX - rect.left;
      const my = ev.clientY - rect.top;
      let hit = null;
      let bestDist = 26;
      for (const node of _obsChartHitNodes) {
        const d = Math.hypot(mx - node.cx, my - node.cy);
        if (d < bestDist) {
          bestDist = d;
          hit = node;
        }
      }
      if (hit) {
        tip.style.display = "block";
        tip.innerHTML = `<strong>${escapeHtml(hit.rec.star)}</strong> • ${escapeHtml(hit.rec.date)}<br>` +
                        `Записей в файле: <strong>${Number(hit.rec.frames) || 0}</strong> (${escapeHtml(hit.rec.filter || "TG")})<br>` +
                        `Телескоп: <strong>Seestar ${escapeHtml(hit.rec.scope || "S50")}</strong>`;
        const leftPx = Math.min(rect.width - 190, Math.max(8, hit.cx - 70));
        const topPx = Math.max(8, hit.cy - 58);
        tip.style.left = `${leftPx}px`;
        tip.style.top = `${topPx}px`;
      } else {
        tip.style.display = "none";
      }
    });
    canvas.addEventListener("mouseleave", () => {
      tip.style.display = "none";
    });

})();

  function renderObsTrackerModal() {
    const daysTextEl = document.getElementById("obsDaysSinceText");
    const statsTextEl = document.getElementById("obsSummaryStatsText");
    const tbody = document.getElementById("obsTrackerTableBody");
    if (!tbody) return;

    const daysIdle = computeDaysSinceLastPhotometry(obsTrackerRecords);
    if (daysTextEl) {
      daysTextEl.textContent = t("obsDaysSinceFmt").replace("{days}", daysIdle);
    }
    const filteredList = getFilteredObsRecords();
    const totalMins = filteredList.reduce((acc, r) => acc + (Number(r.durationMin) || 0), 0);
    const totalFrames = filteredList.reduce((acc, r) => acc + (Number(r.frames) || 0), 0);
    if (statsTextEl) {
      statsTextEl.textContent = t("obsSummaryStatsFmt")
        .replace("{count}", filteredList.length)
        .replace("{mins}", totalMins)
        .replace("{frames}", totalFrames);
    }

    const sortedDesc = [...filteredList].sort((a, b) => String(b.date).localeCompare(String(a.date)));
    if (!sortedDesc.length) {
      tbody.innerHTML = `<tr><td colspan="7" style="text-align:center; padding:18px; color:var(--ios-text-secondary);">${escapeHtml(t("obsEmptyTableMsg"))}</td></tr>`;
    } else {
      tbody.innerHTML = sortedDesc.map((rec, rowIdx) => `
        <tr data-obs-id="${escapeHtml(String(rec.id || ""))}">
          <td><strong>${escapeHtml(rec.star)}</strong></td>
          <td style="font-family:var(--font-mono);">${escapeHtml(rec.date)}</td>
          <td><strong>${Number(rec.durationMin) || 0}</strong> ${escapeHtml(t("obsMinUnit"))}</td>
          <td><strong>${Number(rec.frames) || 0}</strong> ${escapeHtml(t("obsFramesUnit"))} (${escapeHtml(rec.filter || "TG")})</td>
          <td>Seestar ${escapeHtml(rec.scope || "S50")}</td>
          <td>${
            rec.status === "lab_unsubmitted"
              ? (rec.aavsoEligible
                  ? `<span class="obs-qg-badge eligible">${escapeHtml(t("qgEligibleBadge"))}</span>`
                  : `<span class="obs-qg-badge blocked" title="${escapeHtml(rec.aavsoBlockReason || "")}">${escapeHtml(t("qgBlockedBadge"))}</span>`)
              : `<span class="obs-qg-badge converted">✓ AAVSO</span>`
          }</td>
          <td style="text-align:center; white-space:nowrap;">
            ${(rec.status === "lab_unsubmitted" && rec.aavsoEligible)
              ? `<button type="button" class="ios-btn tiny btn-obs-prep-aavso" data-prep-id="${escapeHtml(String(rec.id || ""))}" title="${escapeHtml(t("btnPrepareAavso"))}" style="width:auto; padding:3px 8px; font-size:10.5px; margin-right:4px;">📤</button>`
              : ""}
            <button type="button" class="ios-btn secondary tiny btn-obs-del"
                    data-del-id="${escapeHtml(String(rec.id || ""))}"
                    data-del-idx="${rowIdx}"
                    title="${escapeHtml(t("btnObsDelete"))}"
                    aria-label="${escapeHtml(t("btnObsDelete"))}">
              <svg viewBox="0 0 24 24" aria-hidden="true">
                <polyline points="3 6 5 6 21 6"></polyline>
                <path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"></path>
                <path d="M10 11v6"></path>
                <path d="M14 11v6"></path>
                <path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"></path>
              </svg>
            </button>
          </td>
        </tr>
      `).join("");
    }

    tbody.querySelectorAll(".btn-obs-prep-aavso").forEach(btn => {
      btn.addEventListener("click", (ev) => {
        ev.preventDefault();
        ev.stopPropagation();
        const prepId = btn.getAttribute("data-prep-id");
        const rec = obsTrackerRecords.find(r => String(r && r.id || "") === String(prepId));
        if (!rec) return;
        if (typeof window.setAstrolabWorkflowMode === "function") window.setAstrolabWorkflowMode("aavso");
        const starEl = document.getElementById("starid");
        if (starEl && rec.star) {
          starEl.value = rec.star;
          starEl.dispatchEvent(new Event("input", { bubbles: true }));
        }
        if (Array.isArray(rec.aavsoPoints) && rec.aavsoPoints.length && typeof window._STATE_CURVES === "object") {
          window._STATE_CURVES.currentSessionPoints = rec.aavsoPoints.map(pt => ({
            jd: Number(pt[0]), mag: Number(pt[1]), merr: Number(pt[2] || 0.02),
            band: rec.filter || "TG", source: "LAB_IMPORT", star: rec.star, layer: "current", isUser: true
          }));
        }
        document.getElementById("obsTrackerModal")?.classList.remove("open");
        document.getElementById("accConvertSection")?.setAttribute("open", "");
        if (typeof showIosNotification === "function") {
          showIosNotification("📤 " + (rec.star || ""), t("btnPrepareAavso"), "", "info");
        }
      });
    });
    tbody.querySelectorAll(".btn-obs-del").forEach(btn => {
      btn.addEventListener("click", (ev) => {
        ev.preventDefault();
        ev.stopPropagation();
        const delId = btn.getAttribute("data-del-id");
        const delIdx = parseInt(btn.getAttribute("data-del-idx"), 10);
        const targetRec = (!isNaN(delIdx) && sortedDesc[delIdx]) ? sortedDesc[delIdx] : null;
        const prevLen = obsTrackerRecords.length;
        if (delId) {
          obsTrackerRecords = obsTrackerRecords.filter(r => String(r && r.id || "") !== String(delId));
        }
        if (obsTrackerRecords.length === prevLen && targetRec) {
          const exactPos = obsTrackerRecords.indexOf(targetRec);
          if (exactPos !== -1) {
            obsTrackerRecords.splice(exactPos, 1);
          }
        }
        saveObsTrackerDb(obsTrackerRecords);
        if (targetRec && typeof window.removeConvertedRecordsByObsEntry === "function") {
          window.removeConvertedRecordsByObsEntry(targetRec);
        }
        renderObsTrackerModal();
        if (targetRec && typeof showIosNotification === "function") {
          const tc = document.getElementById("toastContainer");
          showIosNotification(
            "🗑️ Замер удалён из «Моих наблюдений»",
            `${targetRec.star || ""} (${targetRec.date || ""}) — теперь файл можно загрузить повторно`,
            "",
            "info"
          );
          const lastToast = tc && tc.lastElementChild ? tc.lastElementChild.querySelector(".ios-toast-content") : null;
          if (lastToast) {
            const undoBtn = document.createElement("button");
            undoBtn.type = "button";
            undoBtn.className = "ios-toast-undo-btn";
            undoBtn.textContent = "↩️ Отменить удаление";
            undoBtn.addEventListener("click", () => {
              obsTrackerRecords.push(targetRec);
              saveObsTrackerDb(obsTrackerRecords);
              renderObsTrackerModal();
              if (typeof window.refreshLocalizedObsDatePicker === "function") window.refreshLocalizedObsDatePicker();
              undoBtn.closest(".ios-toast")?.remove();
            });
            lastToast.appendChild(undoBtn);
          }
        }
        if (typeof window.refreshLocalizedObsDatePicker === "function") {
          window.refreshLocalizedObsDatePicker();
        }
      });
    });

    drawObsActivityChart(filteredList);
  }
  window.renderObsTrackerModal = renderObsTrackerModal;

  // ПУНКТ 13 (ЦИКЛ 5): Запись добавляется СТРОГО по результатам конвертации файла (frames = число научных строк в сконвертированном CSV)
  function addObsTrackerRecord(star, dateStr, durationMin, frames, scope, filter = "TG", source = "conversion", fileName = "") {
    const cleanStar = String(star || "").trim() || "SZ Lyn";
    const cleanDate = String(dateStr || "").trim() || new Date().toISOString().slice(0, 10);
    const fr = Math.max(0, parseInt(frames, 10) || 0);
    const dur = Math.max(1, parseInt(durationMin, 10) || Math.max(1, Math.round(fr * 0.5)));
    const sc = VALID_SCOPES.includes(scope) ? scope : currentScopeModel;
    const candidate = {
      id: "obs-" + Date.now() + "-" + Math.floor(Math.random() * 1000),
      star: cleanStar,
      date: cleanDate,
      durationMin: dur,
      frames: fr,
      recordsCount: fr,
      filter: filter || "TG",
      scope: sc,
      source: source || "conversion",
      fileName: String(fileName || "")
    };
    if (!validateObservationLogEntry(candidate)) {
      return null;
    }
    obsTrackerRecords.push(candidate);
    saveObsTrackerDb(obsTrackerRecords);
    logRecentAction("actObsAddedFmt", { star: cleanStar, mins: dur });
    renderObsTrackerModal();
    return candidate;
  }
  window.addObsTrackerRecord = addObsTrackerRecord;

  const openObsTracker = () => {
    if (obsTrackerModal) {
      obsTrackerModal.classList.add("open");
      syncModalBodyLock();
      renderObsTrackerModal();
    }
  };
  const closeObsTracker = () => {
    if (obsTrackerModal) {
      obsTrackerModal.classList.remove("open");
      syncModalBodyLock();
    }
  };
  window.openObsTracker = openObsTracker;
  window.closeObsTracker = closeObsTracker;

  const btnOpenObsTracker = document.getElementById("btnOpenObsTracker");
  if (btnOpenObsTracker) btnOpenObsTracker.addEventListener("click", openObsTracker);
  ["btnCloseObsTracker", "btnAckObsTracker"].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.addEventListener("click", closeObsTracker);
  });
  if (obsTrackerModal) {
    obsTrackerModal.addEventListener("click", (e) => {
      if (e.target === obsTrackerModal) closeObsTracker();
    });
  }

  // ПУНКТ 15: Обработчики 3 фильтров (Дата, Поиск по звезде, Поиск по телескопу) и кнопки «Удалить все»
  ["obsFilterDate", "obsFilterStar", "obsFilterScope"].forEach(fid => {
    const el = document.getElementById(fid);
    if (el) {
      el.addEventListener("input", () => renderObsTrackerModal());
      el.addEventListener("change", () => renderObsTrackerModal());
    }
  });
  const btnObsResetFilters = document.getElementById("btnObsResetFilters");
  if (btnObsResetFilters) {
    btnObsResetFilters.addEventListener("click", () => {
      const fDate = document.getElementById("obsFilterDate");
      const fStar = document.getElementById("obsFilterStar");
      const fScope = document.getElementById("obsFilterScope");
      if (fDate) fDate.value = "";
      if (fStar) fStar.value = "";
      if (fScope) fScope.value = "ALL";
      renderObsTrackerModal();
    });
  }
  const btnObsDeleteAll = document.getElementById("btnObsDeleteAll");
  if (btnObsDeleteAll) {
    btnObsDeleteAll.addEventListener("click", () => {
      obsTrackerRecords = [];
      saveObsTrackerDb(obsTrackerRecords);
      renderObsTrackerModal();
    });
  }

  // ПУНКТ 7: Обработчики селекторов сортировки в окне «Срочно» и в боковом радаре
  const urgentSortSelect = document.getElementById("urgentSortSelect");
  if (urgentSortSelect) {
    urgentSortSelect.addEventListener("change", () => {
      const qEl = document.getElementById("urgentSearchField");
      renderUrgentStarsCards(qEl ? qEl.value : "");
    });
  }
  const v6RadarSortSelect = document.getElementById("v6RadarSortSelect");
  if (v6RadarSortSelect) {
    v6RadarSortSelect.addEventListener("change", () => {
      renderV6RadarDock();
    });
  }

  // ПУНКТЫ 18 и 19 + ПУНКТ 5: Скрытый от пользователя автоматический показ окна поддержки проекта
  // строго на 3-й вход в приложение и далее 1 раз в месяц (каждые 30 дней).
  const DONATE_LAUNCH_COUNT_KEY = "seestar_donate_launch_count";
  const DONATE_LAST_SHOWN_TS_KEY = "seestar_donate_last_shown_ts";
  const THIRTY_DAYS_MS = 30 * 86400 * 1000;
  let _donateSessionCounted = false;
  let _donateAutoPendingOpen = false;

  const donateModal = document.getElementById("donateModal");
  function openDonateModal() {
    if (!donateModal) return;
    donateModal.classList.add("open");
    syncModalBodyLock();
  }
  function closeDonateModal() {
    if (!donateModal) return;
    _donateAutoPendingOpen = false;
    safeSetStorage(DONATE_LAST_SHOWN_TS_KEY, String(Date.now()));
    donateModal.classList.remove("open");
    syncModalBodyLock();
  }
  window.openDonateModal = openDonateModal;
  window.closeDonateModal = closeDonateModal;

  function evaluateDonateModalSchedule(nowTs = Date.now(), incrementLaunch = true) {
    let launchCount = parseInt(safeGetStorage(DONATE_LAUNCH_COUNT_KEY, "0"), 10) || 0;
    const hostAlreadyIncremented = Boolean(
      window.__SEESTAR_DISK_STORE__ && window.__SEESTAR_DISK_STORE__.seestar_host_counted_this_launch === "1"
    );
    if (incrementLaunch) {
      if (hostAlreadyIncremented && !_donateSessionCounted) {
        _donateSessionCounted = true;
      } else {
        launchCount += 1;
        _donateSessionCounted = true;
        safeSetStorage(DONATE_LAUNCH_COUNT_KEY, String(launchCount));
      }
    }
    const lastShownTs = parseInt(safeGetStorage(DONATE_LAST_SHOWN_TS_KEY, "0"), 10) || 0;
    if (launchCount === 3 && lastShownTs === 0) {
      safeSetStorage(DONATE_LAST_SHOWN_TS_KEY, String(nowTs));
      return { shouldShow: true, launchCount, reason: "third_launch" };
    }
    if (launchCount > 3 && lastShownTs === 0) {
      safeSetStorage(DONATE_LAST_SHOWN_TS_KEY, String(nowTs));
      return { shouldShow: true, launchCount, reason: "third_launch_catchup" };
    }
    if (launchCount > 3 && lastShownTs > 0 && (nowTs - lastShownTs) >= THIRTY_DAYS_MS) {
      safeSetStorage(DONATE_LAST_SHOWN_TS_KEY, String(nowTs));
      return { shouldShow: true, launchCount, reason: "monthly_interval" };
    }
    return { shouldShow: false, launchCount, reason: "not_due" };
  }
  window.evaluateDonateModalSchedule = evaluateDonateModalSchedule;

  const btnOpenDonateModal = document.getElementById("btnOpenDonateModal");
  if (btnOpenDonateModal) {
    btnOpenDonateModal.addEventListener("click", openDonateModal);
  }
  const btnCloseDonateModal = document.getElementById("btnCloseDonateModal");
