  window.buildScientificStarDossier = buildScientificStarDossier; function buildScientificStarDossier(rawItem) {
    const lg = getActiveLangCode();
    const tpl = DOSSIER_I18N_TEMPLATES[lg] || DOSSIER_I18N_TEMPLATES.en;
    const item = (typeof window.getLocalizedCatalogItem === "function") ? window.getLocalizedCatalogItem(rawItem) : rawItem;
    const tStr = String(rawItem.type || "");
    const pStr = String(rawItem.priority || "");

    let requester = tpl.defReq;
    let whyUrgent = item.comment || tpl.defUrg;
    let whatWeSeek = tpl.defSeek;

    if (rawItem.star === "T CrB" || tStr.includes("NR")) {
      requester = tpl.nrReq;
      whyUrgent = tpl.nrUrg;
      whatWeSeek = tpl.nrSeek;
    } else if (rawItem.star === "SZ Lyn" || tStr.includes("DSCT")) {
      requester = tpl.dsctReq;
      whyUrgent = tpl.dsctUrg;
      whatWeSeek = tpl.dsctSeek;
    } else if (tStr.includes("UG") || tStr.includes("NA") || tStr.includes("NB") || tStr.includes("NC")) {
      requester = tpl.ugReq;
      whyUrgent = tpl.ugUrg;
      whatWeSeek = tpl.ugSeek;
    } else if (tStr.includes("EP") || pStr.includes("Экзопланета")) {
      requester = tpl.epReq;
      whyUrgent = tpl.epUrg;
      whatWeSeek = tpl.epSeek;
    } else if (tStr.includes("ZAND") || pStr.includes("Симбиотическая")) {
      requester = tpl.zandReq;
      whyUrgent = tpl.zandUrg;
      whatWeSeek = tpl.zandSeek;
    } else if (tStr.includes("EA") || tStr.includes("EB") || tStr.includes("EW") || pStr.includes("Затмения")) {
      requester = tpl.eaReq;
      whyUrgent = tpl.eaUrg;
      whatWeSeek = tpl.eaSeek;
    }

    const subMeta = tpl.subMetaFmt
      .replace("{auid}", rawItem.auid || "—")
      .replace("{con}", item.con || rawItem.con || "—")
      .replace("{mag}", item.magRange || rawItem.magRange || "—")
      .replace("{chart}", rawItem.chart || "—")
      .replace("{kname}", rawItem.kname || "—")
      .replace("{kmag}", rawItem.kmag || "—");

    const coordsTxt = tpl.coordsFmt
      .replace("{ra}", `${formatRaJ2000Hms(rawItem.ra, false)} (${Number(rawItem.ra).toFixed(4)}`)
      .replace("{dec}", `${formatDecJ2000Dms(rawItem.dec)} (${Number(rawItem.dec) >= 0 ? '+' : ''}${Number(rawItem.dec).toFixed(4)}`);

    return {
      title: `🌟 ${item.star} (${item.con || rawItem.con})`,
      subMeta: subMeta,
      desc: `${item.desc} (${item.type}). ${coordsTxt}`,
      urgency: whyUrgent,
      requester: requester,
      seek: `${whatWeSeek} ${item.comment || ""}`.trim()
    };
  }
  window.buildScientificStarDossier = buildScientificStarDossier;

  // Благородное золотое свечение частиц (без кислотных цветов) при выборе звезды
  let _fireworksAnimId = null;
  function startLuckFireworksAnimation() {
    const fwCanvas = document.getElementById("luckFireworksCanvas");
    if (!fwCanvas) return;
    if (_fireworksAnimId) cancelAnimationFrame(_fireworksAnimId);

    const ctx = fwCanvas.getContext("2d");
    const W = fwCanvas.width = fwCanvas.parentElement?.clientWidth || 720;
    const H = fwCanvas.height = fwCanvas.parentElement?.clientHeight || 580;

    // Только тёплые золотисто-янтарные и жемчужные оттенки (в гармонии с колесом из аниме)
    const goldPalette = ["#f6e3aa", "#e2c278", "#d4af37", "#fff8dc"];
    const particles = [];

    function spawnGoldBurst(cx, cy) {
      const count = 28;
      for (let i = 0; i < count; i++) {
        const angle = (Math.PI * 2 * i) / count + (Math.random() - 0.5) * 0.2;
        const speed = 1.2 + Math.random() * 2.8;
        particles.push({
          x: cx,
          y: cy,
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed - 0.5,
          alpha: 0.9,
          decay: 0.015 + Math.random() * 0.01,
          r: 1.5 + Math.random() * 1.8,
          color: goldPalette[i % goldPalette.length]
        });
      }
    }

    spawnGoldBurst(W * 0.30, H * 0.24);
    spawnGoldBurst(W * 0.70, H * 0.24);

    let frames = 0;
    function step() {
      frames++;
      ctx.clearRect(0, 0, W, H);
      for (let i = particles.length - 1; i >= 0; i--) {
        const p = particles[i];
        p.x += p.vx;
        p.y += p.vy;
        p.vy += 0.04;
        p.vx *= 0.985;
        p.alpha -= p.decay;
        if (p.alpha <= 0.02) {
          particles.splice(i, 1);
          continue;
        }
        ctx.save();
        ctx.globalAlpha = Math.max(0, p.alpha);
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }
      if (particles.length > 0 && frames < 160) {
        _fireworksAnimId = requestAnimationFrame(step);
      } else {
        ctx.clearRect(0, 0, W, H);
        _fireworksAnimId = null;
      }
    }
    _fireworksAnimId = requestAnimationFrame(step);
  }

  let _casinoBlinkTimer = null;
  function triggerStarIdCasinoJackpotBlink(durationMs = 6000) {
    const starEl = document.getElementById("starid");
    const acc1 = document.getElementById("accObserverStar");
    if (acc1 && !acc1.open) acc1.open = true;
    if (!starEl) return;
    if (_casinoBlinkTimer) clearTimeout(_casinoBlinkTimer);
    starEl.classList.add("casino-jackpot-blink");
    _casinoBlinkTimer = setTimeout(() => {
      starEl.classList.remove("casino-jackpot-blink");
      _casinoBlinkTimer = null;
    }, durationMs);
  }
  window.triggerStarIdCasinoJackpotBlink = triggerStarIdCasinoJackpotBlink;

  let _wheelAnimFrameId = null;
  let _forceStopWheelSpinFn = null;
  let _lastSelectedWinnerItem = null;

  function clearLuckSpinTimers() {
    if (_wheelAnimFrameId) {
      cancelAnimationFrame(_wheelAnimFrameId);
      _wheelAnimFrameId = null;
    }
    _forceStopWheelSpinFn = null;
    document.querySelectorAll(".v6-target-card.casino-slot-highlight").forEach(el => el.classList.remove("casino-slot-highlight"));
  }

  // ПУНКТ 1: Истинное случайное перемешивание (Fisher-Yates + криптографический ГСЧ)
  // актуального списка срочных звёзд из Радара целей и каталога AAVSO
  function getShuffledUrgentStarsPool(scopeModel) {
    const baseCat = Array.isArray(window.AAVSO_URGENT_CATALOGUE) ? window.AAVSO_URGENT_CATALOGUE.slice() : [];
    const byName = new Map();
    for (const item of baseCat) {
      if (item && item.star) byName.set(String(item.star).trim().toLowerCase(), item);
    }
    // Дополнительно учитываем карточки, отображённые сейчас в живом списке Радара целей (#v6RadarListContainer)
    document.querySelectorAll("#v6RadarListContainer [data-v6-star], #urgentStarsGridContainer [data-urgent-star]").forEach(el => {
      const stName = (el.getAttribute("data-v6-star") || el.getAttribute("data-urgent-star") || "").trim();
      if (stName && !byName.has(stName.toLowerCase())) {
        byName.set(stName.toLowerCase(), {
          star: stName,
          con: "—",
          type: "Urgent Target",
          priority: "🔥 Срочно",
          auid: "AAVSO",
          magRange: "9.0–14.0",
          ra: 120.0,
          dec: 30.0,
          chart: "VSP",
          kname: "AUID",
          kmag: "11.0",
          desc: stName,
          comment: ""
        });
      }
    });

    const activeScope = scopeModel || window._currentScopeModel || document.getElementById("headerScopeSelect")?.value || document.querySelector("[data-scope-tab].active")?.getAttribute("data-scope-tab") || "S50";
    const allItems = Array.from(byName.values());
    // Строгий фильтр по оптическому профилю выбранного телескопа (S30 / S30 PLUS / S30PRO / S50 / S50PRO):
    // исключаем звёзды, которые вызывают пересвет матрицы (< brightLimit) или уходят тусклее проницающей способности телескопа (> magLimit)
    const activeVisMode = document.getElementById("v6HemisphereSelect")?.value || "city";
    const strictlySuitable = allItems.filter(it => {
      if (typeof window.matchesObserverHemisphereFilter === "function") {
        // В барабан попадают только звёзды, видимые в полушарии/городе пользователя!
        const checkMode = activeVisMode === "all" ? "city" : activeVisMode;
        if (!window.matchesObserverHemisphereFilter(it, checkMode)) return false;
      }
      if (window.AstroLabCore && typeof window.AstroLabCore.evaluateScopeSuitability === "function") {
        const ev = window.AstroLabCore.evaluateScopeSuitability(it, activeScope);
        return Boolean(ev && ev.status === "ok");
      }
      return true;
    });
    const pool = (strictlySuitable.length > 0 ? strictlySuitable : allItems).slice();

    // Тасование Фишера — Йейтса с использованием crypto.getRandomValues для 100% неповторяющегося рандома
    for (let i = pool.length - 1; i > 0; i--) {
      let rVal = Math.random();
      if (window.crypto && typeof window.crypto.getRandomValues === "function") {
        const u32 = new Uint32Array(1);
        window.crypto.getRandomValues(u32);
        rVal = u32[0] / 4294967296;
      }
      const j = Math.floor(rVal * (i + 1));
      const tmp = pool[i];
      pool[i] = pool[j];
      pool[j] = tmp;
    }
    return pool;
  }

  function runUniverseLuckGachaSpin() {
    const modal = document.getElementById("universeLuckModal");
    if (!modal) return;
    clearLuckSpinTimers();
    UniverseLuckGachaAudio.stopAll();
    syncAllModule14Translations();

    const urgModal = document.getElementById("urgentStarsModal");
    if (urgModal && urgModal.classList.contains("open")) {
      urgModal.classList.remove("open");
    }

    modal.classList.add("open");
    document.documentElement.classList.add("modal-open");
    document.body.classList.add("modal-open");

    const dossierEl = document.getElementById("luckWinnerDossier");
    const reelConEl = document.getElementById("gachaReelCon");
    const reelStarEl = document.getElementById("gachaReelStar");
    const reelTypeEl = document.getElementById("gachaReelType");
    const tickerEl = document.getElementById("gachaTofuTicker");
    const wishEl = document.getElementById("luckClearSkiesWish");
    const vsxLink = document.getElementById("linkLuckStarVsx");
    const acceptBtn = document.getElementById("btnAcceptUniverseLuckTarget");
    const actionsWrap = document.getElementById("luckModalWinnerActionsWrap");

    // ПУНКТ 2: Во время вращения барабана ПОЛНОСТЬЮ скрываем ссылку на AAVSO и кнопку перехода,
    // чтобы никогда не отображалась ссылка на постороннюю или старую звезду!
    if (dossierEl) dossierEl.style.display = "none";
    if (actionsWrap) actionsWrap.style.display = "none";
    if (vsxLink) {
      vsxLink.style.display = "none";
      vsxLink.removeAttribute("href");
    }
    if (acceptBtn) {
      acceptBtn.style.display = "none";
    }
    if (tickerEl) tickerEl.innerHTML = trM14("wheelSpinningTicker");
    if (wishEl) wishEl.textContent = trM14("luckShortWishText");

    const scopeModel = window._currentScopeModel || document.getElementById("headerScopeSelect")?.value || "S50";
    const shuffledPool = getShuffledUrgentStarsPool(scopeModel);
    if (shuffledPool.length === 0) return;

    // Каждый запуск берёт случайный набор из 12 срочных звёзд и заранее кэширует их локализованные подписи и спрайт барабана
    const spinSectorItems = [];
    for (let i = 0; i < 12; i++) {
      spinSectorItems.push(shuffledPool[i % shuffledPool.length]);
    }
    const targetSectorIdx = Math.floor(Math.random() * 12);
    const winnerItem = spinSectorItems[targetSectorIdx];
    _lastSelectedWinnerItem = winnerItem;
    _currentWheelSectorLabels = spinSectorItems.map(it => formatShortStarSectorLabel(it.star));

    // Предварительно вычисляем локализованные строки для 12 секторов ДО старта анимации (0 вызовов regex во время вращения!)
    const precomputedSectorTelemetry = spinSectorItems.map(it => {
      const locIt = ((typeof window.getLocalizedCatalogItem === "function") ? window.getLocalizedCatalogItem(it) : null) || it;
      return {
        con: locIt.con || it.con || "—",
        star: it.star || "—",
        prio: locIt.priority || it.priority || "—"
      };
    });

    // Предварительно прогреваем офскрин-спрайты барабана, фона и ракеты ДО первого кадра анимации
    const dprWarm = Math.min(2, Math.max(1.5, window.devicePixelRatio || 1.5));
    getOrBuildWheelStaticBackground(680, 330, dprWarm);
    getOrBuildWheelDrumSprite(dprWarm, _currentWheelSectorLabels);
    getOrBuildWheelCenterAndRocketOverlay(680, 330, dprWarm);
    renderLuShuCelestialWheel(0, 0, false, "", _currentWheelSectorLabels);

    const secStep = (Math.PI * 2) / 12;
    const totalRotation = Math.PI * 2 * 9 + ((12 - targetSectorIdx) % 12) * secStep;
    const durationMs = 7200;
    let animStartTime = null;
    let prevSectorTick = -1;
    let lastDomUpdateTs = 0;
    let isFinalized = false;

    UniverseLuckGachaAudio.startAnimeWheelMelody();

    function finalizeWheelSpin() {
      if (isFinalized) return;
      isFinalized = true;
      if (_wheelAnimFrameId) {
        cancelAnimationFrame(_wheelAnimFrameId);
        _wheelAnimFrameId = null;
      }
      _forceStopWheelSpinFn = null;

      renderLuShuCelestialWheel(totalRotation, targetSectorIdx, true, winnerItem.star, _currentWheelSectorLabels);
      UniverseLuckGachaAudio.playJackpotFanfare();
      startLuckFireworksAnimation();

      const winTel = precomputedSectorTelemetry[targetSectorIdx] || { con: winnerItem.con, star: winnerItem.star, prio: winnerItem.priority };
      if (reelConEl) reelConEl.textContent = winTel.con;
      if (reelStarEl) reelStarEl.textContent = winTel.star;
      if (reelTypeEl) reelTypeEl.textContent = winTel.prio;

      if (tickerEl) {
        tickerEl.innerHTML = trM14("wheelWinnerTickerFmt").replace("{star}", winnerItem.star);
      }

      const d = buildScientificStarDossier(winnerItem);
      const titleEl = document.getElementById("luckWinnerStarTitle");
      const subEl = document.getElementById("luckWinnerSubMeta");
      const descEl = document.getElementById("luckDossierDesc");
      const urgEl = document.getElementById("luckDossierUrgency");
      const reqEl = document.getElementById("luckDossierRequester");
      const seekEl = document.getElementById("luckDossierSeek");

      if (titleEl) titleEl.textContent = d.title;
      if (subEl) subEl.textContent = d.subMeta;
      if (descEl) descEl.textContent = d.desc;
      if (urgEl) urgEl.textContent = d.urgency;
      if (reqEl) reqEl.textContent = d.requester;
      if (seekEl) seekEl.textContent = d.seek;
      if (wishEl) wishEl.textContent = trM14("luckShortWishText");

      if (vsxLink) {
        vsxLink.href = `https://www.aavso.org/vsx/index.php?view=results.get&ident=${encodeURIComponent(winnerItem.star)}`;
        vsxLink.textContent = `${trM14("btnOpenStarInVsx").replace(" ↗", "")} (${winnerItem.star}) ↗`;
        vsxLink.style.display = "inline-flex";
      }
      if (acceptBtn) {
        acceptBtn.style.display = "inline-flex";
      }
      if (actionsWrap) {
        actionsWrap.style.display = "flex";
      }
      if (dossierEl) dossierEl.style.display = "flex";

      if (typeof window.selectRadarOrUrgentTarget === "function") {
        window.selectRadarOrUrgentTarget(
          winnerItem.star,
          winnerItem.ra.toFixed(6),
          winnerItem.dec.toFixed(6),
          winnerItem.chart,
          winnerItem.kname,
          winnerItem.kmag
        );
      } else {
        const stEl = document.getElementById("starid");
        if (stEl) stEl.value = winnerItem.star;
      }

      triggerStarIdCasinoJackpotBlink(6000);

      const btnFetch = document.getElementById("btnFetchAll");
      if (btnFetch && !btnFetch.disabled) {
        btnFetch.click();
      }
    }

    _forceStopWheelSpinFn = finalizeWheelSpin;

    function animateWheelFrame(now) {
      if (isFinalized) return;
      const safeNow = (typeof now === "number" && Number.isFinite(now)) ? now : performance.now();
      if (animStartTime === null) animStartTime = safeNow;
      const elapsed = Math.max(0, safeNow - animStartTime);
      const t = Math.min(1, Math.max(0, elapsed / durationMs));
      // Плавная физическая кривая замедления со степенью 2.75 (без многосекундного субпиксельного «ползания» в конце!)
      const eased = 1 - Math.pow(1 - t, 2.75);
      const currentRot = totalRotation * eased;

      const currentTopSector = (((-Math.round(currentRot / secStep)) % 12) + 12) % 12;
      if (currentTopSector !== prevSectorTick) {
        prevSectorTick = currentTopSector;
        // Обновляем текстовые плашки телеметрии не чаще чем раз в 80 мс, чтобы не вызывать лишний DOM reflow
        if (safeNow - lastDomUpdateTs >= 80 || t > 0.82) {
          lastDomUpdateTs = safeNow;
          const tel = precomputedSectorTelemetry[currentTopSector];
          if (tel) {
            if (reelConEl) reelConEl.textContent = tel.con;
            if (reelStarEl) reelStarEl.textContent = tel.star;
            if (reelTypeEl) reelTypeEl.textContent = tel.prio;
          }
        }
      }

      renderLuShuCelestialWheel(currentRot, currentTopSector, t >= 1, t >= 1 ? winnerItem.star : "", _currentWheelSectorLabels);

      if (t < 1) {
        _wheelAnimFrameId = requestAnimationFrame(animateWheelFrame);
      } else {
        finalizeWheelSpin();
      }
    }

    _wheelAnimFrameId = requestAnimationFrame(animateWheelFrame);
  }
  window.runUniverseLuckGachaSpin = runUniverseLuckGachaSpin;

  // [RU] Глобальный метод обновления 12 секторов барабана под выбранный телескоп и широту города
  // [EN] Global helper to refresh the 12 wheel sectors for active telescope & observer latitude
  function refreshWheelStarsForActiveScope(scopeModel) {
    try {
      const pool = typeof getShuffledUrgentStarsPool === "function" ? getShuffledUrgentStarsPool(scopeModel) : [];
      if (Array.isArray(pool) && pool.length > 0) {
        const picked = [];
        for (let i = 0; i < 12; i++) {
          const item = pool[i % pool.length];
          picked.push(formatShortStarSectorLabel(item.star));
        }
        _currentWheelSectorLabels = picked;
      }
      if (typeof renderLuShuCelestialWheel === "function") {
        renderLuShuCelestialWheel(0, 0, false, "", _currentWheelSectorLabels);
      }
    } catch (_) {}
  }
  window.refreshWheelStarsForActiveScope = refreshWheelStarsForActiveScope;

  function closeUniverseLuckModal() {
    clearLuckSpinTimers();
    UniverseLuckGachaAudio.stopAll();
    const modal = document.getElementById("universeLuckModal");
    if (modal) modal.classList.remove("open");
    document.documentElement.classList.remove("modal-open");
    document.body.classList.remove("modal-open");

    const acc1 = document.getElementById("accObserverStar");
    if (acc1) {
      if (window._accSimbadTimer) clearTimeout(window._accSimbadTimer);
      acc1.open = true;
    }
    const starEl = document.getElementById("starid");
    if (starEl) {
      triggerStarIdCasinoJackpotBlink(4500);
      try {
        starEl.scrollIntoView({ behavior: "smooth", block: "center" });
      } catch (_) {}
    }
  }
  window.closeUniverseLuckModal = closeUniverseLuckModal;

  ["btnTryUniverseLuck", "btnTryUniverseLuckFromModal", "btnSpinUniverseLuckAgain"].forEach(id => {
    document.getElementById(id)?.addEventListener("click", (e) => {
      e.stopPropagation();
      runUniverseLuckGachaSpin();
    });
  });
  // Клик по самому центральному медальону «奖» на колесе также запускает вращение!
  document.getElementById("luckWheelCanvas")?.addEventListener("click", (e) => {
    e.stopPropagation();
    if (_wheelAnimFrameId && typeof _forceStopWheelSpinFn === "function") {
      _forceStopWheelSpinFn();
    } else {
      runUniverseLuckGachaSpin();
    }
  });

  ["btnCloseUniverseLuckModal", "btnAcceptUniverseLuckTarget"].forEach(id => {
    document.getElementById(id)?.addEventListener("click", closeUniverseLuckModal);
  });
  document.getElementById("btnToggleLuckSound")?.addEventListener("click", (e) => {
    e.stopPropagation();
    UniverseLuckGachaAudio.toggleMute();
  });
  const luckModalEl = document.getElementById("universeLuckModal");
  if (luckModalEl) {
    luckModalEl.addEventListener("click", (e) => {
      if (e.target === luckModalEl) closeUniverseLuckModal();
    });
  }
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      if (aavsoDonateModalEl && aavsoDonateModalEl.classList.contains("open")) closeAavsoDonateModal();
      if (luckModalEl && luckModalEl.classList.contains("open")) closeUniverseLuckModal();
    }
  });

  // При смене языка интерфейса мгновенно переводим все подписи, тултипы и открытое досье звезды (Пункт 9)
  ["langSelect", "splashLangSelect"].forEach(selId => {
    document.getElementById(selId)?.addEventListener("change", () => {
      setTimeout(() => {
        syncAllModule14Translations();
        renderSkyAndMoonHeaderWidgets();
        if (_lastSelectedWinnerItem) {
          const d = buildScientificStarDossier(_lastSelectedWinnerItem);
          const titleEl = document.getElementById("luckWinnerStarTitle");
          const subEl = document.getElementById("luckWinnerSubMeta");
          const descEl = document.getElementById("luckDossierDesc");
          const urgEl = document.getElementById("luckDossierUrgency");
          const reqEl = document.getElementById("luckDossierRequester");
          const seekEl = document.getElementById("luckDossierSeek");
          const tickerEl = document.getElementById("gachaTofuTicker");
          const wishEl = document.getElementById("luckClearSkiesWish");
          if (titleEl) titleEl.textContent = d.title;
          if (subEl) subEl.textContent = d.subMeta;
          if (descEl) descEl.textContent = d.desc;
          if (urgEl) urgEl.textContent = d.urgency;
          if (reqEl) reqEl.textContent = d.requester;
          if (seekEl) seekEl.textContent = d.seek;
          if (tickerEl) tickerEl.innerHTML = trM14("wheelWinnerTickerFmt").replace("{star}", _lastSelectedWinnerItem.star);
          if (wishEl) wishEl.textContent = trM14("luckShortWishText");
        }
      }, 30);
    });
  });


  // ==========================================================================
  // 14.11. ИНТЕГРАЦИЯ: ЧИСТОТА НЕБА В ВЫБРАННОМ ГОРОДЕ (OPEN-METEO API, 10 МИН),
  //        ФАЗА И ВЫСОТА ЛУНЫ ПО РЕГИОНУ (USNO API v4.0) И ФИЛЬТР ПО ПОЛУШАРИЮ
  // ==========================================================================
  function getLocalizedCityName(rawCity) {
    const lang = (typeof currentLang !== "undefined") ? currentLang : (document.getElementById("langSelect")?.value || "ru");
    if (lang === "ru") return rawCity;
    const map = {
      "Москва": "Moscow",
      "Санкт-Петербург": "St. Petersburg",
      "Казань": "Kazan",
      "Нижний Новгород": "Nizhny Novgorod",
      "Екатеринбург": "Yekaterinburg",
      "Новосибирск": "Novosibirsk",
      "Сочи": "Sochi",
      "Владивосток": "Vladivostok",
      "Sydney (Австралия)": "Sydney (Australia)"
    };
    return map[rawCity] || rawCity;
  }

  function localizeCitySelectDropdown() {
    if (typeof window.__populateCountryAndCitySelectors === "function") {
      window.__populateCountryAndCitySelectors(false);
      return;
    }
    const sel = document.getElementById("headerCitySelect");
    if (!sel) return;
    Array.from(sel.options).forEach(opt => {
      if (!opt.value || opt.value === "custom") {
        if (opt.value === "custom") opt.textContent = trSky("optCustomCity") || "🔍 Other City...";
        return;
      }
      const p = opt.value.split(",");
      if (p.length >= 3) {
        const latNum = parseFloat(p[0]);
        const rawC = p.slice(2).join(",").trim();
        const locC = getLocalizedCityName(rawC);
        const hemiChar = latNum >= 0 ? "N" : "S";
        opt.textContent = `${locC} (${Math.abs(latNum).toFixed(1)}°${hemiChar})`;
      }
    });
  }
  window.localizeCitySelectDropdown = localizeCitySelectDropdown;

