  window._syncRadarApiFetchButton = function(hasKeyOverride = null) {
    const btn = document.getElementById("btnRadarFetchTargetToolApi");
    if (!btn) return;
    const hasKey = hasKeyOverride !== null ? Boolean(hasKeyOverride) : Boolean(_getStoredAavsoApiKey());
    btn.disabled = !hasKey;
    btn.title = hasKey ? t("tipRadarFetchApiReady") : t("tipRadarFetchApiDisabled");
  };

  const _btnRadarApi = document.getElementById("btnRadarFetchTargetToolApi");
  if (_btnRadarApi) {
    window._syncRadarApiFetchButton();
    _btnRadarApi.addEventListener("click", async () => {
      if (_btnRadarApi.disabled) return;
      _btnRadarApi.disabled = true;
      const prevTxt = _btnRadarApi.textContent;
      _btnRadarApi.textContent = "⏳ API...";
      try {
        const res = await window._syncLiveAavsoOnlineTargets();
        const nowStr = new Date().toLocaleTimeString(((typeof currentLang !== "undefined" ? currentLang : (window.STATE?.lang || "ru")) === "ru" ? "ru-RU" : "en-GB"), { hour: "2-digit", minute: "2-digit", second: "2-digit" });
        if (res && res.targetToolOk) {
          showIosNotification(
            t("toastRadarRefreshedTitle"),
            t("toastRadarRefreshedMsgFmt").replace("{count}", AAVSO_URGENT_CATALOGUE.length).replace("{time}", nowStr),
            t("apiKeyStatusActiveFmt").replace("{added}", res.targetToolAdded || 0).replace("{total}", AAVSO_URGENT_CATALOGUE.length),
            "ok"
          );
        } else if (res && res.targetToolError) {
          showIosNotification(t("lblAavsoApiKeyTitle"), res.targetToolError, "targettool.aavso.org", "warn");
        } else {
          showIosNotification(
            t("errOfflineStarTitle") || "No internet connection",
            t("errOfflineRadarApi") || "Could not fetch AAVSO Target Radar updates (no internet connection or server unreachable).",
            "targettool.aavso.org",
            "warn"
          );
        }
      } catch (_) {
        showIosNotification(
          t("errOfflineStarTitle") || "No internet connection",
          t("errOfflineRadarApi") || "Could not fetch AAVSO Target Radar updates (no internet connection or server unreachable).",
          "targettool.aavso.org",
          "warn"
        );
      } finally {
        _btnRadarApi.textContent = prevTxt;
        window._syncRadarApiFetchButton();
      }
    });
  }

  // 2. Scientific Light Curve Analysis Lab (100% local in-app algorithms: Lomb-Scargle, BLS, Phase Folding, Triggers)
  const AstroLabLightCurveLab = (function() {
    function _median(arr) {
      if (!arr.length) return 0;
      const s = [...arr].sort((a, b) => a - b);
      const m = Math.floor(s.length / 2);
      return (s.length % 2) ? s[m] : (s[m - 1] + s[m]) / 2;
    }

    function preprocessPoints(rawPts, opts = {}) {
      const band = String(opts.band || "ALL").toUpperCase();
      const sigmaClip = Boolean(opts.sigmaClip);
      const binMinutes = Number(opts.binMinutes || 0);

      let pts = (rawPts || []).filter(p => p && Number.isFinite(Number(p.jd)) && Number.isFinite(Number(p.mag))).map(p => ({
        jd: Number(p.jd),
        mag: Number(p.mag),
        merr: Math.max(0.002, Number(p.merr || 0.02)),
        band: (function(rawB){ const u = String(rawB || "").trim().toUpperCase(); return (!u || u === "/" || u === "-" || u === "NA" || u === "N/A" || u === "NONE" || u === "IRCUT" || u === "IR-CUT") ? "TG" : u; })(p.band || p.filt || p.filter),
        source: p.source || "LOCAL",
        obscode: p.obscode || "",
        layer: p.layer,
        label: p.label,
        utc: p.utc,
        idx: p.idx,
        isUser: p.isUser
      }));

      if (band !== "ALL") {
        pts = pts.filter(p => {
          const b = p.band.replace(".", "");
          return (band === "VIS") ? (b === "VIS" || b === "VISUAL") : (b === band);
        });
      }
      pts.sort((a, b) => a.jd - b.jd);

      if (sigmaClip && pts.length >= 6) {
        const med = _median(pts.map(p => p.mag));
        const mad = _median(pts.map(p => Math.abs(p.mag - med))) * 1.4826 || 0.05;
        const limit = Math.max(0.06, 3.0 * mad);
        pts = pts.filter(p => Math.abs(p.mag - med) <= limit);
      }

      if (binMinutes > 0 && pts.length >= 4) {
        const binDays = binMinutes / 1440.0;
        const t0 = pts[0].jd;
        const buckets = new Map();
        pts.forEach(p => {
          const idx = Math.floor((p.jd - t0) / binDays);
          if (!buckets.has(idx)) buckets.set(idx, []);
          buckets.get(idx).push(p);
        });
        const binned = [];
        buckets.forEach(group => {
          let wSum = 0, mSum = 0, tSum = 0;
          group.forEach(g => {
            const w = 1.0 / (g.merr * g.merr);
            wSum += w;
            mSum += g.mag * w;
            tSum += g.jd * w;
          });
          binned.push({
            jd: tSum / wSum,
            mag: mSum / wSum,
            merr: Math.sqrt(1.0 / wSum),
            band: group[0].band,
            source: group[0].source,
            obscode: group[0].obscode,
            layer: group.some(g => g.layer === "current") ? "current" : group[0].layer,
            label: group[0].label,
            utc: group[0].utc,
            idx: group[0].idx,
            isUser: group.some(g => g.isUser) || group[0].isUser
          });
        });
        binned.sort((a, b) => a.jd - b.jd);
        pts = binned;
      }
      return pts;
    }

    function estimateExtremum(pts) {
      if (!pts.length) return null;
      const mags = pts.map(p => p.mag);
      const n = mags.length;
      const mean = mags.reduce((a, b) => a + b, 0) / n;
      const med = _median(mags);
      const madSigma = Math.max(0.003, _median(mags.map(m => Math.abs(m - med))) * 1.4826);
      let variance = 0, m3 = 0;
      for (let i = 0; i < n; i++) {
        const d = mags[i] - mean;
        variance += d * d;
        m3 += d * d * d;
      }
      const rms = Math.sqrt(variance / Math.max(1, n - 1));
      const skewness = (rms > 1e-6) ? ((m3 / n) / Math.pow(rms, 3)) : 0;

      let brightest = pts[0], faintest = pts[0];
      for (let i = 1; i < n; i++) {
        if (pts[i].mag < brightest.mag) brightest = pts[i];
        if (pts[i].mag > faintest.mag) faintest = pts[i];
      }
      return {
        n,
        spanDays: Math.max(0, pts[n - 1].jd - pts[0].jd),
        meanMag: mean,
        medianMag: med,
        rmsMag: rms,
        madSigma,
        skewness,
        minMagBrightest: brightest.mag,
        maxMagFaintest: faintest.mag,
        amplitudeMag: faintest.mag - brightest.mag,
        tMaxJd: brightest.jd,
        tMinJd: faintest.jd,
        brightJumpMag: med - brightest.mag,
        faintDropMag: faintest.mag - med
      };
    }

    function computeBaluevFap(zNorm, mPts, fMax, tVar) {
      if (mPts < 6 || zNorm <= 0) return 1.0;
      if (zNorm >= 0.999999) return 0.0;
      const powSingle = Math.pow(Math.max(1e-12, 1.0 - zNorm), (mPts - 3.0) / 2.0);
      const W = Math.max(1.0, fMax * Math.sqrt(4.0 * Math.PI * Math.max(1e-6, tVar)));
      const tau = W * Math.pow(Math.max(1e-12, 1.0 - zNorm), (mPts - 4.0) / 2.0) * Math.sqrt(zNorm);
      const fap = 1.0 - Math.max(0.0, 1.0 - powSingle) * Math.exp(-tau);
      return Math.max(0.0, Math.min(1.0, fap));
    }

    function computeLombScargle(pts, opts = {}) {
      const n = pts.length;
      if (n < 10) return { bestPeriodDays: 0, bestPeriodHours: 0, peakPower: 0, baluevFap: 1.0, aliasRisk: false, significant: false };
      const t0 = pts[0].jd;
      const span = pts[n - 1].jd - t0;
      if (span <= 0.02) return { bestPeriodDays: 0, bestPeriodHours: 0, peakPower: 0, baluevFap: 1.0, aliasRisk: false, significant: false };

      // Downsample if > 900 pts for < 35ms execution
      const step = Math.max(1, Math.floor(n / 900));
      const ts = [], ys = [], ws = [];
      let wTotal = 0;
      for (let i = 0; i < n; i += step) {
        const ti = pts[i].jd - t0;
        const merr = Math.max(0.002, Number(pts[i].merr || 0.02));
        const wi = 1.0 / (merr * merr);
        ts.push(ti);
        ys.push(pts[i].mag);
        ws.push(wi);
        wTotal += wi;
      }
      const m = ts.length;
      let yWMean = 0, tWMean = 0;
      for (let i = 0; i < m; i++) {
        yWMean += ws[i] * ys[i];
        tWMean += ws[i] * ts[i];
      }
      yWMean /= Math.max(1e-12, wTotal);
      tWMean /= Math.max(1e-12, wTotal);

      let yVarW = 0, tVar = 0;
      const yc = new Array(m);
      for (let i = 0; i < m; i++) {
        const dy = ys[i] - yWMean;
        const dt = ts[i] - tWMean;
        yc[i] = dy;
        yVarW += ws[i] * dy * dy;
        tVar += (ws[i] / wTotal) * dt * dt;
      }
      if (yVarW < 1e-9) return { bestPeriodDays: 0, bestPeriodHours: 0, peakPower: 0, baluevFap: 1.0, aliasRisk: false, significant: false };

      const minP = Math.max(0.03, Math.min(0.08, span / 20));
      const maxP = Math.max(minP * 2, Math.min(span * 1.15, 250.0));
      const fMin = 1.0 / maxP;
      const fMax = 1.0 / minP;
      // VanderPlas Sec VII.1: oversample >= 5x peak width 1/T -> df <= 1/(5*span)
      const nFreqTarget = Math.ceil(5.0 * span * (fMax - fMin));
      const nFreq = Math.min(1800, Math.max(240, nFreqTarget));
      const df = (fMax - fMin) / nFreq;

      let bestPower = 0;
      let bestFreq = fMin;
      const TWO_PI = 2 * Math.PI;

      // Floating-Mean & 1/MERR^2 Weighted Generalized Lomb-Scargle (Zechmeister & Kurster 2009 / VanderPlas VI.1-VI.2)
      for (let k = 0; k <= nFreq; k++) {
        const f = fMin + k * df;
        const w = TWO_PI * f;
        let C = 0, S = 0, YC = 0, YS = 0, CC = 0, SS = 0, CS = 0;
        for (let i = 0; i < m; i++) {
          const wn = ws[i] / wTotal;
          const arg = w * ts[i];
          const ca = Math.cos(arg);
          const sa = Math.sin(arg);
          C += wn * ca;
          S += wn * sa;
          YC += wn * yc[i] * ca;
          YS += wn * yc[i] * sa;
          CC += wn * ca * ca;
          SS += wn * sa * sa;
          CS += wn * ca * sa;
        }
        const YY = yVarW / wTotal;
        const CCh = CC - C * C;
        const SSh = SS - S * S;
        const CSh = CS - C * S;
        const tau = Math.atan2(2 * CSh, CCh - SSh) / (2 * w);
        const cosT = Math.cos(w * tau);
        const sinT = Math.sin(w * tau);
        const YC_t = YC * cosT + YS * sinT;
        const YS_t = YS * cosT - YC * sinT;
        const CC_t = 0.5 * (CCh + SSh) + 0.5 * (CCh - SSh) * Math.cos(2 * w * tau) + CSh * Math.sin(2 * w * tau);
        const SS_t = (CCh + SSh) - CC_t;
        const pwr = ((YC_t * YC_t) / Math.max(1e-12, CC_t) + (YS_t * YS_t) / Math.max(1e-12, SS_t)) / Math.max(1e-12, YY);
        if (pwr > bestPower) {
          bestPower = pwr;
          bestFreq = f;
        }
      }

      const mult = (Number(opts.periodMultiplier) === 2) ? 2.0 : 1.0;
      const bestPeriodDays = (1.0 / bestFreq) * mult;
      const peakNorm = Math.min(0.999999, Math.max(0.0, bestPower));
      const baluevFap = computeBaluevFap(peakNorm, m, fMax, tVar);
      const aliasRisk = span < bestPeriodDays || (bestPeriodDays > 0.45 && bestPeriodDays < 1.15 && span < 3.0);

      return {
        bestPeriodDays,
        bestPeriodHours: bestPeriodDays * 24.0,
        peakPower: peakNorm,
        baluevFap,
        aliasRisk,
        significant: peakNorm >= 0.30 && baluevFap <= 0.05 && m >= 12
      };
    }

    function computeBLS(pts, stats) {
      if (!pts || pts.length < 12 || !stats) {
        return { depthMag: 0, snr: 0, isBoxDip: false, midTransitJd: 0 };
      }
      // Evaluate box-shaped dip against upper baseline (median of brightest 70% of points)
      const sortedMags = pts.map(p => p.mag).sort((a, b) => a - b);
      const baseCut = Math.max(4, Math.floor(sortedMags.length * 0.7));
      const baseSlice = sortedMags.slice(0, baseCut);
      const baseMed = _median(baseSlice);
      const baseSigma = Math.max(0.0025, _median(baseSlice.map(v => Math.abs(v - baseMed))) * 1.4826);

      // Find contiguous faint dip points (> baseMed + 2.5*baseSigma)
      let bestDipPts = [];
      let curDip = [];
      for (let i = 0; i < pts.length; i++) {
        if (pts[i].mag > baseMed + 2.5 * baseSigma) {
          curDip.push(pts[i]);
        } else {
          if (curDip.length > bestDipPts.length) bestDipPts = curDip;
          curDip = [];
        }
      }
      if (curDip.length > bestDipPts.length) bestDipPts = curDip;

      if (bestDipPts.length < 3) {
        return { depthMag: 0, snr: 0, isBoxDip: false, midTransitJd: 0 };
      }
      const dipMed = _median(bestDipPts.map(p => p.mag));
      const depthMag = Math.max(0, dipMed - baseMed);
      const snr = (depthMag / baseSigma) * Math.sqrt(bestDipPts.length);
      const midTransitJd = (bestDipPts[0].jd + bestDipPts[bestDipPts.length - 1].jd) / 2.0;
      const dipFrac = bestDipPts.length / pts.length;
      return {
        depthMag,
        snr,
        dipFrac,
        baseSigma,
        midTransitJd,
        isBoxDip: depthMag >= 0.005 && snr >= 4.5 && dipFrac <= 0.40
      };
    }

    function computePhotometryMetrics(pts, opts = {}) {
      const snrs = (pts || []).map(p => 1.0857 / Math.max(0.002, Number(p.merr || 0.02)));
      const medianSnr = snrs.length ? _median(snrs) : 0;
      const snrTier = medianSnr >= 100 ? "EXOPLANET" : (medianSnr >= 25 ? "VARIABLE" : "LOW");

      // Mironov P1: Bouguer airmass correlation r(MAG, M(z))
      const airPts = (pts || []).filter(p => Number.isFinite(Number(p.airmass)) && Number(p.airmass) >= 1.0 && Number(p.airmass) <= 6.0);
      let bouguerCorr = null;
      let bouguerWarn = false;
      if (airPts.length >= 8) {
        const xs = airPts.map(p => Number(p.airmass));
        const ys = airPts.map(p => Number(p.mag));
        const mx = xs.reduce((a, b) => a + b, 0) / xs.length;
        const my = ys.reduce((a, b) => a + b, 0) / ys.length;
        let num = 0, dx2 = 0, dy2 = 0;
        for (let i = 0; i < xs.length; i++) {
          const dx = xs[i] - mx, dy = ys[i] - my;
          num += dx * dy; dx2 += dx * dx; dy2 += dy * dy;
        }
        if (dx2 > 1e-6 && dy2 > 1e-8) {
          bouguerCorr = num / Math.sqrt(dx2 * dy2);
          bouguerWarn = Math.abs(bouguerCorr) >= 0.72;
        }
      }

      // Mironov P2: Scintillation warning if EXP < 10 s
      const expSec = Number(opts.expSec || 0);
      const scintillationWarn = expSec > 0 && expSec < 10;

      // Meeus (1998): Geocentric JD -> Heliocentric JD (HJD) light-time correction (±8.3 min max)
      function computeHeliocentricJd(jd, raDeg, decDeg) {
        if (!Number.isFinite(jd) || !Number.isFinite(raDeg) || !Number.isFinite(decDeg)) return jd;
        const d = jd - 2451545.0;
        const deg2rad = Math.PI / 180.0;
        const g = (357.5291 + 0.98560028 * d) * deg2rad;
        const q = (280.459 + 0.98564736 * d) % 360;
        const L = (q + 1.915 * Math.sin(g) + 0.020 * Math.sin(2 * g)) * deg2rad;
        const R = 1.00014 - 0.01671 * Math.cos(g) - 0.00014 * Math.cos(2 * g);
        const eps = (23.4393 - 0.00000036 * d) * deg2rad;
        const sinDecSun = Math.sin(eps) * Math.sin(L);
        const decSun = Math.asin(sinDecSun);
        const raSun = Math.atan2(Math.cos(eps) * Math.sin(L), Math.cos(L));
        const ra = raDeg * deg2rad;
        const dec = decDeg * deg2rad;
        const cosTheta = Math.sin(dec) * Math.sin(decSun) + Math.cos(dec) * Math.cos(decSun) * Math.cos(ra - raSun);
        // Light-time 1 AU = 0.0057755183 days (~499.005 s)
        return jd - 0.0057755183 * R * cosTheta;
      }

      // Budding & Demircan: O-C (Observed minus Calculated, with JD -> HJD correction when RA/Dec known)
      let oMinusCDays = null;
      let oMinusCMins = null;
      let oMinusCHeliocentric = false;
      const catP = Number(opts.catalogPeriodDays || 0);
      const catE = Number(opts.catalogEpochJd || 0);
      const obsT = Number(opts.observedExtremumJd || 0);
      const raDegOpt = Number(opts.raDeg);
      const decDegOpt = Number(opts.decDeg);
      if (catP > 0 && catE > 2400000 && obsT > 2400000) {
        let obsAligned = obsT;
        if (Number.isFinite(raDegOpt) && Number.isFinite(decDegOpt)) {
          obsAligned = computeHeliocentricJd(obsT, raDegOpt, decDegOpt);
          oMinusCHeliocentric = true;
        }
        const E = Math.round((obsAligned - catE) / catP);
        oMinusCDays = obsAligned - (catE + E * catP);
        oMinusCMins = oMinusCDays * 1440.0;
      }

      return { medianSnr, snrTier, bouguerCorr, bouguerWarn, scintillationWarn, oMinusCDays, oMinusCMins, oMinusCHeliocentric };
    }

    // Unified Quality Gate for Lab-Only sessions before allowing AAVSO export/reminders
    function evaluateSessionAavsoEligibility(rawPts, opts = {}) {
      const valid = (rawPts || []).filter(p =>
        p && Number.isFinite(Number(p.jd)) && Number(p.jd) > 2400000 &&
        Number.isFinite(Number(p.mag)) && Number(p.mag) > -2 && Number(p.mag) < 25 &&
        Number.isFinite(Number(p.merr || 0.02)) && Number(p.merr || 0.02) > 0 && Number(p.merr || 0.02) <= 0.35
      );
      if (valid.length < 5) {
        return { eligible: false, reasonKey: "qgTooFewPts", reasonFallback: "Too few valid points (< 5)" };
      }
      const clean = preprocessPoints(valid, { band: "ALL", sigmaClip: true, binMinutes: 0 });
      if (clean.length < 5 || (clean.length / valid.length) < 0.45) {
        return { eligible: false, reasonKey: "qgHighOutliers", reasonFallback: "Excessive outliers (>55% rejected)" };
      }
      const metrics = computePhotometryMetrics(clean, opts);
      if (metrics.medianSnr < 10) {
        return { eligible: false, reasonKey: "qgLowSnr", reasonFallback: `Low SNR (${metrics.medianSnr.toFixed(0)} < 10)` };
      }
      if (opts.calibrationBlocked) {
        return { eligible: false, reasonKey: "qgCalibFail", reasonFallback: "Calibration Guard failed (saturation / ref stars)" };
      }
      return { eligible: true, reasonKey: "qgPass", reasonFallback: "Ready for AAVSO" };
    }

    function analyze(rawPts, opts = {}) {
      const pts = preprocessPoints(rawPts, opts);
      const stats = estimateExtremum(pts);
      const lang = (typeof currentLang !== "undefined") ? currentLang : "ru";
      const isRu = lang === "ru";

      if (!stats || pts.length < 8) {
        return {
          ok: false,
          count: pts.length,
          stats,
          ls: { bestPeriodDays: 0, bestPeriodHours: 0, peakPower: 0, significant: false },
          bls: { depthMag: 0, snr: 0, isBoxDip: false, midTransitJd: 0 },
          triggers: [{
            code: "INSUFFICIENT_DATA",
            icon: "ℹ️",
            confidence: 0,
            title: isRu ? "Недостаточно точек для анализа" : "Insufficient points for analysis",
            reason: isRu ? "Загрузите CSV Seestar или расширьте окно AAVSO AID (нужно ≥ 8 точек)." : "Load a Seestar CSV or widen the AAVSO AID window (need ≥ 8 points)."
          }]
        };
      }

      const ls = computeLombScargle(pts, opts);
      const metrics = computePhotometryMetrics(pts, Object.assign({}, opts, { observedExtremumJd: stats.tMinJd }));
      const bls = computeBLS(pts, stats);
      const triggers = [];

      // Trigger 1: Outburst / Nova / Dwarf Nova (sudden bright jump above quiescence)
      if (stats.brightJumpMag >= 1.0 && (stats.brightJumpMag / stats.madSigma) >= 4.5 && stats.skewness < -0.5) {
        const conf = Math.min(96, Math.round(58 + stats.brightJumpMag * 12));
        triggers.push({
          code: "OUTBURST_NOVA",
          icon: "💥",
          confidence: conf,
          title: isRu ? "Вспышка Новой / Карликовой новой (UG / N)" : "Nova / Dwarf Nova Outburst (UG / N)",
          reason: isRu
            ? `Резкий рост блеска на Δm = ${stats.brightJumpMag.toFixed(2)} mag выше базового уровня (${stats.medianMag.toFixed(2)}m) с отрицательной асимметрией (${stats.skewness.toFixed(2)}).`
            : `Sudden brightening Δm = ${stats.brightJumpMag.toFixed(2)} mag above baseline (${stats.medianMag.toFixed(2)}m), skewness ${stats.skewness.toFixed(2)}.`
        });
      }

      // Trigger 2: Exoplanet Transit (flat baseline + shallow U/box dip 0.005-0.08 mag)
      if (bls.isBoxDip && bls.depthMag >= 0.005 && bls.depthMag <= 0.08 && bls.baseSigma <= 0.03) {
        const conf = Math.min(92, Math.round(50 + bls.snr * 4.5));
        triggers.push({
          code: "EXOPLANET_TRANSIT",
          icon: "🪐",
          confidence: conf,
          title: isRu ? "Возможный транзит экзопланеты (EP)" : "Exoplanet Transit Candidate (EP)",
          reason: isRu
            ? `Обнаружен неглубокий П-образный провал BLS: глубина ${(bls.depthMag * 1000).toFixed(1)} mmag (SNR ${bls.snr.toFixed(1)}), середина JD ${bls.midTransitJd.toFixed(4)}.`
            : `Shallow box-shaped BLS dip detected: depth ${(bls.depthMag * 1000).toFixed(1)} mmag (SNR ${bls.snr.toFixed(1)}), mid-transit JD ${bls.midTransitJd.toFixed(4)}.`
        });
      }

      // Trigger 3: Eclipsing Binary (EA / EB / EW — deep sharp minima below plateau)
      if ((stats.faintDropMag >= 0.18 && stats.skewness >= 0.55) || (bls.isBoxDip && bls.depthMag >= 0.15)) {
        const conf = Math.min(95, Math.round(55 + Math.min(35, stats.faintDropMag * 28 + Math.max(0, stats.skewness) * 10)));
        triggers.push({
          code: "ECLIPSING_BINARY",
          icon: "🌑",
          confidence: conf,
          title: isRu ? "Затменная двойная звезда (EA / EB / EW)" : "Eclipsing Binary Star (EA / EB / EW)",
          reason: isRu
            ? `Выраженный провал блеска вниз от плато на Δm = ${Math.max(stats.faintDropMag, bls.depthMag).toFixed(2)} mag (асимметрия +${stats.skewness.toFixed(2)}), минимум JD ${stats.tMinJd.toFixed(4)}.`
            : `Sharp downward eclipse dip Δm = ${Math.max(stats.faintDropMag, bls.depthMag).toFixed(2)} mag below plateau (skew +${stats.skewness.toFixed(2)}), min JD ${stats.tMinJd.toFixed(4)}.`
        });
      }

      // Trigger 4: Pulsating Variable (Lomb-Scargle significant period + continuous oscillation)
      if (ls.significant && stats.amplitudeMag >= 0.08 && Math.abs(stats.skewness) < 1.2) {
        const pStr = ls.bestPeriodDays < 2.0 ? `${ls.bestPeriodHours.toFixed(2)} ч (${ls.bestPeriodDays.toFixed(4)} d)` : `${ls.bestPeriodDays.toFixed(3)} d`;
        const conf = Math.min(96, Math.round(45 + ls.peakPower * 52));
        triggers.push({
          code: "PULSATING",
          icon: "💓",
          confidence: conf,
          title: isRu ? "Пульсирующая переменная (HADS / RR Lyr / δ Sct / Cep)" : "Pulsating Variable (HADS / RR Lyr / δ Sct / Cep)",
          reason: isRu
            ? `Устойчивый пик периодограммы Ломба–Скаргла: P ≈ ${pStr} (мощность ${(ls.peakPower * 100).toFixed(0)}%), амплитуда Δm = ${stats.amplitudeMag.toFixed(2)} mag.`
            : `Strong Lomb–Scargle periodogram peak: P ≈ ${pStr} (power ${(ls.peakPower * 100).toFixed(0)}%), amplitude Δm = ${stats.amplitudeMag.toFixed(2)} mag.`
        });
      }

      if (triggers.length === 0) {
        triggers.push({
          code: "STABLE_OR_SHORT",
          icon: "🟢",
          confidence: 65,
          title: isRu ? "Спокойная фаза / короткий ряд наблюдений" : "Quiescent Baseline / Short Time Span",
          reason: isRu
            ? `Размах Δm = ${stats.amplitudeMag.toFixed(3)} mag, RMS = ${stats.rmsMag.toFixed(3)} mag за ${stats.spanDays.toFixed(2)} сут. Добавьте больше ночей или расширьте окно AAVSO AID.`
            : `Span Δm = ${stats.amplitudeMag.toFixed(3)} mag, RMS = ${stats.rmsMag.toFixed(3)} mag over ${stats.spanDays.toFixed(2)} d. Add more nights or widen AAVSO AID window.`
        });
      }

      triggers.sort((a, b) => b.confidence - a.confidence);
      return { ok: true, count: pts.length, stats, ls, bls, metrics, triggers };
    }

    function renderPhasePlotCanvas(canvas, pts, periodDays, epochJd, width, height) {
      if (!canvas || !pts || !pts.length || !periodDays || periodDays <= 0) return;
      const ctx = canvas.getContext("2d");
      const dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.round(width * dpr);
      canvas.height = Math.round(height * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      const isLight = document.body.getAttribute("data-theme") === "light";
      ctx.fillStyle = isLight ? "#f8fafc" : "#0b1224";
      ctx.fillRect(0, 0, width, height);

      const pad = { l: 64, r: 28, t: 44, b: 48 };
      const pw = Math.max(100, width - pad.l - pad.r);
      const ph = Math.max(100, height - pad.t - pad.b);

      const mags = pts.map(p => p.mag);
      const mMin = Math.min(...mags) - 0.08;
      const mMax = Math.max(...mags) + 0.08;
      const xOf = (phase) => pad.l + (phase / 2.0) * pw;
      const yOf = (mag) => pad.t + ((mag - mMin) / Math.max(0.02, mMax - mMin)) * ph;

      // Grid
      ctx.strokeStyle = isLight ? "rgba(15,23,42,0.10)" : "rgba(148,163,184,0.16)";
      ctx.lineWidth = 1;
      for (let phTick = 0; phTick <= 2.001; phTick += 0.25) {
        const x = xOf(phTick);
        ctx.beginPath(); ctx.moveTo(x, pad.t); ctx.lineTo(x, pad.t + ph); ctx.stroke();
        ctx.fillStyle = isLight ? "#475569" : "#94a3b8";
        ctx.font = "11px sans-serif";
        ctx.fillText(phTick.toFixed(2), x - 12, pad.t + ph + 18);
      }
      for (let i = 0; i <= 5; i++) {
        const mv = mMin + (i / 5) * (mMax - mMin);
        const y = yOf(mv);
        ctx.beginPath(); ctx.moveTo(pad.l, y); ctx.lineTo(pad.l + pw, y); ctx.stroke();
        ctx.fillStyle = isLight ? "#475569" : "#94a3b8";
        ctx.fillText(mv.toFixed(2), 10, y + 4);
      }

      // Plot points across 2 cycles (phase 0..2)
      const binSums = new Array(20).fill(0);
      const binCnts = new Array(20).fill(0);
      pts.forEach(p => {
        let ph0 = ((p.jd - epochJd) / periodDays) % 1.0;
        if (ph0 < 0) ph0 += 1.0;
        const bIdx = Math.min(19, Math.floor(ph0 * 20));
        binSums[bIdx] += p.mag;
        binCnts[bIdx] += 1;
        const isUser = p.source !== "AAVSO_AID_DELIM" && p.source !== "AAVSO_API_V2";
        const col = isUser ? "#f59e0b" : "#38bdf8";
        for (const shift of [0, 1]) {
          const x = xOf(ph0 + shift);
          const y = yOf(p.mag);
          const errPx = Math.min(24, (p.merr / Math.max(0.02, mMax - mMin)) * ph);
          ctx.strokeStyle = col;
          ctx.globalAlpha = 0.45;
          ctx.beginPath(); ctx.moveTo(x, y - errPx); ctx.lineTo(x, y + errPx); ctx.stroke();
          ctx.globalAlpha = 0.92;
          ctx.fillStyle = col;
          ctx.beginPath(); ctx.arc(x, y, isUser ? 3.5 : 2.8, 0, Math.PI * 2); ctx.fill();
        }
      });
      ctx.globalAlpha = 1.0;

      // Mean phase curve overlay
      ctx.strokeStyle = "#4ade80";
      ctx.lineWidth = 2.2;
      ctx.beginPath();
      let started = false;
      for (let shift = 0; shift <= 1; shift++) {
        for (let b = 0; b < 20; b++) {
          if (!binCnts[b]) continue;
          const x = xOf((b + 0.5) / 20 + shift);
          const y = yOf(binSums[b] / binCnts[b]);
          if (!started) { ctx.moveTo(x, y); started = true; } else { ctx.lineTo(x, y); }
        }
      }
      ctx.stroke();

      // Title
      ctx.fillStyle = isLight ? "#0f172a" : "#f8fafc";
      ctx.font = "bold 13px sans-serif";
      const pTxt = periodDays < 2.0 ? `${(periodDays * 24).toFixed(3)} h (${periodDays.toFixed(5)} d)` : `${periodDays.toFixed(4)} d`;
      ctx.fillText(`Phase Plot (φ ∈ [0, 2]) • P = ${pTxt} • Epoch JD ${epochJd.toFixed(4)} • N = ${pts.length}`, pad.l, 26);
    }

    function renderFilteredTimeSeriesCanvas(canvas, rawPts, cleanPts, opts, width, height) {
      if (!canvas) return;
      const ctx = canvas.getContext("2d");
      const dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.round(width * dpr);
      canvas.height = Math.round(height * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      const isLight = document.body.getAttribute("data-theme") === "light";
      ctx.fillStyle = isLight ? "#f8fafc" : "#0b1224";
      ctx.fillRect(0, 0, width, height);

      const pad = { l: 64, r: 28, t: 46, b: 48 };
      const pw = Math.max(100, width - pad.l - pad.r);
      const ph = Math.max(100, height - pad.t - pad.b);

      if (!cleanPts || cleanPts.length === 0) {
        ctx.fillStyle = "#94a3b8";
        ctx.font = "bold 15px sans-serif";
        ctx.fillText("No points match the selected Band / Binning / 3σ filter — switch Band to All or turn Binning Off.", 40, Math.round(height / 2));
        return;
      }

      const jds = cleanPts.map(p => p.jd);
      const mags = cleanPts.map(p => p.mag);
      const jdMin = Math.min(...jds);
      const jdMax = Math.max(...jds) + (Math.max(...jds) === jdMin ? 0.01 : 0);
      const mMin = Math.min(...mags) - 0.06;
      const mMax = Math.max(...mags) + 0.06;
      const xOf = (jd) => pad.l + ((jd - jdMin) / Math.max(1e-6, jdMax - jdMin)) * pw;
      const yOf = (mag) => pad.t + ((mag - mMin) / Math.max(0.02, mMax - mMin)) * ph;

      // Grid
      ctx.strokeStyle = isLight ? "rgba(15,23,42,0.10)" : "rgba(148,163,184,0.16)";
      ctx.lineWidth = 1;
      for (let i = 0; i <= 6; i++) {
        const jv = jdMin + (i / 6) * (jdMax - jdMin);
        const x = xOf(jv);
        ctx.beginPath(); ctx.moveTo(x, pad.t); ctx.lineTo(x, pad.t + ph); ctx.stroke();
        ctx.fillStyle = isLight ? "#475569" : "#94a3b8";
        ctx.font = "11px sans-serif";
        ctx.fillText(jv.toFixed(3), x - 22, pad.t + ph + 18);
      }
      for (let i = 0; i <= 5; i++) {
        const mv = mMin + (i / 5) * (mMax - mMin);
        const y = yOf(mv);
        ctx.beginPath(); ctx.moveTo(pad.l, y); ctx.lineTo(pad.l + pw, y); ctx.stroke();
        ctx.fillStyle = isLight ? "#475569" : "#94a3b8";
        ctx.fillText(mv.toFixed(2), 10, y + 4);
      }

      // Faint raw points in background for visual comparison when binning/clipping is active
      if (rawPts && rawPts.length > cleanPts.length) {
        ctx.fillStyle = isLight ? "rgba(100,116,139,0.22)" : "rgba(148,163,184,0.20)";
        rawPts.forEach(p => {
          if (p.jd < jdMin || p.jd > jdMax || p.mag < mMin || p.mag > mMax) return;
          ctx.beginPath();
          ctx.arc(xOf(p.jd), yOf(p.mag), 2.0, 0, Math.PI * 2);
          ctx.fill();
        });
      }

      // Filtered/binned points + error bars + connecting trend line
      ctx.strokeStyle = "rgba(74, 222, 128, 0.45)";
      ctx.lineWidth = 1.6;
      ctx.beginPath();
      cleanPts.forEach((p, idx) => {
        const x = xOf(p.jd), y = yOf(p.mag);
        if (idx === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      });
      ctx.stroke();

      cleanPts.forEach(p => {
        const x = xOf(p.jd), y = yOf(p.mag);
        const isAavso = (p.source === "AAVSO_WEBOBS" || p.source === "AAVSO_AID_DELIM" || p.source === "AAVSO_API_V2");
        const col = isAavso ? "#38bdf8" : "#4ade80";
        const errPx = Math.min(26, (p.merr / Math.max(0.02, mMax - mMin)) * ph);
        ctx.strokeStyle = col;
        ctx.globalAlpha = 0.55;
        ctx.beginPath(); ctx.moveTo(x, y - errPx); ctx.lineTo(x, y + errPx); ctx.stroke();
        ctx.globalAlpha = 0.95;
        ctx.fillStyle = col;
        ctx.beginPath(); ctx.arc(x, y, 3.6, 0, Math.PI * 2); ctx.fill();
      });
      ctx.globalAlpha = 1.0;

      // Active filter summary header
      const tags = [];
      if (opts.band && opts.band !== "ALL") tags.push(`Band: ${opts.band}`);
      if (opts.binMinutes > 0) tags.push(`Bin: ${opts.binMinutes} min`);
      if (opts.sigmaClip) tags.push("3σ Clip ON");
      ctx.fillStyle = isLight ? "#0f172a" : "#f8fafc";
      ctx.font = "bold 13px sans-serif";
      ctx.fillText(`Filtered Time Series (${tags.join(" • ")}) — ${cleanPts.length} pts (from ${rawPts.length} raw)`, pad.l, 26);
    }

    return { preprocessPoints, estimateExtremum, computeLombScargle, computeBLS, computePhotometryMetrics, evaluateSessionAavsoEligibility, analyze, renderPhasePlotCanvas, renderFilteredTimeSeriesCanvas };
  })();

  window.AstroLabLightCurveLab = AstroLabLightCurveLab;
  window._fpPhaseModeActive = false;
  window._fpDetectedPeriodDays = 0;
  window._fpDetectedEpochJd = 0;

  function _collectActiveFullPagePoints() {
    const sc = window._STATE_CURVES || null;
    const liveCurPts = (typeof window.parseCurrentCsvPoints === "function") ? window.parseCurrentCsvPoints() : [];
    const domStar = (document.getElementById("starid")?.value || "").trim();
    const catStar = (window.STATE && window.STATE.catalogStarName) ? String(window.STATE.catalogStarName).trim() : "";
    const activeStar = domStar || catStar || (sc && sc.star) || (liveCurPts.length > 0 ? liveCurPts[0].star : "");
    const livePastPts = (activeStar && typeof window.getPastConvertedPointsExcludingCurrent === "function")
      ? window.getPastConvertedPointsExcludingCurrent(activeStar, liveCurPts) : [];
    const aavsoPts = (sc && Array.isArray(sc.aavsoOtherPoints)) ? sc.aavsoOtherPoints : [];
    const userAavsoPts = (sc && Array.isArray(sc.aavsoUserPoints)) ? sc.aavsoUserPoints : [];
    const mode = (sc && sc.fullPageMode) ? sc.fullPageMode : "aavso_combined";
    const combined = (mode === "user_only")
      ? [...livePastPts, ...liveCurPts]
      : [...aavsoPts, ...userAavsoPts, ...livePastPts, ...liveCurPts];
    return { activeStar, points: combined };
  }

  window.runFullPageLightCurveAnalysis = function(customPoints = null) {
    const panel = document.getElementById("lcAnalysisResultPanel");
    const { activeStar, points } = customPoints ? { activeStar: "Test", points: customPoints } : _collectActiveFullPagePoints();
    const band = document.getElementById("fpBandFilterSelect")?.value || "TG";
    const binMinutes = Number(document.getElementById("fpBinningSelect")?.value || "0");
    const sigmaClip = Boolean(document.getElementById("chkFpSigmaClip")?.checked);

    const vsxItem = activeStar ? AAVSO_URGENT_CATALOGUE.find(it => it.star.toLowerCase() === activeStar.toLowerCase()) : null;
    const catPeriodDays = vsxItem && Number.isFinite(parseFloat(vsxItem.periodDays)) ? parseFloat(vsxItem.periodDays) : 0;
    const catEpochJd = vsxItem && Number.isFinite(parseFloat(vsxItem.epochJd)) ? parseFloat(vsxItem.epochJd) : 0;
    const mult = window._fpPeriodMultiplier === 2 ? 2 : 1;

    const starRaDeg = (vsxItem && Number.isFinite(parseFloat(vsxItem.ra)))
      ? parseFloat(vsxItem.ra)
      : ((window.STATE && Number.isFinite(Number(window.STATE.catalogRa))) ? Number(window.STATE.catalogRa) : NaN);
    const starDecDeg = (vsxItem && Number.isFinite(parseFloat(vsxItem.dec)))
      ? parseFloat(vsxItem.dec)
      : ((window.STATE && Number.isFinite(Number(window.STATE.catalogDec))) ? Number(window.STATE.catalogDec) : NaN);

    const res = AstroLabLightCurveLab.analyze(points, {
      band, binMinutes, sigmaClip,
      periodMultiplier: mult,
      catalogPeriodDays: catPeriodDays,
      catalogEpochJd: catEpochJd,
      raDeg: starRaDeg,
      decDeg: starDecDeg
    });
    if (res.ls && res.ls.bestPeriodDays > 0) {
      window._fpDetectedPeriodDays = res.ls.bestPeriodDays;
      window._fpDetectedEpochJd = (res.stats && res.stats.tMinJd) ? res.stats.tMinJd : 0;
    }

    if (typeof window.refreshLabUnsubmittedReminderBar === "function") {
      window.refreshLabUnsubmittedReminderBar(activeStar);
    }

    if (panel) {
      const isRu = ((document.getElementById("langSelect")?.value || window.currentLang || (typeof currentLang !== "undefined" ? currentLang : "ru")) === "ru");
      const vsxNote = vsxItem
        ? (isRu ? ` • Справка AAVSO VSX: <strong>${escapeHtml(vsxItem.type)}</strong>` : ` • AAVSO VSX Ref: <strong>${escapeHtml(vsxItem.type)}</strong>`)
        : "";
      const fapPct = (res.ls && typeof res.ls.baluevFap === "number")
        ? (res.ls.baluevFap < 0.0001 ? "< 0.01%" : `${(res.ls.baluevFap * 100).toFixed(2)}%`)
        : "";
      const pPill = (res.ls && res.ls.bestPeriodDays > 0)
        ? `<span class="lc-metric-pill">⏱ P${mult === 2 ? "×2" : ""} ≈ ${res.ls.bestPeriodDays < 2 ? res.ls.bestPeriodHours.toFixed(2) + " h" : res.ls.bestPeriodDays.toFixed(3) + " d"} (LS ${(res.ls.peakPower * 100).toFixed(0)}%)</span>` +
          (fapPct ? `<span class="lc-metric-pill">🎯 Baluev FAP ${fapPct}</span>` : "") +
          (res.ls.aliasRisk ? `<span class="lc-metric-pill" style="border-color:rgba(245,158,11,0.5);">⚠️ ${isRu ? "Риск сут. алиаса (T < P)" : "Diurnal alias risk (T < P)"}</span>` : "")
        : "";
      const m = res.metrics || {};
      const snrPill = (m.medianSnr > 0)
        ? `<span class="lc-metric-pill">📶 SNR ~${Math.round(m.medianSnr)}</span>`
        : "";
      const ocPill = (typeof m.oMinusCMins === "number" && Number.isFinite(m.oMinusCMins))
        ? `<span class="lc-metric-pill">🧭 O−C${m.oMinusCHeliocentric ? " (HJD)" : ""}: ${m.oMinusCMins >= 0 ? "+" : ""}${m.oMinusCMins.toFixed(1)} min</span>`
        : "";
      const bouguerPill = m.bouguerWarn
        ? `<span class="lc-metric-pill" style="border-color:rgba(245,158,11,0.5);">🌫️ ${isRu ? "Дрейф по M(z) (Бугер)" : "Airmass drift r=" + m.bouguerCorr.toFixed(2)}</span>`
        : "";
      const stPills = res.stats
        ? `<span class="lc-metric-pill">📊 N = ${res.count}</span>` +
          `<span class="lc-metric-pill">↕ Δm = ${res.stats.amplitudeMag.toFixed(3)} mag</span>` +
          `<span class="lc-metric-pill">📉 RMS = ${res.stats.rmsMag.toFixed(3)} mag</span>` +
          `<span class="lc-metric-pill">🔻 T_min JD ${res.stats.tMinJd.toFixed(4)}</span>` +
          snrPill + ocPill + bouguerPill
        : "";

      const foldBtn = (res.ls && res.ls.bestPeriodDays > 0)
        ? `<button type="button" class="ios-btn tiny" id="btnApplyDetectedPhaseFold" style="width:auto; padding:4px 11px; font-size:11px; font-weight:700;">🔄 ${isRu ? "Свернуть в фазовую кривую" : "Fold Phase Plot"} (P=${res.ls.bestPeriodDays.toFixed(4)}d)</button>`
        : "";

      panel.innerHTML = `
        <div style="display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:8px;">
          <div style="font-size:12.5px; font-weight:800;">🔬 ${isRu ? "Предварительная математическая диагностика формы кривой" : "Preliminary Light Curve Shape Diagnostics"}${vsxNote}</div>
          <div style="display:flex; align-items:center; gap:6px;">
            ${foldBtn}
            <button type="button" class="ios-btn secondary tiny" id="btnCloseLcAnalysisPanel" style="width:auto; padding:3px 9px; font-size:11px;">✕</button>
          </div>
        </div>
        <div class="lc-metrics-strip">${stPills}${pPill}</div>
        <div class="lc-analysis-grid">
          ${res.triggers.map((tr, i) => `
            <div class="lc-trigger-card ${i === 0 && tr.confidence >= 55 ? "primary-hit" : ""}">
              <div style="display:flex; justify-content:space-between; gap:6px; font-size:12px; font-weight:800;">
                <span>${tr.icon} ${escapeHtml(tr.title)}</span>
                ${tr.confidence > 0 ? `<span class="lc-trigger-conf">${tr.confidence}%</span>` : ""}
              </div>
              <div style="font-size:11.5px; color:var(--ios-text-secondary); margin-top:4px; line-height:1.4;">${escapeHtml(tr.reason)}</div>
            </div>
          `).join("")}
        </div>
      `;
      panel.style.display = "block";
      document.getElementById("btnCloseLcAnalysisPanel")?.addEventListener("click", () => { panel.style.display = "none"; });
      document.getElementById("btnApplyDetectedPhaseFold")?.addEventListener("click", () => {
        window._fpPhaseModeActive = true;
        window._renderFpPhaseOrTime();
      });
    }
    return res;
  };

  window._renderFpPhaseOrTime = function() {
    const toggleBtn = document.getElementById("btnFpTogglePhaseMode");
    if (toggleBtn) toggleBtn.textContent = window._fpPhaseModeActive ? t("btnFpTimeView") : t("btnFpPhaseView");
    const band = document.getElementById("fpBandFilterSelect")?.value || "TG";
    const binMinutes = Number(document.getElementById("fpBinningSelect")?.value || "0");
    const sigmaClip = Boolean(document.getElementById("chkFpSigmaClip")?.checked);
    const hasFilter = (band !== "ALL" || binMinutes > 0 || sigmaClip);

    const stickyColEl = document.getElementById("fullPageStickyYCol");
    if (!window._fpPhaseModeActive) {
      if (stickyColEl) stickyColEl.style.display = "block";
      if (typeof window.renderFullPageScrollableChart === "function") window.renderFullPageScrollableChart();
      return;
    }
    if (stickyColEl) stickyColEl.style.display = "none";
    const { points } = _collectActiveFullPagePoints();
    const cleanPts = AstroLabLightCurveLab.preprocessPoints(points, { band, binMinutes, sigmaClip });
    let period = window._fpDetectedPeriodDays;
    let epoch = window._fpDetectedEpochJd;
    if (!period || period <= 0) {
      const ls = AstroLabLightCurveLab.computeLombScargle(cleanPts);
      period = ls.bestPeriodDays || 0.1205;
      epoch = cleanPts.length ? cleanPts[0].jd : 0;
      window._fpDetectedPeriodDays = period;
      window._fpDetectedEpochJd = epoch;
    }
    const fpCanvas = document.getElementById("fullPageLightCurveCanvas");
    const scrollContainer = document.getElementById("fullPageLcScrollContainer");
    const innerWrap = document.getElementById("fullPageLcInnerWrap");
    if (fpCanvas && scrollContainer && innerWrap) {
      const wheelZoom = (window._CHART_ZOOM_STATE && window._CHART_ZOOM_STATE.fullPageLightCurveCanvas && window._CHART_ZOOM_STATE.fullPageLightCurveCanvas.scale) ? window._CHART_ZOOM_STATE.fullPageLightCurveCanvas.scale : 1;
      const phZoom = Math.min(8, Math.max(1, (parseFloat(document.getElementById("fullPageZoomSelect")?.value || "1") || 1) * wheelZoom));
      const w = Math.min(4800, Math.round(Math.max(720, (scrollContainer.clientWidth || 1060) - 16) * phZoom));
      const h = Math.max(460, (scrollContainer.clientHeight || 540) - 16);
      innerWrap.style.width = `${w}px`;
      innerWrap.style.height = `${h}px`;
      fpCanvas.style.width = `${w}px`;
      fpCanvas.style.height = `${h}px`;
      if (cleanPts.length >= 2) {
        AstroLabLightCurveLab.renderPhasePlotCanvas(fpCanvas, cleanPts, period, epoch, w, h);
      } else {
        const ctx = fpCanvas.getContext("2d");
        fpCanvas.width = w; fpCanvas.height = h;
        ctx.fillStyle = document.body.getAttribute("data-theme") === "light" ? "#f8fafc" : "#0b1224";
        ctx.fillRect(0, 0, w, h);
        ctx.fillStyle = "#94a3b8";
        ctx.font = "bold 15px sans-serif";
        ctx.fillText("Phase Plot: load a Seestar CSV or click 🔄 AID to load AAVSO points (need ≥ 2 points)", 40, Math.round(h / 2));
      }
    }
  };

  document.getElementById("btnRunLightCurveAnalysis")?.addEventListener("click", () => window.runFullPageLightCurveAnalysis());
  document.getElementById("btnFpTogglePhaseMode")?.addEventListener("click", () => {
    window._fpPhaseModeActive = !window._fpPhaseModeActive;
    window._renderFpPhaseOrTime();
  });
  ["fpBandFilterSelect", "fpBinningSelect", "chkFpSigmaClip"].forEach(id => {
    document.getElementById(id)?.addEventListener("change", () => {
      const panel = document.getElementById("lcAnalysisResultPanel");
      if (panel && panel.style.display !== "none") window.runFullPageLightCurveAnalysis();
      window._renderFpPhaseOrTime();
    });
  });
  async function _autoReloadAavsoForSelectedDays() {
    const days = Number(document.getElementById("fpDaysBackSelect")?.value || "180") || 180;
    const { activeStar } = _collectActiveFullPagePoints();
    if (!activeStar) return;
    const subEl = document.getElementById("fullPageLcSubtitle");
    const prevSub = subEl ? subEl.textContent : "";
    if (subEl) subEl.textContent = `⏳ Загрузка данных AAVSO за ${days} дн. (${activeStar})...`;
    try {
      if (window.AstroLabCurveLoaderV2) window.AstroLabCurveLoaderV2.start(activeStar, String(days));
      const resp = await _callBackendLiveAction("backend_fetch_aavso_light_curve", "fetch_aavso_light_curve", {
        star: activeStar,
        daysBack: days,
        obscode: document.getElementById("obscode")?.value || ""
      });
      const _scReload = window._STATE_CURVES;
      if (resp && resp.ok && _scReload) {
        _scReload.aavsoOtherPoints = resp.otherObserversPoints || [];
        _scReload.aavsoUserPoints = resp.userAavsoPoints || [];
        _scReload.aavsoHasEnoughData = (_scReload.aavsoOtherPoints.length + _scReload.aavsoUserPoints.length) > 0;
        if (window._aavsoCurveMemoryCache) window._aavsoCurveMemoryCache.clear();
        const panel = document.getElementById("lcAnalysisResultPanel");
        if (panel && panel.style.display !== "none") window.runFullPageLightCurveAnalysis();
        window._renderFpPhaseOrTime();
      }
    } catch (_) {
    } finally {
      if (window.AstroLabCurveLoaderV2) window.AstroLabCurveLoaderV2.stop();
      if (subEl && prevSub) subEl.textContent = prevSub;
    }
  }
  document.getElementById("fpDaysBackSelect")?.addEventListener("change", _autoReloadAavsoForSelectedDays);
  document.getElementById("fpXAxisUnitSelect")?.addEventListener("change", () => {
    window._renderFpPhaseOrTime();
  });

  if (typeof applyTranslations === "function") applyTranslations();
  window._syncRadarApiFetchButton();

